def local_state_dir():
    preferred = pathlib.Path.cwd() / ".napseer"
    legacy = pathlib.Path.cwd() / "napseer"
    if preferred.exists() or not legacy.exists():
        return preferred
    return legacy


def state_dir_status_payload():
    preferred = pathlib.Path.cwd() / ".napseer"
    legacy = pathlib.Path.cwd() / "napseer"
    active = AUTH_DIR
    if preferred.exists() and legacy.exists():
        message = "Both .napseer and legacy napseer directories exist; .napseer is active."
    elif active == legacy:
        message = "Legacy napseer directory is active because .napseer does not exist."
    else:
        message = ".napseer directory is active."
    return {
        "active_state_dir": str(active),
        "preferred_state_dir": str(preferred),
        "legacy_state_dir": str(legacy),
        "legacy_state_dir_active": active == legacy,
        "preferred_state_dir_exists": preferred.exists(),
        "legacy_state_dir_exists": legacy.exists(),
        "state_dir_message": message,
    }


def telemetry_state():
    try:
        if TELEMETRY_PATH.exists():
            data = json.loads(TELEMETRY_PATH.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return data
    except Exception:
        return {}
    return {}


def telemetry_enabled():
    env_value = os.environ.get("NAPSEER_TELEMETRY")
    if env_value is not None and env_value.strip().lower() in TELEMETRY_DISABLED_VALUES:
        return False
    return telemetry_state().get("enabled") is not False


def telemetry_install_id():
    if not telemetry_enabled():
        return ""
    state = telemetry_state()
    value = state.get("anonymous_install_id")
    if isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9_.:-]{16,80}", value):
        return value
    value = uuid.uuid4().hex
    state["anonymous_install_id"] = value
    state.setdefault("enabled", True)
    try:
        AUTH_DIR.mkdir(parents=True, exist_ok=True)
        TELEMETRY_PATH.write_text(json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        chmod_best_effort(TELEMETRY_PATH, 0o600)
    except Exception:
        return ""
    return value


def telemetry_safe_text(value, max_len=128):
    if value is None:
        return None
    text = str(value)
    text = TELEMETRY_SAFE_RE.sub("_", text).strip("_")
    if not text:
        return "unknown"
    return text[:max_len]


def telemetry_error_code(exc):
    cause = getattr(exc, "__cause__", None)
    if cause is not None:
        return telemetry_safe_text(cause.__class__.__name__)
    return telemetry_safe_text(exc.__class__.__name__)


def send_telemetry_event(event, component, outcome="success", **fields):
    if not telemetry_enabled():
        return
    install_id = telemetry_install_id()
    if not install_id:
        return
    payload = {
        "anonymous_install_id": install_id,
        "event": telemetry_safe_text(event, 80),
        "component": telemetry_safe_text(component, 80),
        "outcome": telemetry_safe_text(outcome, 32),
        "contract_version": CONTRACT_VERSION,
        "script_name": SCRIPT_NAME,
        "python": f"{sys.version_info.major}.{sys.version_info.minor}",
        "os": telemetry_safe_text(sys.platform, 64),
        "timestamp": iso_now(),
    }
    for key, value in fields.items():
        if key not in TELEMETRY_ALLOWED_FIELDS or value is None:
            continue
        if isinstance(value, bool):
            payload[key] = value
        elif key == "duration_ms":
            try:
                payload[key] = max(0, min(int(value), 86_400_000))
            except Exception:
                continue
        else:
            payload[key] = telemetry_safe_text(value)
    try:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        request = urllib.request.Request(
            f"{BASE_URL}/v1/telemetry/events",
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with api_urlopen(request, timeout=2) as response:
            response.read(128)
    except Exception:
        pass


def send_telemetry_event_async(event, component, outcome="success", **fields):
    if not telemetry_enabled():
        return
    threading.Thread(
        target=lambda: send_telemetry_event(event, component, outcome, **fields),
        name="napseer-telemetry",
        daemon=True,
    ).start()


