def gateway_log(event, level="info", **fields):
    payload = {
        "ts": iso_now(),
        "level": level,
        "component": "gateway",
        "event": event,
    }
    for key, value in fields.items():
        if value is None:
            continue
        if isinstance(value, pathlib.Path):
            payload[key] = str(value)
        elif isinstance(value, (str, bool, int, float, list, dict)):
            payload[key] = value
        else:
            payload[key] = str(value)
    print(json.dumps(payload, separators=(",", ":"), sort_keys=True), file=sys.stderr, flush=True)


def gateway_periodic_log(key, interval_seconds, event, level="info", **fields):
    now = time.monotonic()
    fingerprint = json.dumps(fields, sort_keys=True, default=str)
    last = GATEWAY_PERIODIC_LOG_STATE.get(key)
    if last and (now - float(last.get("at", 0))) < interval_seconds and last.get("fingerprint") == fingerprint:
        return
    GATEWAY_PERIODIC_LOG_STATE[key] = {"at": now, "fingerprint": fingerprint}
    gateway_log(event, level=level, **fields)


def compact_log_file(path, max_bytes):
    if max_bytes <= 0:
        return
    file_path = pathlib.Path(path)
    try:
        size = file_path.stat().st_size
    except FileNotFoundError:
        return
    except OSError:
        return
    if size <= max_bytes:
        return
    try:
        with file_path.open("rb") as handle:
            handle.seek(-max_bytes, os.SEEK_END)
            chunk = handle.read(max_bytes)
    except OSError:
        return
    newline_index = chunk.find(b"\n")
    if newline_index >= 0 and newline_index + 1 < len(chunk):
        chunk = chunk[newline_index + 1 :]
    tmp_path = file_path.with_suffix(file_path.suffix + ".tmp")
    try:
        tmp_path.write_bytes(chunk)
        tmp_path.replace(file_path)
    except OSError:
        try:
            tmp_path.unlink(missing_ok=True)
        except OSError:
            pass


def start_gateway_log_compactor_thread():
    def loop():
        while True:
            try:
                compact_log_file(AUTH_DIR / "gateway.log", GATEWAY_MAX_LOG_BYTES)
            except Exception:
                pass
            time.sleep(30)

    threading.Thread(target=loop, name="napseer-gateway-log-compactor", daemon=True).start()


def _rotl32(value, shift):
    return ((value << shift) & 0xFFFFFFFF) | (value >> (32 - shift))


def _quarter_round(state, a, b, c, d):
    state[a] = (state[a] + state[b]) & 0xFFFFFFFF
    state[d] ^= state[a]
    state[d] = _rotl32(state[d], 16)
    state[c] = (state[c] + state[d]) & 0xFFFFFFFF
    state[b] ^= state[c]
    state[b] = _rotl32(state[b], 12)
    state[a] = (state[a] + state[b]) & 0xFFFFFFFF
    state[d] ^= state[a]
    state[d] = _rotl32(state[d], 8)
    state[c] = (state[c] + state[d]) & 0xFFFFFFFF
    state[b] ^= state[c]
    state[b] = _rotl32(state[b], 7)


def _chacha20_block(key, counter, nonce):
    constants = b"expand 32-byte k"
    state = list(struct.unpack("<4I", constants))
    state.extend(struct.unpack("<8I", key))
    state.append(counter & 0xFFFFFFFF)
    state.extend(struct.unpack("<3I", nonce))
    working = state[:]
    for _ in range(10):
        _quarter_round(working, 0, 4, 8, 12)
        _quarter_round(working, 1, 5, 9, 13)
        _quarter_round(working, 2, 6, 10, 14)
        _quarter_round(working, 3, 7, 11, 15)
        _quarter_round(working, 0, 5, 10, 15)
        _quarter_round(working, 1, 6, 11, 12)
        _quarter_round(working, 2, 7, 8, 13)
        _quarter_round(working, 3, 4, 9, 14)
    return struct.pack("<16I", *[((working[i] + state[i]) & 0xFFFFFFFF) for i in range(16)])


def _chacha20_xor(key, nonce, data):
    output = bytearray()
    counter = 1
    for offset in range(0, len(data), 64):
        block = _chacha20_block(key, counter, nonce)
        chunk = data[offset : offset + 64]
        output.extend(bytes(left ^ right for left, right in zip(chunk, block)))
        counter = (counter + 1) & 0xFFFFFFFF
    return bytes(output)


def _poly1305_mac(message, key):
    r = int.from_bytes(key[:16], "little")
    r &= 0x0FFFFFFC0FFFFFFC0FFFFFFC0FFFFFFF
    s = int.from_bytes(key[16:], "little")
    p = (1 << 130) - 5
    acc = 0
    for offset in range(0, len(message), 16):
        block = message[offset : offset + 16]
        acc = (acc + int.from_bytes(block + b"\x01", "little")) % p
        acc = (acc * r) % p
    return ((acc + s) % (1 << 128)).to_bytes(16, "little")


def _aead_mac_data(aad, ciphertext):
    def pad16(data):
        remainder = len(data) % 16
        return b"" if remainder == 0 else b"\x00" * (16 - remainder)

    return aad + pad16(aad) + ciphertext + pad16(ciphertext) + struct.pack("<QQ", len(aad), len(ciphertext))


def _encrypt_vault_payload(key, plaintext, aad=b""):
    nonce = secrets.token_bytes(12)
    one_time_key = _chacha20_block(key, 0, nonce)[:32]
    ciphertext = _chacha20_xor(key, nonce, plaintext)
    tag = _poly1305_mac(_aead_mac_data(aad, ciphertext), one_time_key)
    return nonce, ciphertext, tag


def _decrypt_vault_payload(key, nonce, ciphertext, tag, aad=b""):
    one_time_key = _chacha20_block(key, 0, nonce)[:32]
    expected = _poly1305_mac(_aead_mac_data(aad, ciphertext), one_time_key)
    if not hmac.compare_digest(expected, tag):
        raise ValueError("gateway unlock failed")
    return _chacha20_xor(key, nonce, ciphertext)


def _derive_vault_key(passphrase, salt, iterations):
    if not isinstance(passphrase, str) or not passphrase:
        raise ValueError("master passphrase is required")
    return hashlib.pbkdf2_hmac("sha256", passphrase.encode("utf-8"), salt, iterations, dklen=32)


def read_master_passphrase(create=False):
    value = os.environ.get("NAPSEER_MASTER_PASSPHRASE")
    if value:
        return value
    if not sys.stdin.isatty():
        raise RuntimeError("NAPSEER_MASTER_PASSPHRASE is required in non-interactive mode")
    first = getpass.getpass("Create master passphrase: " if create else "Master passphrase: ")
    if create:
        second = getpass.getpass("Confirm master passphrase: ")
        if first != second:
            raise RuntimeError("master passphrases did not match")
    return first


def vault_exists():
    return VAULT_PATH.exists()


def load_public_auth_file():
    if not AUTH_PATH.exists():
        return {}
    try:
        data = json.loads(AUTH_PATH.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"failed to read {AUTH_PATH}: {exc}") from exc
    if not isinstance(data, dict):
        raise RuntimeError(f"{AUTH_PATH} must contain a JSON object")
    return data


def write_public_auth(data):
    public = {key: value for key, value in data.items() if key in AUTH_FILE_KEYS and value is not None}
    if vault_exists() or data.get("gateway_auth_required"):
        public["gateway_auth_required"] = True
        public["vault_path"] = str(VAULT_PATH)
    AUTH_PATH.parent.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_PATH.parent, 0o700)
    AUTH_PATH.write_text(json.dumps(public, indent=2) + "\n", encoding="utf-8")
    chmod_best_effort(AUTH_PATH, 0o600)


def read_vault(passphrase, return_key=False):
    envelope = json.loads(VAULT_PATH.read_text(encoding="utf-8"))
    if envelope.get("schema") != VAULT_SCHEMA:
        raise ValueError("gateway unlock failed")
    kdf = envelope.get("kdf") or {}
    cipher = envelope.get("cipher") or {}
    if kdf.get("name") != "pbkdf2-sha256" or cipher.get("name") != "chacha20-poly1305":
        raise ValueError("gateway unlock failed")
    salt = base64.b64decode(kdf["salt"])
    iterations = int(kdf["iterations"])
    nonce = base64.b64decode(cipher["nonce"])
    ciphertext = base64.b64decode(cipher["ciphertext"])
    tag = base64.b64decode(cipher["tag"])
    key = _derive_vault_key(passphrase, salt, iterations)
    plaintext = _decrypt_vault_payload(key, nonce, ciphertext, tag, VAULT_SCHEMA.encode("utf-8"))
    data = json.loads(plaintext.decode("utf-8"))
    if not isinstance(data, dict):
        raise ValueError("gateway unlock failed")
    return (data, key) if return_key else data


def write_vault(passphrase, payload):
    salt = secrets.token_bytes(16)
    key = _derive_vault_key(passphrase, salt, VAULT_KDF_ITERATIONS)
    plaintext = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    nonce, ciphertext, tag = _encrypt_vault_payload(key, plaintext, VAULT_SCHEMA.encode("utf-8"))
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    VAULT_PATH.write_text(
        json.dumps(
            {
                "schema": VAULT_SCHEMA,
                "created_at": iso_now(),
                "kdf": {
                    "name": "pbkdf2-sha256",
                    "iterations": VAULT_KDF_ITERATIONS,
                    "salt": base64.b64encode(salt).decode("ascii"),
                },
                "cipher": {
                    "name": "chacha20-poly1305",
                    "nonce": base64.b64encode(nonce).decode("ascii"),
                    "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
                    "tag": base64.b64encode(tag).decode("ascii"),
                },
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    chmod_best_effort(VAULT_PATH, 0o600)


def write_vault_with_key(key, payload):
    if not key:
        raise RuntimeError("gateway is locked; unlock before updating vault secrets")
    plaintext = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    nonce, ciphertext, tag = _encrypt_vault_payload(key, plaintext, VAULT_SCHEMA.encode("utf-8"))
    envelope = json.loads(VAULT_PATH.read_text(encoding="utf-8"))
    envelope["cipher"] = {
        "name": "chacha20-poly1305",
        "nonce": base64.b64encode(nonce).decode("ascii"),
        "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
        "tag": base64.b64encode(tag).decode("ascii"),
    }
    VAULT_PATH.write_text(json.dumps(envelope, indent=2) + "\n", encoding="utf-8")
    chmod_best_effort(VAULT_PATH, 0o600)


def persist_vault_secrets():
    write_vault_with_key(VAULT_KEY, {"version": 1, "updated_at": iso_now(), "secrets": VAULT_SECRETS})
    chmod_best_effort(VAULT_PATH, 0o600)


def derive_gateway_relay_secret(passphrase):
    return hashlib.pbkdf2_hmac(
        "sha256",
        str(passphrase).encode("utf-8"),
        b"napseer-gateway-relay-secret:v1",
        GATEWAY_RELAY_SECRET_ITERATIONS,
        dklen=32,
    )


def write_gateway_relay_secret(passphrase):
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    GATEWAY_RELAY_SECRET_PATH.write_text(
        json.dumps(
            {
                "schema": GATEWAY_RELAY_SECRET_SCHEMA,
                "kdf": {
                    "name": "pbkdf2-sha256",
                    "iterations": GATEWAY_RELAY_SECRET_ITERATIONS,
                    "salt": "napseer-gateway-relay-secret:v1",
                },
                "secret": base64.b64encode(derive_gateway_relay_secret(passphrase)).decode("ascii"),
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    chmod_best_effort(GATEWAY_RELAY_SECRET_PATH, 0o600)


def read_gateway_relay_secret():
    if not GATEWAY_RELAY_SECRET_PATH.exists():
        return None
    try:
        payload = json.loads(GATEWAY_RELAY_SECRET_PATH.read_text(encoding="utf-8"))
        if payload.get("schema") != GATEWAY_RELAY_SECRET_SCHEMA:
            return None
        return base64.b64decode(payload["secret"])
    except Exception:
        return None


def gateway_relay_secret_fingerprint(secret):
    if not secret:
        return None
    return base64.b64encode(hashlib.sha256(secret).digest()).decode("ascii")


def read_gateway_relay_state():
    if not GATEWAY_RELAY_STATE_PATH.exists():
        return {}
    try:
        payload = json.loads(GATEWAY_RELAY_STATE_PATH.read_text(encoding="utf-8"))
        if payload.get("schema") != GATEWAY_RELAY_STATE_SCHEMA:
            return {}
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def write_gateway_relay_state(**updates):
    current = read_gateway_relay_state()
    current.update({key: value for key, value in updates.items() if value is not None})
    current["schema"] = GATEWAY_RELAY_STATE_SCHEMA
    current["updated_at"] = iso_now()
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    GATEWAY_RELAY_STATE_PATH.write_text(json.dumps(current, indent=2) + "\n", encoding="utf-8")
    chmod_best_effort(GATEWAY_RELAY_STATE_PATH, 0o600)


def gateway_requires_passphrase_rotation():
    state = read_gateway_relay_state()
    return bool(state.get("requires_passphrase_rotation") is True)


def gateway_rotation_safe_error_code(value):
    text = str(value or "").strip().lower()
    if not text:
        return "rotation_retry_required"
    if text in {
        "rotation_required",
        "challenge_consumed_retry_required",
        "challenge_expired_retry_required",
        "rotation_retry_required",
    }:
        return text
    return "rotation_retry_required"


def gateway_rotation_result_payload(status="retry_required", code="rotation_retry_required", retry_required=True):
    safe_status = "rotated" if str(status or "").strip().lower() == "rotated" else "retry_required"
    return {
        "type": "gateway.passphrase_rotation.result",
        "source": "gateway",
        "status": safe_status,
        "code": gateway_rotation_safe_error_code(code),
        "retry_required": bool(retry_required),
        "sent_at": iso_now(),
    }


def gateway_rotation_frame_class(frame_type):
    value = str(frame_type or "").strip().lower()
    if value in {"heartbeat", "terminal.status"}:
        return "always_allowed"
    if value.startswith("gateway.passphrase_rotation."):
        return "rotation"
    if value.startswith("terminal.") or value.startswith("schedule."):
        return "terminal_or_schedule"
    return "other"


def gateway_rotation_gate_decision(frame_type, rotation_state):
    mode = str((rotation_state or {}).get("allowed_frame_mode") or "normal")
    frame_class = gateway_rotation_frame_class(frame_type)
    if mode != "rotation_only":
        return {"allowed": True, "reason": "normal_mode", "frame_class": frame_class}
    if frame_class in {"always_allowed", "rotation"}:
        return {"allowed": True, "reason": "rotation_allowlist", "frame_class": frame_class}
    return {"allowed": False, "reason": "rotation_required", "frame_class": frame_class}


def gateway_rotation_session_state(
    session_id,
    project_id,
    request_id,
    connect_request,
    requires_rotation,
):
    now = iso_now()
    return {
        "relay_session_id": str(session_id),
        "project_id": str(project_id),
        "gateway_agent_id": AUTH.get("agent_id"),
        "gateway_worker_id": AUTH.get("worker_id"),
        "client_account_id": connect_request.get("client_account_id"),
        "client_id": connect_request.get("client_id"),
        "request_id": request_id,
        "authenticated_at": now,
        "rotation_required_at_session_start": bool(requires_rotation),
        "rotation_gate_state": "required" if requires_rotation else "not_required",
        "allowed_frame_mode": "rotation_only" if requires_rotation else "normal",
        "pending_challenge": None,
        "blocked_frames": 0,
        "failed_rotation_attempts": 0,
    }


def normalize_uuid_text(value):
    if value is None:
        return ""
    try:
        return str(uuid.UUID(str(value).strip()))
    except (TypeError, ValueError, AttributeError):
        return ""


def read_container_uuid_file():
    if not CONTAINER_IDENTITY_PATH.exists():
        return ""
    try:
        data = json.loads(CONTAINER_IDENTITY_PATH.read_text(encoding="utf-8"))
    except Exception:
        return ""
    if not isinstance(data, dict) or data.get("schema") != CONTAINER_IDENTITY_SCHEMA:
        return ""
    return normalize_uuid_text(data.get("container_uuid"))


def read_container_uuid():
    for env_name in ("NAPSEER_GATEWAY_CONTAINER_UUID", "NAPSEER_CONTAINER_UUID"):
        value = normalize_uuid_text(os.environ.get(env_name))
        if value:
            return value
    return read_container_uuid_file()


def ensure_container_uuid():
    existing = read_container_uuid_file()
    if existing:
        return existing
    env_value = ""
    for env_name in ("NAPSEER_GATEWAY_CONTAINER_UUID", "NAPSEER_CONTAINER_UUID"):
        env_value = normalize_uuid_text(os.environ.get(env_name))
        if env_value:
            break
    value = env_value or str(uuid.uuid4())
    payload = {
        "schema": CONTAINER_IDENTITY_SCHEMA,
        "version": 1,
        "container_uuid": value,
        "created_at": iso_now(),
    }
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    CONTAINER_IDENTITY_PATH.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    chmod_best_effort(CONTAINER_IDENTITY_PATH, 0o600)
    return value


def gateway_remote_enabled_value(unlocked=None):
    state = read_gateway_relay_state()
    if isinstance(state.get("remote_enabled"), bool):
        return state["remote_enabled"]
    if unlocked is None:
        unlocked = gateway_is_unlocked()
    if unlocked:
        return bool(VAULT_SECRETS.get("gateway_remote_enabled", True))
    return bool(read_gateway_relay_secret())


def gateway_vault_secret_subset(secrets_map):
    return {key: value for key, value in secrets_map.items() if key in GATEWAY_VAULT_KEYS and value is not None}


def auth_file_secret_subset(secrets_map):
    return {key: value for key, value in secrets_map.items() if key in AUTH_FILE_KEYS and value is not None}


def gateway_locked_reason():
    if not vault_exists():
        return "vault_not_configured"
    if not GATEWAY_UNLOCKED:
        return "locked"
    if GATEWAY_LAST_USED_AT and datetime.now(timezone.utc) - GATEWAY_LAST_USED_AT > timedelta(seconds=GATEWAY_IDLE_TIMEOUT_SECONDS):
        gateway_lock()
        return "idle_timeout"
    return None


def gateway_is_unlocked():
    return gateway_locked_reason() is None


def touch_gateway():
    global GATEWAY_LAST_USED_AT
    GATEWAY_LAST_USED_AT = datetime.now(timezone.utc)


def gateway_lock():
    global VAULT_SECRETS, VAULT_KEY, GATEWAY_UNLOCKED, GATEWAY_LAST_USED_AT, AUTH, TOKEN, TOKEN_EXPIRES_AT
    with GATEWAY_LOCK:
        VAULT_SECRETS = {}
        VAULT_KEY = None
        GATEWAY_UNLOCKED = False
        GATEWAY_LAST_USED_AT = None
        AUTH = load_auth()
        TOKEN = AUTH["token"]
        TOKEN_EXPIRES_AT = AUTH["token_expires_at"]
    return {"status": "locked", "vault_configured": vault_exists()}


def gateway_status():
    unlocked = gateway_is_unlocked()
    remote_enabled = gateway_remote_enabled_value(unlocked)
    listener_ready = bool(remote_enabled and GATEWAY_LISTENER_CONNECTED)
    if not DEFAULT_PROJECT_ID or not TOKEN:
        status = "not_configured"
        message = "No project/token is configured for this directory."
    elif not vault_exists():
        status = "vault_not_configured"
        message = "Gateway vault is not configured; run nap gateway configure."
    elif remote_enabled and listener_ready:
        status = "relay_ready"
        message = "Gateway relay listener is connected."
    elif remote_enabled:
        status = "relay_not_ready"
        message = "Gateway is configured but the relay listener is not connected."
    else:
        status = "remote_disabled"
        message = "Gateway remote relay is disabled."
    return {
        "status": status,
        "message": message,
        **state_dir_status_payload(),
        "auth_path": str(AUTH_PATH),
        "log_path": str(AUTH_DIR / "gateway.log"),
        "container_uuid": read_container_uuid(),
        "vault_path": str(VAULT_PATH),
        "vault_configured": vault_exists(),
        "locked": not unlocked,
        "lock_reason": gateway_locked_reason(),
        "idle_timeout_seconds": GATEWAY_IDLE_TIMEOUT_SECONDS,
        "cwd": str(pathlib.Path.cwd()),
        "base_url": BASE_URL,
        "project_id": DEFAULT_PROJECT_ID,
        "project_slug": AUTH.get("project_slug"),
        "project_name": AUTH.get("project_name"),
        "project_configured": bool(DEFAULT_PROJECT_ID),
        "agent_id": AUTH.get("agent_id"),
        "worker_id": AUTH.get("worker_id"),
        "token_expires_at": TOKEN_EXPIRES_AT,
        "has_token": bool(TOKEN),
        "has_ssh_key": bool(AUTH.get("ssh_private_key")) or pathlib.Path(AUTH["ssh_key_path"]).expanduser().exists(),
        "tmux_target": VAULT_SECRETS.get("gateway_tmux_target") if unlocked else None,
        "default_command": VAULT_SECRETS.get("gateway_default_command") if unlocked else None,
        "managed_session": VAULT_SECRETS.get("gateway_managed_session") if unlocked else None,
        "managed_window": VAULT_SECRETS.get("gateway_managed_window") if unlocked else None,
        "remote_enabled": remote_enabled,
        "relay_listener_connected": GATEWAY_LISTENER_CONNECTED,
        "relay_listener_ready": listener_ready,
        "relay_listener_last_connected_at": GATEWAY_LISTENER_LAST_CONNECTED_AT,
        "relay_listener_last_error": GATEWAY_LISTENER_LAST_ERROR,
        "relay_listener_last_error_at": GATEWAY_LISTENER_LAST_ERROR_AT,
        "relay_listener_active_lanes": sorted(GATEWAY_LISTENER_ACTIVE_LANES),
        "relay_listener_target_lanes": gateway_listener_target_lanes(),
        "relay_listener_unstable": time.time() < GATEWAY_LISTENER_UNSTABLE_UNTIL,
        "relay_secret_configured": bool(read_gateway_relay_secret()),
        "requires_passphrase_rotation": gateway_requires_passphrase_rotation(),
        "relay_connections": len(GATEWAY_RELAY_THREADS),
        "telemetry_enabled": telemetry_enabled(),
        "telemetry_config_path": str(TELEMETRY_PATH),
        "telemetry_anonymous_id_present": bool(telemetry_state().get("anonymous_install_id")),
    }


def gateway_worker_capabilities(capabilities=None):
    current = capabilities if isinstance(capabilities, dict) else {}
    merged = dict(current)
    merged.setdefault("local_mcp", True)
    merged.setdefault("mcp_wrapper", SCRIPT_NAME)
    merged["gateway"] = True
    return merged


def ensure_gateway_worker_capability(refresh=True):
    current = AUTH.get("worker_capabilities") if isinstance(AUTH, dict) else {}
    updated = gateway_worker_capabilities(current)
    if current != updated:
        save_auth({"worker_capabilities": updated})
    if refresh and TOKEN:
        try:
            renew_auth()
        except Exception as exc:
            gateway_log("gateway_capability_refresh_failed", level="error", error=str(exc))
            return {"status": "refresh_failed", "worker_capabilities": updated, "error": str(exc)}
    return {
        "status": "refreshed" if refresh and TOKEN else "updated",
        "worker_capabilities": updated,
    }


def apply_vault_secrets(secrets_payload):
    if not isinstance(secrets_payload, dict):
        raise ValueError("gateway unlock failed")
    secrets_map = secrets_payload.get("secrets", secrets_payload)
    if not isinstance(secrets_map, dict):
        raise ValueError("gateway unlock failed")
    return {key: value for key, value in secrets_map.items() if value is not None}


def gateway_unlock(passphrase):
    global VAULT_SECRETS, VAULT_KEY, GATEWAY_UNLOCKED, AUTH, BASE_URL, TOKEN, DEFAULT_PROJECT_ID, TOKEN_EXPIRES_AT
    if not vault_exists():
        raise RuntimeError("gateway vault is not configured")
    try:
        vault_payload, vault_key = read_vault(passphrase, return_key=True)
        secrets_map = apply_vault_secrets(vault_payload)
    except Exception as exc:
        raise RuntimeError("gateway unlock failed") from exc
    with GATEWAY_LOCK:
        public = load_public_auth_file()
        recovered_auth = auth_file_secret_subset(secrets_map)
        if recovered_auth:
            public = {**public, **recovered_auth}
            write_public_auth(public)
        VAULT_SECRETS = gateway_vault_secret_subset(secrets_map)
        VAULT_SECRETS.setdefault("gateway_encryption_key", base64.b64encode(secrets.token_bytes(32)).decode("ascii"))
        VAULT_SECRETS.setdefault("gateway_remote_enabled", True)
        relay_state = read_gateway_relay_state()
        target_mode = "manual" if VAULT_SECRETS.get("gateway_tmux_target") else "managed"
        if "remote_enabled" not in relay_state:
            write_gateway_relay_state(
                remote_enabled=bool(VAULT_SECRETS.get("gateway_remote_enabled", True)),
                tmux_target=VAULT_SECRETS.get("gateway_tmux_target") or {},
                tmux_target_mode=target_mode,
                managed_session=VAULT_SECRETS.get("gateway_managed_session"),
                managed_window=VAULT_SECRETS.get("gateway_managed_window"),
                default_command=VAULT_SECRETS.get("gateway_default_command"),
            )
        elif "tmux_target_mode" not in relay_state:
            write_gateway_relay_state(tmux_target_mode=target_mode)
        VAULT_KEY = vault_key
        GATEWAY_UNLOCKED = True
        AUTH = load_auth(public_override=public)
        BASE_URL = AUTH["base_url"].rstrip("/")
        TOKEN = AUTH["token"]
        DEFAULT_PROJECT_ID = AUTH["project_id"]
        TOKEN_EXPIRES_AT = AUTH["token_expires_at"]
        write_gateway_relay_secret(passphrase)
        persist_vault_secrets()
        touch_gateway()
    return {
        "status": "unlocked",
        "message": "Gateway vault unlocked.",
        "project_id": DEFAULT_PROJECT_ID,
        "idle_timeout_seconds": GATEWAY_IDLE_TIMEOUT_SECONDS,
    }


def require_unlocked(operation="operation"):
    reason = gateway_locked_reason()
    if reason:
        raise RuntimeError(f"gateway is locked; unlock with the master passphrase before {operation}")
    touch_gateway()


def clean_tmux_name(value, fallback):
    cleaned = "".join(ch if ch.isalnum() or ch in "-_" else "-" for ch in str(value or "").strip().lower())
    cleaned = "-".join(part for part in cleaned.split("-") if part)
    return cleaned[:48] or fallback


def clean_terminal_name(value, fallback="terminal"):
    cleaned = clean_tmux_name(value, fallback)
    if cleaned in {"", ".", ".."}:
        return fallback
    return cleaned


def default_gateway_session_name():
    source = AUTH.get("project_slug") or AUTH.get("project_name") or pathlib.Path.cwd().name or "project"
    return f"napseer-{clean_tmux_name(source, 'project')}"


def normalize_gateway_command(value=None):
    command = str(value or "").strip()
    return command or os.environ.get("NAPSEER_GATEWAY_COMMAND", "bash -l")


def gateway_setup(args):
    passphrase = args.get("passphrase") or read_master_passphrase(create=True)
    if vault_exists() and not args.get("overwrite"):
        result = gateway_unlock(passphrase)
        capability_result = ensure_gateway_worker_capability(refresh=True)
        if args.get("default_command"):
            gateway_tmux_configure({"default_command": args.get("default_command")})
            result = gateway_status()
        return {**result, "resolved_existing_vault": True, "gateway_capability": capability_result}
    public = load_public_auth_file()
    default_command = normalize_gateway_command(args.get("default_command"))
    secrets_map = {
        "gateway_encryption_key": base64.b64encode(secrets.token_bytes(32)).decode("ascii"),
        "gateway_default_command": default_command,
        "gateway_managed_session": default_gateway_session_name(),
        "gateway_managed_window": "agent",
        "gateway_remote_enabled": True,
    }
    payload = {"version": 1, "created_at": iso_now(), "secrets": secrets_map}
    write_vault(passphrase, payload)
    write_public_auth({**public, "gateway_auth_required": True, "vault_path": str(VAULT_PATH)})
    result = gateway_unlock(passphrase)
    write_gateway_relay_state(
        remote_enabled=True,
        tmux_target={},
        tmux_target_mode="managed",
        managed_session=secrets_map.get("gateway_managed_session"),
        managed_window=secrets_map.get("gateway_managed_window"),
        default_command=secrets_map.get("gateway_default_command"),
    )
    write_gateway_relay_secret(passphrase)
    capability_result = ensure_gateway_worker_capability(refresh=True)
    return {**gateway_status(), "status": result.get("status", "unlocked"), "message": "Gateway vault configured and unlocked.", "gateway_capability": capability_result}


def gateway_rotate_passphrase(args):
    require_unlocked("rotating gateway passphrase")
    new_passphrase = (
        args.get("new_passphrase")
        or args.get("passphrase")
        or os.environ.get("NAPSEER_GATEWAY_NEW_PASSPHRASE")
    )
    if not isinstance(new_passphrase, str) or not new_passphrase.strip():
        raise RuntimeError("new gateway passphrase is required")
    new_passphrase = new_passphrase.strip()
    with GATEWAY_LOCK:
        secrets_map = dict(VAULT_SECRETS)
        secrets_map.setdefault("gateway_encryption_key", base64.b64encode(secrets.token_bytes(32)).decode("ascii"))
        secrets_map.setdefault("gateway_remote_enabled", True)
        write_vault(new_passphrase, {"version": 1, "updated_at": iso_now(), "secrets": secrets_map})
        vault_payload, vault_key = read_vault(new_passphrase, return_key=True)
        apply_vault_secrets(vault_payload)
        globals()["VAULT_KEY"] = vault_key
        globals()["VAULT_SECRETS"] = gateway_vault_secret_subset(secrets_map)
        write_gateway_relay_secret(new_passphrase)
        touch_gateway()
    return {
        **gateway_status(),
        "status": "rotated",
        "message": "Gateway passphrase rotated. Update NAPSEER_GATEWAY_PASSPHRASE in compose.yaml or the service environment before restarting the gateway.",
    }


def gateway_tmux_configure(args):
    require_unlocked("configuring gateway tmux target")
    capability_result = ensure_gateway_worker_capability(refresh=True)
    default_command = normalize_gateway_command(args.get("default_command"))
    session = str(args.get("session") or "").strip()
    window = str(args.get("window") or "").strip()
    pane = str(args.get("pane") or "").strip()
    if default_command:
        VAULT_SECRETS["gateway_default_command"] = default_command
    VAULT_SECRETS["gateway_remote_enabled"] = True
    write_gateway_relay_state(remote_enabled=True)
    if session:
        target = {"session": session}
        target_mode = "manual"
        if window:
            target["window"] = window
        if pane:
            target["pane"] = pane
        VAULT_SECRETS["gateway_tmux_target"] = target
    else:
        target_mode = "managed"
        VAULT_SECRETS.pop("gateway_tmux_target", None)
        VAULT_SECRETS.setdefault("gateway_managed_session", default_gateway_session_name())
        VAULT_SECRETS.setdefault("gateway_managed_window", "agent")
        VAULT_SECRETS.setdefault("gateway_default_command", default_command)
        target = {}
    write_gateway_relay_state(
        remote_enabled=True,
        tmux_target=target,
        tmux_target_mode=target_mode,
        managed_session=VAULT_SECRETS.get("gateway_managed_session"),
        managed_window=VAULT_SECRETS.get("gateway_managed_window"),
        default_command=VAULT_SECRETS.get("gateway_default_command"),
    )
    persist_vault_secrets()
    return {
        "status": "configured",
        "message": "Gateway tmux target/default command configured.",
        "tmux_target": VAULT_SECRETS.get("gateway_tmux_target"),
        "default_command": VAULT_SECRETS.get("gateway_default_command"),
        "managed_session": VAULT_SECRETS.get("gateway_managed_session"),
        "managed_window": VAULT_SECRETS.get("gateway_managed_window"),
        "gateway_capability": capability_result,
    }


def format_tmux_target(target):
    value = str(target["session"])
    if target.get("window"):
        value += f":{target['window']}"
    if target.get("pane"):
        value += f".{target['pane']}"
    return value


def gateway_public_tmux_target():
    state = read_gateway_relay_state()
    target = state.get("tmux_target")
    if isinstance(target, dict) and target.get("session"):
        return format_tmux_target(target)
    session = str(state.get("managed_session") or default_gateway_session_name()).strip()
    window = str(state.get("managed_window") or "agent").strip()
    return f"{session}:{window}"


def gateway_tmux_target(remote_authenticated=False):
    if not remote_authenticated:
        require_unlocked("reading gateway terminal")
    if gateway_is_unlocked():
        target = VAULT_SECRETS.get("gateway_tmux_target")
        if not isinstance(target, dict) or not target.get("session"):
            target = ensure_gateway_tmux()
        return format_tmux_target(target)
    if remote_authenticated:
        return gateway_public_tmux_target()
    require_unlocked("reading gateway terminal")


def tmux_run(args, timeout=10):
    return subprocess.run(
        ["tmux", *args],
        check=False,
        capture_output=True,
        text=True,
        timeout=timeout,
    )


def ensure_gateway_tmux():
    command = normalize_gateway_command(VAULT_SECRETS.get("gateway_default_command"))
    session = str(VAULT_SECRETS.get("gateway_managed_session") or default_gateway_session_name()).strip()
    window = str(VAULT_SECRETS.get("gateway_managed_window") or "agent").strip()
    VAULT_SECRETS["gateway_default_command"] = command
    VAULT_SECRETS["gateway_managed_session"] = session
    VAULT_SECRETS["gateway_managed_window"] = window
    cwd = str(pathlib.Path.cwd())

    if tmux_run(["has-session", "-t", session]).returncode != 0:
        result = tmux_run(["new-session", "-d", "-s", session, "-n", window, "-c", cwd, command], timeout=15)
        if result.returncode != 0:
            raise RuntimeError((result.stderr or "tmux new-session failed").strip())
    else:
        listed = tmux_run(["list-windows", "-t", session, "-F", "#{window_name}"])
        if listed.returncode != 0:
            raise RuntimeError((listed.stderr or "tmux list-windows failed").strip())
        windows = {line.strip() for line in listed.stdout.splitlines() if line.strip()}
        if window not in windows:
            result = tmux_run(["new-window", "-d", "-t", session, "-n", window, "-c", cwd, command], timeout=15)
            if result.returncode != 0:
                raise RuntimeError((result.stderr or "tmux new-window failed").strip())

    target = {"session": session, "window": window, "pane": "0"}
    write_gateway_relay_state(
        tmux_target=target,
        tmux_target_mode="managed",
        managed_session=session,
        managed_window=window,
        default_command=command,
    )
    persist_vault_secrets()
    return target


def gateway_manual_tmux_target(remote_authenticated=False):
    if gateway_is_unlocked():
        target = VAULT_SECRETS.get("gateway_tmux_target")
    elif remote_authenticated:
        state = read_gateway_relay_state()
        target = state.get("tmux_target") if state.get("tmux_target_mode") == "manual" else None
    else:
        target = None
    return target if isinstance(target, dict) and target.get("session") else None


def gateway_managed_config(remote_authenticated=False):
    state = read_gateway_relay_state()
    if gateway_is_unlocked():
        return {
            "session": str(VAULT_SECRETS.get("gateway_managed_session") or state.get("managed_session") or default_gateway_session_name()).strip(),
            "window": str(VAULT_SECRETS.get("gateway_managed_window") or state.get("managed_window") or "agent").strip(),
            "command": normalize_gateway_command(VAULT_SECRETS.get("gateway_default_command") or state.get("default_command")),
        }
    if remote_authenticated:
        return {
            "session": str(state.get("managed_session") or default_gateway_session_name()).strip(),
            "window": str(state.get("managed_window") or "agent").strip(),
            "command": normalize_gateway_command(state.get("default_command")),
        }
    require_unlocked("reading gateway terminal")


def ensure_gateway_public_tmux(remote_authenticated=False):
    if gateway_is_unlocked():
        return ensure_gateway_tmux()
    if not remote_authenticated:
        require_unlocked("reading gateway terminal")
    config = gateway_managed_config(remote_authenticated=True)
    session = config["session"]
    window = config["window"]
    command = config["command"]
    cwd = str(pathlib.Path.cwd())
    if tmux_run(["has-session", "-t", session]).returncode != 0:
        result = tmux_run(["new-session", "-d", "-s", session, "-n", window, "-c", cwd, command], timeout=15)
        if result.returncode != 0:
            raise RuntimeError((result.stderr or "tmux new-session failed").strip())
    else:
        listed = tmux_run(["list-windows", "-t", session, "-F", "#{window_name}"])
        if listed.returncode != 0:
            raise RuntimeError((listed.stderr or "tmux list-windows failed").strip())
        windows = {line.strip() for line in listed.stdout.splitlines() if line.strip()}
        if window not in windows:
            result = tmux_run(["new-window", "-d", "-t", session, "-n", window, "-c", cwd, command], timeout=15)
            if result.returncode != 0:
                raise RuntimeError((result.stderr or "tmux new-window failed").strip())
    target = {"session": session, "window": window, "pane": "0"}
    write_gateway_relay_state(
        tmux_target=target,
        tmux_target_mode="managed",
        managed_session=session,
        managed_window=window,
        default_command=command,
    )
    return target


def gateway_tmux_windows(remote_authenticated=False):
    manual = gateway_manual_tmux_target(remote_authenticated=remote_authenticated)
    if manual:
        target = format_tmux_target(manual)
        return [{
            "id": "manual",
            "name": target,
            "index": None,
            "target": target,
            "active": True,
            "managed": False,
            "protected": True,
            "command": "",
        }]
    config = gateway_managed_config(remote_authenticated=remote_authenticated)
    ensure_gateway_public_tmux(remote_authenticated=remote_authenticated)
    result = tmux_run([
        "list-windows",
        "-t",
        config["session"],
        "-F",
        "#{window_id}\t#{window_index}\t#{window_name}\t#{window_active}\t#{pane_current_command}",
    ])
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "tmux list-windows failed").strip())
    items = []
    for line in result.stdout.splitlines():
        parts = line.split("\t")
        if len(parts) < 5:
            continue
        window_id, index, name, active, command = parts[:5]
        target = f"{config['session']}:{index}.0"
        items.append({
            "id": window_id,
            "name": name,
            "index": index,
            "target": target,
            "active": active == "1",
            "managed": True,
            "protected": False,
            "command": command,
        })
    return items


def gateway_terminal_sessions(args=None):
    args = args or {}
    selected_id = str(args.get("terminal_id") or args.get("selected_terminal_id") or "").strip()
    remote_authenticated = bool(args.get("remote_authenticated"))
    items = gateway_terminal_backend_sessions(remote_authenticated=remote_authenticated)
    if selected_id:
        for item in items:
            item["active"] = item["id"] == selected_id or item["name"] == selected_id or str(item.get("index")) == selected_id
    selected = next((item for item in items if item.get("active")), items[0] if items else None)
    return {
        "status": "listed",
        "message": "Gateway terminal sessions listed.",
        "sessions": items,
        "selected_terminal_id": selected.get("id") if selected else None,
        "selected_terminal": selected,
    }


def gateway_terminal_target_from_id(terminal_id=None, remote_authenticated=False):
    backend, selected = gateway_terminal_backend_from_id(terminal_id, remote_authenticated=remote_authenticated)
    if backend != "tmux":
        raise RuntimeError("gateway terminal target is not tmux-backed")
    return selected["target"], selected


def gateway_terminal_unique_name(base_name, windows):
    existing = {str(item.get("name")) for item in windows}
    base = clean_terminal_name(base_name, "terminal")
    if base not in existing:
        return base
    for index in range(2, 100):
        candidate = clean_terminal_name(f"{base}-{index}", "terminal")
        if candidate not in existing:
            return candidate
    raise RuntimeError("could not allocate a unique terminal name")


def gateway_pty_terminal_enabled():
    value = str(os.environ.get("NAPSEER_GATEWAY_PTY_TERMINAL", "1")).strip().lower()
    return value not in {"0", "false", "no", "off", "disabled"}


def gateway_pty_manager():
    from terminal.pty_manager import default_manager

    return default_manager


def gateway_pty_terminal_sessions():
    if not gateway_pty_terminal_enabled():
        return []
    items = []
    for info in gateway_pty_manager().list():
        command = " ".join(info.command)
        items.append({
            "id": info.terminal_id,
            "name": info.terminal_id,
            "index": None,
            "target": None,
            "active": False,
            "managed": True,
            "protected": False,
            "command": command,
            "backend": "pty",
            "rows": info.rows,
            "cols": info.cols,
            "output_seq": info.output_seq,
            "oldest_output_seq": info.oldest_output_seq,
            "created_at": datetime.fromtimestamp(info.created_at, timezone.utc).isoformat().replace("+00:00", "Z"),
            "last_activity": datetime.fromtimestamp(info.last_activity, timezone.utc).isoformat().replace("+00:00", "Z"),
            "closed": info.closed,
            "exit_code": info.exit_code,
        })
    return items


def gateway_terminal_backend_sessions(remote_authenticated=False):
    if not gateway_pty_terminal_enabled():
        tmux_items = gateway_tmux_windows(remote_authenticated=remote_authenticated)
        for item in tmux_items:
            item.setdefault("backend", "tmux")
        return tmux_items
    tmux_items = []
    try:
        tmux_items = gateway_tmux_windows(remote_authenticated=remote_authenticated)
        for item in tmux_items:
            item.setdefault("backend", "tmux")
    except Exception as exc:
        gateway_periodic_log(
            "gateway_terminal_tmux_fallback_unavailable",
            60,
            "gateway_terminal_tmux_fallback_unavailable",
            level="warn",
            error=str(exc),
        )
    return gateway_pty_terminal_sessions() + tmux_items


def gateway_terminal_backend_from_id(terminal_id=None, remote_authenticated=False):
    items = gateway_terminal_backend_sessions(remote_authenticated=remote_authenticated)
    wanted = str(terminal_id or "").strip()
    if wanted:
        for item in items:
            if wanted in {str(item.get("id")), str(item.get("name")), str(item.get("index"))}:
                return item.get("backend") or "tmux", item
        raise RuntimeError("gateway terminal session not found")
    selected = next((item for item in items if item.get("active")), items[0] if items else None)
    if not selected:
        raise RuntimeError("no gateway terminal sessions are available")
    return selected.get("backend") or "tmux", selected


def gateway_terminal_create(args=None):
    args = args or {}
    remote_authenticated = bool(args.get("remote_authenticated"))
    if gateway_pty_terminal_enabled():
        command = normalize_gateway_command(args.get("command") or gateway_managed_config(remote_authenticated=remote_authenticated)["command"])
        info = gateway_pty_manager().open(command=command, cwd=str(pathlib.Path.cwd()))
        sessions = gateway_terminal_sessions({"terminal_id": info.terminal_id, "remote_authenticated": remote_authenticated})
        return {
            **sessions,
            "status": "created",
            "message": "Gateway PTY terminal session created.",
        }
    if gateway_manual_tmux_target(remote_authenticated=remote_authenticated):
        raise RuntimeError("cannot create terminals for a manually configured tmux target")
    config = gateway_managed_config(remote_authenticated=remote_authenticated)
    ensure_gateway_public_tmux(remote_authenticated=remote_authenticated)
    windows = gateway_tmux_windows(remote_authenticated=remote_authenticated)
    max_terminals = max(1, min(int(os.environ.get("NAPSEER_GATEWAY_MAX_TERMINALS", "8")), 32))
    if len(windows) >= max_terminals:
        raise RuntimeError(f"gateway terminal limit reached ({max_terminals})")
    name = gateway_terminal_unique_name(args.get("name") or f"terminal-{len(windows) + 1}", windows)
    command = normalize_gateway_command(args.get("command") or config["command"])
    result = tmux_run(["new-window", "-d", "-t", config["session"], "-n", name, "-c", str(pathlib.Path.cwd()), command], timeout=15)
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "tmux new-window failed").strip())
    sessions = gateway_terminal_sessions({"terminal_id": name, "remote_authenticated": remote_authenticated})
    return {
        **sessions,
        "status": "created",
        "message": "Gateway terminal session created.",
    }


def gateway_terminal_close(args=None):
    args = args or {}
    remote_authenticated = bool(args.get("remote_authenticated"))
    terminal_id = str(args.get("terminal_id") or "").strip()
    current_id = str(args.get("selected_terminal_id") or args.get("current_terminal_id") or "").strip()
    create_replacement = bool(args.get("create_replacement", False))
    if not terminal_id:
        raise RuntimeError("terminal_id is required")
    backend, terminal = gateway_terminal_backend_from_id(terminal_id, remote_authenticated=remote_authenticated)
    if backend == "pty":
        remaining_before_close = [
            item for item in gateway_pty_terminal_sessions()
            if str(item.get("id")) != str(terminal["id"])
        ]
        replacement = None
        if create_replacement and not remaining_before_close:
            replacement = gateway_pty_manager().open(
                command=normalize_gateway_command(gateway_managed_config(remote_authenticated=remote_authenticated)["command"]),
                cwd=str(pathlib.Path.cwd()),
            )
        gateway_pty_manager().close(str(terminal["id"]))
        if replacement:
            selected_id = replacement.terminal_id
        elif current_id and current_id != str(terminal["id"]):
            selected_id = current_id
        elif remaining_before_close:
            selected_id = str(remaining_before_close[0].get("id") or "")
        else:
            selected_id = ""
        sessions = gateway_terminal_sessions({"terminal_id": selected_id, "remote_authenticated": remote_authenticated})
        return {
            **sessions,
            "status": "closed",
            "message": "Gateway PTY terminal session closed.",
            "closed_terminal_id": terminal.get("id"),
            "replacement_terminal_id": replacement.terminal_id if replacement else None,
        }
    if gateway_manual_tmux_target(remote_authenticated=remote_authenticated):
        raise RuntimeError("cannot close a manually configured tmux target")
    windows = gateway_tmux_windows(remote_authenticated=remote_authenticated)
    replacement_name = None
    if len(windows) <= 1 and create_replacement:
        config = gateway_managed_config(remote_authenticated=remote_authenticated)
        replacement_name = gateway_terminal_unique_name("terminal", windows)
        command = normalize_gateway_command(config["command"])
        result = tmux_run(["new-window", "-d", "-t", config["session"], "-n", replacement_name, "-c", str(pathlib.Path.cwd()), command], timeout=15)
        if result.returncode != 0:
            raise RuntimeError((result.stderr or "tmux replacement new-window failed").strip())
        windows = gateway_tmux_windows(remote_authenticated=remote_authenticated)
    if len(windows) <= 1:
        raise RuntimeError("cannot close the last gateway terminal")
    target, closing = gateway_terminal_target_from_id(terminal_id, remote_authenticated=remote_authenticated)
    result = tmux_run(["kill-window", "-t", target])
    stderr = (result.stderr or "").lower()
    if result.returncode != 0 and "can't find" not in stderr and "no server running" not in stderr:
        raise RuntimeError((result.stderr or "tmux kill-window failed").strip())
    remaining = gateway_tmux_windows(remote_authenticated=remote_authenticated)
    selected = None
    if current_id and current_id not in {str(closing.get("id")), str(closing.get("name")), str(closing.get("index"))}:
        selected = next(
            (
                item
                for item in remaining
                if current_id in {str(item.get("id")), str(item.get("name")), str(item.get("index"))}
            ),
            None,
        )
    if selected is None and replacement_name:
        selected = next((item for item in remaining if item.get("name") == replacement_name), None)
    if selected is None:
        selected = remaining[0] if remaining else None
    selected_id = selected.get("id") if selected else None
    sessions = gateway_terminal_sessions({"terminal_id": selected_id, "remote_authenticated": remote_authenticated})
    return {
        **sessions,
        "status": "closed",
        "message": "Gateway terminal session closed.",
        "closed_terminal_id": closing.get("id"),
        "replacement_terminal_name": replacement_name,
    }


def parse_iso_datetime(value):
    if not value:
        return None
    try:
        text = str(value)
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception:
        return None


def gateway_schedule_default_state():
    return {"schema": GATEWAY_SCHEDULES_SCHEMA, "version": 1, "schedules": []}


def read_gateway_schedules_state():
    if not GATEWAY_SCHEDULES_PATH.exists():
        return gateway_schedule_default_state()
    try:
        payload = json.loads(GATEWAY_SCHEDULES_PATH.read_text(encoding="utf-8"))
        if payload.get("schema") != GATEWAY_SCHEDULES_SCHEMA or not isinstance(payload.get("schedules"), list):
            return gateway_schedule_default_state()
        return payload
    except Exception:
        return gateway_schedule_default_state()


def write_gateway_schedules_state(state):
    state["schema"] = GATEWAY_SCHEDULES_SCHEMA
    state["version"] = 1
    state["updated_at"] = iso_now()
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    GATEWAY_SCHEDULES_PATH.write_text(json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    chmod_best_effort(GATEWAY_SCHEDULES_PATH, 0o600)


def cron_field_matches(field, value, minimum, maximum):
    text = str(field or "").strip()
    if not text:
        return False
    for part in text.split(","):
        part = part.strip()
        if not part:
            return False
        step = 1
        if "/" in part:
            part, step_text = part.split("/", 1)
            if not step_text.isdigit() or int(step_text) <= 0:
                return False
            step = int(step_text)
        if part in {"", "*"}:
            start, end = minimum, maximum
        elif "-" in part:
            left, right = part.split("-", 1)
            if not left.isdigit() or not right.isdigit():
                return False
            start, end = int(left), int(right)
        elif part.isdigit():
            start = end = int(part)
        else:
            return False
        if start < minimum or end > maximum or start > end:
            return False
        if start <= value <= end and (value - start) % step == 0:
            return True
    return False


def cron_expr_matches(cron_expr, moment):
    fields = str(cron_expr or "").split()
    if len(fields) != 5:
        return False
    weekday = (moment.weekday() + 1) % 7
    return (
        cron_field_matches(fields[0], moment.minute, 0, 59)
        and cron_field_matches(fields[1], moment.hour, 0, 23)
        and cron_field_matches(fields[2], moment.day, 1, 31)
        and cron_field_matches(fields[3], moment.month, 1, 12)
        and cron_field_matches(fields[4], weekday, 0, 6)
    )


def validate_gateway_cron_expr(cron_expr):
    now = datetime.now(timezone.utc).replace(second=0, microsecond=0)
    fields = str(cron_expr or "").split()
    if len(fields) != 5:
        raise RuntimeError("cron_expr must use five fields")
    for offset in range(0, 366 * 24 * 60):
        if cron_expr_matches(cron_expr, now + timedelta(minutes=offset)):
            return True
    raise RuntimeError("cron_expr does not match any time in the next year")


def next_gateway_schedule_run(cron_expr, after=None):
    validate_gateway_cron_expr(cron_expr)
    cursor = (after or datetime.now(timezone.utc)).astimezone(timezone.utc)
    cursor = cursor.replace(second=0, microsecond=0) + timedelta(minutes=1)
    for offset in range(0, 366 * 24 * 60):
        candidate = cursor + timedelta(minutes=offset)
        if cron_expr_matches(cron_expr, candidate):
            return candidate.isoformat().replace("+00:00", "Z")
    return None


def gateway_terminal_public_lookup(remote_authenticated=True):
    lookup = {}
    for item in gateway_terminal_sessions({"remote_authenticated": remote_authenticated}).get("sessions") or []:
        public = {key: value for key, value in item.items() if key != "target"}
        for key in {str(item.get("id") or ""), str(item.get("name") or ""), str(item.get("index") or "")}:
            if key:
                lookup[key] = public
    return lookup


def gateway_schedule_projection(schedule, terminal_lookup):
    terminal = terminal_lookup.get(str(schedule.get("terminal_id") or ""))
    item = dict(schedule)
    item["missing_target"] = terminal is None
    item["terminal_name"] = terminal.get("name") if terminal else None
    item["terminal_backend"] = terminal.get("backend") if terminal else item.get("terminal_backend")
    item["terminal_command"] = terminal.get("command") if terminal else item.get("terminal_command")
    if terminal is None:
        item["last_error"] = item.get("last_error") or "Target terminal no longer exists."
    return item


def gateway_schedule_list(args=None):
    args = args or {}
    remote_authenticated = bool(args.get("remote_authenticated"))
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
    terminal_lookup = gateway_terminal_public_lookup(remote_authenticated=remote_authenticated)
    projected = [gateway_schedule_projection(item, terminal_lookup) for item in schedules]
    projected.sort(key=lambda item: (str(item.get("next_run_at") or ""), str(item.get("name") or "")))
    return {
        "status": "listed",
        "message": "Gateway terminal schedules listed.",
        "schedules": projected,
    }


def normalize_gateway_schedule_payload(args, existing=None):
    existing = existing or {}
    name = str(args.get("name") if args.get("name") is not None else existing.get("name") or "Scheduled terminal message").strip()
    terminal_id = str(args.get("terminal_id") if args.get("terminal_id") is not None else existing.get("terminal_id") or "").strip()
    message = str(args.get("message") if args.get("message") is not None else args.get("text") if args.get("text") is not None else existing.get("message") or "")
    cron_expr = str(args.get("cron_expr") if args.get("cron_expr") is not None else existing.get("cron_expr") or "*/15 * * * *").strip()
    if not terminal_id:
        raise RuntimeError("terminal_id is required")
    if not message.strip():
        raise RuntimeError("schedule message is required")
    validate_gateway_cron_expr(cron_expr)
    terminal_lookup = gateway_terminal_public_lookup(remote_authenticated=bool(args.get("remote_authenticated")))
    terminal = terminal_lookup.get(terminal_id)
    missing_target = terminal is None
    now = iso_now()
    enabled = args.get("enabled", existing.get("enabled", True))
    if isinstance(enabled, str):
        enabled = enabled.lower() not in {"0", "false", "no", "off"}
    return {
        **existing,
        "id": existing.get("id") or f"sch_{secrets.token_hex(12)}",
        "name": name[:120] or "Scheduled terminal message",
        "terminal_id": terminal_id,
        "terminal_backend": terminal.get("backend") if terminal else existing.get("terminal_backend"),
        "terminal_command": terminal.get("command") if terminal else existing.get("terminal_command"),
        "message": message,
        "cron_expr": cron_expr,
        "enabled": bool(enabled),
        "created_at": existing.get("created_at") or now,
        "updated_at": now,
        "last_run_at": existing.get("last_run_at"),
        "last_error": "Target terminal no longer exists." if missing_target else existing.get("last_error"),
        "next_run_at": next_gateway_schedule_run(cron_expr),
    }


def gateway_schedule_create(args=None):
    args = args or {}
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
        schedule = normalize_gateway_schedule_payload(args)
        schedules.append(schedule)
        state["schedules"] = schedules
        write_gateway_schedules_state(state)
    return {**gateway_schedule_list(args), "status": "created", "schedule": schedule}


def gateway_schedule_update(args=None):
    args = args or {}
    schedule_id = str(args.get("schedule_id") or args.get("id") or "").strip()
    if not schedule_id:
        raise RuntimeError("schedule_id is required")
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
        for index, item in enumerate(schedules):
            if str(item.get("id")) == schedule_id:
                schedules[index] = normalize_gateway_schedule_payload(args, existing=item)
                state["schedules"] = schedules
                write_gateway_schedules_state(state)
                return {**gateway_schedule_list(args), "status": "updated", "schedule": schedules[index]}
    raise RuntimeError("gateway schedule not found")


def gateway_schedule_delete(args=None):
    args = args or {}
    schedule_id = str(args.get("schedule_id") or args.get("id") or "").strip()
    if not schedule_id:
        raise RuntimeError("schedule_id is required")
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
        next_schedules = [item for item in schedules if str(item.get("id")) != schedule_id]
        if len(next_schedules) == len(schedules):
            raise RuntimeError("gateway schedule not found")
        state["schedules"] = next_schedules
        write_gateway_schedules_state(state)
    return {**gateway_schedule_list(args), "status": "deleted", "deleted_schedule_id": schedule_id}


def gateway_schedule_execute(schedule, remote_authenticated=True):
    backend, terminal = gateway_terminal_backend_from_id(schedule.get("terminal_id"), remote_authenticated=remote_authenticated)
    message = schedule.get("message") or ""
    if backend == "pty":
        payload = message if message.endswith("\n") else f"{message}\n"
        gateway_pty_manager().write(str(terminal["id"]), payload.encode("utf-8"))
        return {
            "status": "ran",
            "terminal_id": terminal["id"],
            "terminal_backend": "pty",
        }
    gateway_terminal_target_from_id(schedule.get("terminal_id"), remote_authenticated=remote_authenticated)
    gateway_terminal_input({
        "terminal_id": schedule.get("terminal_id"),
        "input": message,
        "enter": True,
        "remote_authenticated": remote_authenticated,
        "stream": True,
    })
    return {
        "status": "ran",
        "terminal_id": schedule.get("terminal_id"),
        "terminal_backend": "tmux",
    }


def gateway_schedule_run_now(args=None):
    args = args or {}
    schedule_id = str(args.get("schedule_id") or args.get("id") or "").strip()
    if not schedule_id:
        raise RuntimeError("schedule_id is required")
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
        for item in schedules:
            if str(item.get("id")) != schedule_id:
                continue
            try:
                result = gateway_schedule_execute(item, remote_authenticated=bool(args.get("remote_authenticated")))
                item["last_run_at"] = iso_now()
                item["last_error"] = None
                item["terminal_backend"] = result.get("terminal_backend") or item.get("terminal_backend")
                item["next_run_at"] = next_gateway_schedule_run(item.get("cron_expr"))
                status = "ran"
            except Exception as exc:
                item["last_error"] = str(exc)
                item["next_run_at"] = next_gateway_schedule_run(item.get("cron_expr"))
                status = "error"
            item["updated_at"] = iso_now()
            state["schedules"] = schedules
            write_gateway_schedules_state(state)
            if status == "error":
                raise RuntimeError(item["last_error"])
            return {**gateway_schedule_list(args), "status": status, "schedule": item}
    raise RuntimeError("gateway schedule not found")


def gateway_schedule_run_due_once():
    now = datetime.now(timezone.utc)
    changed = False
    with GATEWAY_SCHEDULE_LOCK:
        state = read_gateway_schedules_state()
        schedules = list(state.get("schedules") or [])
        for item in schedules:
            if not item.get("enabled", True):
                continue
            next_run = parse_iso_datetime(item.get("next_run_at"))
            if next_run is None:
                item["next_run_at"] = next_gateway_schedule_run(item.get("cron_expr"), now - timedelta(minutes=1))
                changed = True
                continue
            if next_run > now:
                continue
            try:
                result = gateway_schedule_execute(item, remote_authenticated=True)
                item["last_run_at"] = iso_now()
                item["last_error"] = None
                item["terminal_backend"] = result.get("terminal_backend") or item.get("terminal_backend")
                gateway_log("gateway_schedule_ran", schedule_id=item.get("id"), terminal_id=item.get("terminal_id"), terminal_backend=item.get("terminal_backend"))
            except Exception as exc:
                item["last_error"] = str(exc)
                gateway_log("gateway_schedule_error", level="warn", schedule_id=item.get("id"), terminal_id=item.get("terminal_id"), terminal_backend=item.get("terminal_backend"), error=str(exc))
            item["next_run_at"] = next_gateway_schedule_run(item.get("cron_expr"), now)
            item["updated_at"] = iso_now()
            changed = True
        if changed:
            state["schedules"] = schedules
            write_gateway_schedules_state(state)
    return {"status": "checked", "changed": changed}


def gateway_schedule_loop():
    interval = max(5, min(int(os.environ.get("NAPSEER_GATEWAY_SCHEDULE_POLL_SECONDS", "20")), 300))
    gateway_log("gateway_schedule_thread_started", schedule_path=GATEWAY_SCHEDULES_PATH)
    while True:
        try:
            gateway_schedule_run_due_once()
        except Exception as exc:
            gateway_periodic_log("gateway_schedule_loop_error", 60, "gateway_schedule_loop_error", level="warn", error=str(exc))
        time.sleep(interval)


def start_gateway_schedule_thread():
    threading.Thread(target=gateway_schedule_loop, name="napseer-gateway-schedules", daemon=True).start()


def gateway_terminal_kill(args=None):
    require_unlocked("killing gateway terminal")
    target = VAULT_SECRETS.get("gateway_tmux_target")
    if isinstance(target, dict) and target.get("session"):
        tmux_target = gateway_tmux_target()
    else:
        tmux_target = f"{VAULT_SECRETS.get('gateway_managed_session') or default_gateway_session_name()}:{VAULT_SECRETS.get('gateway_managed_window') or 'agent'}"
    result = tmux_run(["kill-window", "-t", tmux_target])
    stderr = (result.stderr or "").lower()
    if result.returncode != 0 and "can't find" not in stderr and "no server running" not in stderr:
        raise RuntimeError((result.stderr or "tmux kill-window failed").strip())
    return {"status": "killed", "message": "Gateway tmux window killed.", "tmux_target": tmux_target}


def gateway_terminal_restart(args=None):
    require_unlocked("restarting gateway terminal")
    gateway_terminal_kill(args or {})
    target = ensure_gateway_tmux()
    output = gateway_terminal_capture({"start": "-80"})["output"]
    return {"status": "restarted", "message": "Gateway tmux window restarted.", "tmux_target": target, "output": output}


def gateway_terminal_capture(args=None):
    args = args or {}
    if args.get("_internal_target") and (args.get("tmux_target") or args.get("target")):
        target = str(args.get("tmux_target") or args.get("target"))
    elif args.get("terminal_id"):
        target, _selected = gateway_terminal_target_from_id(
            args.get("terminal_id"),
            remote_authenticated=bool(args.get("remote_authenticated")),
        )
    else:
        target = gateway_tmux_target(remote_authenticated=bool(args.get("remote_authenticated")))
    start = str((args or {}).get("start") or "-200")
    output = gateway_terminal_capture_target(target, start)
    return {"status": "captured", "message": "Gateway terminal output captured.", "tmux_target": target, "output": output}


def gateway_terminal_capture_target(target, start="-200"):
    command = ["tmux", "capture-pane", "-p", "-t", target]
    if start not in (None, "", "visible"):
        command.extend(["-S", str(start)])
    result = subprocess.run(
        command,
        check=False,
        capture_output=True,
        text=True,
        timeout=10,
    )
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "tmux capture-pane failed").strip())
    return result.stdout


def gateway_terminal_bound_output(output):
    max_chars = max(2000, min(int(os.environ.get("NAPSEER_GATEWAY_STREAM_MAX_CHARS", "24000")), 48000))
    if len(output) <= max_chars:
        return output
    return output[-max_chars:]


def gateway_terminal_route_args(frame, stream_state):
    terminal_id = str((frame or {}).get("terminal_id") or "").strip()
    if terminal_id:
        return {"terminal_id": terminal_id, "remote_authenticated": True}
    target = (stream_state or {}).get("target")
    return {
        "tmux_target": target,
        "_internal_target": True,
        "remote_authenticated": True,
    }


def gateway_terminal_output_payload(payload, terminal_id):
    terminal_id = str(terminal_id or "").strip()
    if not terminal_id or (payload or {}).get("type") != "terminal.output":
        return payload
    return {
        **payload,
        "terminal_id": terminal_id,
        "selected_terminal_id": terminal_id,
    }


def gateway_terminal_output_delta(previous, current):
    if previous is None or current == previous:
        return ""
    if current.startswith(previous):
        return current[len(previous):]
    max_overlap = min(len(previous), len(current), 12000)
    for size in range(max_overlap, 0, -1):
        if previous[-size:] == current[:size]:
            return current[size:]
    return ""


def gateway_wait_for_terminal_output(target, before_output, start="-200", max_wait_ms=None, settle_ms=None):
    max_wait_ms = max(0, min(int(max_wait_ms if max_wait_ms is not None else os.environ.get("NAPSEER_GATEWAY_OUTPUT_WAIT_MS", "12000")), 30000))
    settle_ms = max(0, min(int(settle_ms if settle_ms is not None else os.environ.get("NAPSEER_GATEWAY_OUTPUT_SETTLE_MS", "700")), 5000))
    interval_ms = max(50, min(int(os.environ.get("NAPSEER_GATEWAY_OUTPUT_POLL_MS", "250")), 2000))
    if max_wait_ms <= 0:
        return {
            "output": gateway_terminal_capture_target(target, start),
            "waited_ms": 0,
            "changed": False,
            "settled": False,
        }
    deadline = time.monotonic() + (max_wait_ms / 1000)
    latest = before_output
    changed = False
    last_change_at = None
    started_at = time.monotonic()
    while time.monotonic() < deadline:
        time.sleep(interval_ms / 1000)
        captured = gateway_terminal_capture_target(target, start)
        now = time.monotonic()
        if captured != latest:
            latest = captured
            if captured != before_output:
                changed = True
                last_change_at = now
        if changed and last_change_at is not None and (now - last_change_at) * 1000 >= settle_ms:
            return {
                "output": latest,
                "waited_ms": int((now - started_at) * 1000),
                "changed": True,
                "settled": True,
            }
    return {
        "output": latest if changed else gateway_terminal_capture_target(target, start),
        "waited_ms": int((time.monotonic() - started_at) * 1000),
        "changed": changed,
        "settled": False,
    }


def gateway_terminal_input(args):
    if args.get("_internal_target") and (args.get("tmux_target") or args.get("target")):
        target = str(args.get("tmux_target") or args.get("target"))
    elif args.get("terminal_id"):
        target, _selected = gateway_terminal_target_from_id(
            args.get("terminal_id"),
            remote_authenticated=bool(args.get("remote_authenticated")),
        )
    else:
        target = gateway_tmux_target(remote_authenticated=bool(args.get("remote_authenticated")))
    text = str(args.get("input") or args.get("text") or "")
    if not text:
        raise RuntimeError("terminal input is required")
    submit = bool(args.get("enter", True))
    submit_delay_ms = max(0, min(int(args.get("enter_delay_ms", os.environ.get("NAPSEER_GATEWAY_ENTER_DELAY_MS", "150"))), 2000))
    capture_start = str(args.get("start") or "-200")
    stream_mode = bool(args.get("stream"))
    before_output = None if stream_mode else gateway_terminal_capture_target(target, capture_start)
    lines = text.splitlines()
    if not lines:
        lines = [text]
    for index, line in enumerate(lines):
        if line:
            result = subprocess.run(
                ["tmux", "send-keys", "-t", target, "-l", line],
                check=False,
                capture_output=True,
                text=True,
                timeout=10,
            )
            if result.returncode != 0:
                raise RuntimeError((result.stderr or "tmux send-keys failed").strip())
        if submit or index < len(lines) - 1:
            if submit_delay_ms:
                time.sleep(submit_delay_ms / 1000)
            result = subprocess.run(
                ["tmux", "send-keys", "-t", target, "Enter"],
                check=False,
                capture_output=True,
                text=True,
                timeout=10,
            )
            if result.returncode != 0:
                raise RuntimeError((result.stderr or "tmux send-keys failed").strip())
    if stream_mode:
        return {
            "status": "sent",
            "message": "Gateway terminal input sent.",
            "tmux_target": target,
            "output": "",
            "output_waited_ms": 0,
            "output_changed": False,
            "output_settled": False,
        }
    waited = gateway_wait_for_terminal_output(
        target,
        before_output,
        start=capture_start,
        max_wait_ms=args.get("output_wait_ms"),
        settle_ms=args.get("output_settle_ms"),
    )
    return {
        "status": "sent",
        "message": "Gateway terminal input sent.",
        "tmux_target": target,
        "output": waited["output"],
        "output_waited_ms": waited["waited_ms"],
        "output_changed": waited["changed"],
        "output_settled": waited["settled"],
    }


def gateway_terminal_key(args):
    if args.get("_internal_target") and (args.get("tmux_target") or args.get("target")):
        target = str(args.get("tmux_target") or args.get("target"))
    elif args.get("terminal_id"):
        target, _selected = gateway_terminal_target_from_id(
            args.get("terminal_id"),
            remote_authenticated=bool(args.get("remote_authenticated")),
        )
    else:
        target = gateway_tmux_target(remote_authenticated=bool(args.get("remote_authenticated")))
    text = args.get("text")
    if isinstance(text, str) and text:
        if len(text) > 256:
            raise RuntimeError("terminal key text is too large")
        result = tmux_run(["send-keys", "-t", target, "-l", text])
        if result.returncode != 0:
            raise RuntimeError((result.stderr or "tmux send-keys failed").strip())
        return {"status": "sent", "message": "Gateway terminal key sent.", "tmux_target": target}
    key = str(args.get("key") or "").strip()
    key_map = {
        "Enter": "Enter",
        "Escape": "Escape",
        "Esc": "Escape",
        "Tab": "Tab",
        "BTab": "BTab",
        "Backspace": "BSpace",
        "Delete": "DC",
        "ArrowUp": "Up",
        "ArrowDown": "Down",
        "ArrowLeft": "Left",
        "ArrowRight": "Right",
        "PageUp": "PageUp",
        "PageDown": "PageDown",
        "Home": "Home",
        "End": "End",
        "Insert": "IC",
        "Space": "Space",
    }
    key_parts = key.split("-")
    modifiers = []
    while key_parts and key_parts[0] in {"C", "M"}:
        modifiers.append(key_parts.pop(0))
    base_key = "-".join(key_parts)
    if base_key == "\\\\":
        base_key = "\\"
    base_tmux_key = key_map.get(base_key, base_key)
    allowed_base_keys = {
        "Enter", "Escape", "Tab", "BTab", "BSpace", "DC", "Up", "Down",
        "Left", "Right", "PageUp", "PageDown", "Home", "End", "IC", "Space",
    }
    if re.fullmatch(r"F([1-9]|1[0-2])", base_tmux_key):
        allowed = True
    elif re.fullmatch(r"[a-zA-Z0-9]", base_tmux_key):
        allowed = True
    elif base_tmux_key in {"[", "\\", "]", "^", "_", "?"}:
        allowed = True
    else:
        allowed = base_tmux_key in allowed_base_keys
    tmux_key = "-".join([*modifiers, base_tmux_key]) if allowed else None
    if not tmux_key:
        raise RuntimeError("terminal key is not allowed")
    result = tmux_run(["send-keys", "-t", target, tmux_key])
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "tmux send-keys failed").strip())
    return {"status": "sent", "message": "Gateway terminal key sent.", "tmux_target": target}


def gateway_terminal_stream_loop(stop_event, send_payload, project_id, session_id, request_id, target, start="-200"):
    interval_ms = max(100, min(int(os.environ.get("NAPSEER_GATEWAY_STREAM_POLL_MS", "350")), 5000))
    send_initial_snapshot = os.environ.get("NAPSEER_GATEWAY_STREAM_INITIAL_SNAPSHOT", "true").lower() in {"1", "true", "yes"}
    output_mode = os.environ.get("NAPSEER_GATEWAY_STREAM_MODE", "snapshot").strip().lower()
    use_delta_stream = output_mode in {"delta", "stream"}
    latest = None
    while not stop_event.is_set():
        try:
            captured = gateway_terminal_bound_output(gateway_terminal_capture_target(target, start))
            if latest is None:
                latest = captured
                if send_initial_snapshot:
                    send_payload({
                        "type": "terminal.output",
                        "source": "gateway",
                        "mode": "snapshot",
                        "data": captured,
                        "sent_at": iso_now(),
                    })
                stop_event.wait(interval_ms / 1000)
                continue
            if captured == latest:
                stop_event.wait(interval_ms / 1000)
                continue
            if use_delta_stream:
                delta = gateway_terminal_output_delta(latest, captured)
                if delta:
                    send_payload({
                        "type": "terminal.output",
                        "source": "gateway",
                        "mode": "stream",
                        "data": gateway_terminal_bound_output(delta),
                        "sent_at": iso_now(),
                    })
                    latest = captured
                    stop_event.wait(interval_ms / 1000)
                    continue
            send_payload({
                "type": "terminal.output",
                "source": "gateway",
                "mode": "snapshot",
                "data": captured,
                "sent_at": iso_now(),
            })
            if use_delta_stream:
                gateway_log(
                    "relay_terminal_stream_resync",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    reason="tmux capture changed without append-only delta",
                )
            latest = captured
        except Exception as exc:
            if isinstance(exc, RelaySocketClosed):
                gateway_log(
                    "relay_terminal_stream_closed",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    error=str(exc),
                )
                break
            gateway_log(
                "relay_terminal_stream_error",
                level="error",
                project_id=project_id,
                session_id=session_id,
                request_id=request_id,
                error=str(exc),
            )
            try:
                send_payload({
                    "type": "terminal.status",
                    "source": "gateway",
                    "status": "terminal stream stopped",
                    "sent_at": iso_now(),
                })
            except Exception:
                pass
            break
        stop_event.wait(interval_ms / 1000)


def gateway_remote_enable(args):
    unlocked = gateway_is_unlocked()
    capability_result = ensure_gateway_worker_capability(refresh=True)
    if unlocked:
        touch_gateway()
        VAULT_SECRETS["gateway_remote_enabled"] = True
    write_gateway_relay_state(remote_enabled=True)
    if args.get("relay_url"):
        if unlocked:
            VAULT_SECRETS["gateway_relay_url"] = str(args["relay_url"])
        write_gateway_relay_state(relay_url=str(args["relay_url"]))
    if unlocked:
        persist_vault_secrets()
    return {
        "status": "enabled",
        "message": "Gateway remote relay enabled.",
        "remote_enabled": True,
        "tmux_target": VAULT_SECRETS.get("gateway_tmux_target"),
        "gateway_capability": capability_result,
    }


def gateway_remote_disable():
    unlocked = gateway_is_unlocked()
    if unlocked:
        touch_gateway()
        VAULT_SECRETS["gateway_remote_enabled"] = False
    write_gateway_relay_state(remote_enabled=False)
    if unlocked:
        persist_vault_secrets()
    return {"status": "disabled", "message": "Gateway remote relay disabled.", "remote_enabled": False}


def gateway_remote_readiness():
    return {
        "has_token": bool(TOKEN),
        "project_id": current_project_id(),
        "agent_id": AUTH.get("agent_id"),
        "remote_enabled": gateway_remote_enabled_value(),
        "relay_secret_configured": bool(read_gateway_relay_secret()),
    }


def gateway_remote_blockers(readiness):
    blockers = []
    if not readiness.get("has_token"):
        blockers.append("missing_token")
    if not readiness.get("project_id"):
        blockers.append("missing_project")
    if not readiness.get("agent_id"):
        blockers.append("missing_agent_id")
    if not readiness.get("remote_enabled"):
        blockers.append("remote_disabled")
    return blockers


def gateway_remote_should_run():
    readiness = gateway_remote_readiness()
    if not readiness["has_token"] or not readiness["project_id"] or not readiness["agent_id"]:
        return False
    return bool(readiness["remote_enabled"])


def relay_base_url():
    state = read_gateway_relay_state()
    return str(state.get("relay_url") or VAULT_SECRETS.get("gateway_relay_url") or BASE_URL).rstrip("/")


def relay_ws_url(project_id, session_id, ticket):
    parsed = urllib.parse.urlparse(relay_base_url())
    scheme = "wss" if parsed.scheme == "https" else "ws"
    netloc = parsed.netloc
    return f"{scheme}://{netloc}/v1/projects/{project_id}/gateway-sessions/{session_id}/relay?{urllib.parse.urlencode({'ticket': ticket})}"


def gateway_listener_ws_url(project_id, agent_id):
    parsed = urllib.parse.urlparse(relay_base_url())
    scheme = "wss" if parsed.scheme == "https" else "ws"
    netloc = parsed.netloc
    quoted_agent = urllib.parse.quote(str(agent_id), safe="")
    return f"{scheme}://{netloc}/v1/projects/{project_id}/gateways/{quoted_agent}/listener"


def websocket_proxy_url(parsed):
    host = parsed.hostname or ""
    if host and urllib.request.proxy_bypass(host):
        return None
    explicit = (
        os.environ.get("NAPSEER_GATEWAY_PROXY_URL")
        or os.environ.get("NAPSEER_RELAY_PROXY_URL")
        or os.environ.get("NAPSEER_PROXY_URL")
    )
    if explicit:
        return explicit
    proxies = urllib.request.getproxies_environment()
    proxy_key = "https" if parsed.scheme == "wss" else "http"
    return proxies.get(proxy_key) or proxies.get("all")


def normalize_proxy_url(value):
    if not value:
        return None
    proxy_url = str(value).strip()
    if not proxy_url:
        return None
    if "://" not in proxy_url:
        proxy_url = f"http://{proxy_url}"
    return urllib.parse.urlparse(proxy_url)


def api_proxy_url(parsed):
    host = parsed.hostname or ""
    if host and urllib.request.proxy_bypass(host):
        return None
    explicit = (
        os.environ.get("NAPSEER_API_PROXY_URL")
        or os.environ.get("NAPSEER_HTTP_PROXY_URL")
        or os.environ.get("NAPSEER_PROXY_URL")
        or os.environ.get("NAPSEER_RELAY_PROXY_URL")
        or os.environ.get("NAPSEER_GATEWAY_PROXY_URL")
    )
    if explicit:
        return explicit
    proxies = urllib.request.getproxies_environment()
    return proxies.get(parsed.scheme) or proxies.get("all")


def api_urlopen(request, timeout):
    parsed = urllib.parse.urlparse(request.full_url)
    proxy = normalize_proxy_url(api_proxy_url(parsed))
    if not proxy:
        return urllib.request.urlopen(request, timeout=timeout)
    proxy_url = urllib.parse.urlunparse(proxy)
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({parsed.scheme: proxy_url}))
    return opener.open(request, timeout=timeout)


def configure_interactive_socket(sock):
    try:
        sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    except OSError:
        pass
    return sock


def read_http_response_head(sock, description):
    response = b""
    while b"\r\n\r\n" not in response:
        chunk = sock.recv(4096)
        if not chunk:
            raise RuntimeError(f"{description} closed during handshake")
        response += chunk
        if len(response) > 16384:
            raise RuntimeError(f"{description} handshake too large")
    return response


def connect_proxy_tunnel(proxy, target_host, target_port, timeout=20):
    proxy_host = proxy.hostname or ""
    if not proxy_host:
        raise RuntimeError("websocket proxy URL is missing a host")
    proxy_port = proxy.port or (443 if proxy.scheme == "https" else 80)
    if proxy.scheme not in {"http", "https"}:
        raise RuntimeError("websocket proxy must use http:// or https://")
    raw = configure_interactive_socket(socket.create_connection((proxy_host, proxy_port), timeout=timeout))
    sock = ssl.create_default_context().wrap_socket(raw, server_hostname=proxy_host) if proxy.scheme == "https" else raw
    target = f"{target_host}:{target_port}"
    request = (
        f"CONNECT {target} HTTP/1.1\r\n"
        f"Host: {target}\r\n"
        "Proxy-Connection: keep-alive\r\n"
        "User-Agent: napseer-gateway\r\n"
    )
    if proxy.username:
        username = urllib.parse.unquote(proxy.username)
        password = urllib.parse.unquote(proxy.password or "")
        credentials = base64.b64encode(f"{username}:{password}".encode("utf-8")).decode("ascii")
        request += f"Proxy-Authorization: Basic {credentials}\r\n"
    request += "\r\n"
    sock.sendall(request.encode("ascii"))
    response = read_http_response_head(sock, "websocket proxy")
    status_line = response.split(b"\r\n", 1)[0]
    if b" 200 " not in status_line:
        raise RuntimeError(status_line.decode("utf-8", errors="replace"))
    return sock


def ws_connect(url, extra_headers=None):
    parsed = urllib.parse.urlparse(url)
    host = parsed.hostname or ""
    port = parsed.port or (443 if parsed.scheme == "wss" else 80)
    path = parsed.path + (f"?{parsed.query}" if parsed.query else "")
    proxy = normalize_proxy_url(websocket_proxy_url(parsed))
    raw = connect_proxy_tunnel(proxy, host, port, timeout=20) if proxy else configure_interactive_socket(socket.create_connection((host, port), timeout=20))
    sock = ssl.create_default_context().wrap_socket(raw, server_hostname=host) if parsed.scheme == "wss" else raw
    configure_interactive_socket(sock)
    key = base64.b64encode(secrets.token_bytes(16)).decode("ascii")
    request = (
        f"GET {path} HTTP/1.1\r\n"
        f"Host: {parsed.netloc}\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        "Sec-WebSocket-Version: 13\r\n"
    )
    for header, value in (extra_headers or {}).items():
        request += f"{header}: {value}\r\n"
    request += "\r\n"
    sock.sendall(request.encode("ascii"))
    response = read_http_response_head(sock, "relay websocket")
    if b" 101 " not in response.split(b"\r\n", 1)[0]:
        raise RuntimeError(response.decode("utf-8", errors="replace").split("\r\n\r\n", 1)[0])
    sock.settimeout(None)
    return sock


def gateway_listener_min_lanes():
    try:
        return max(1, min(3, int(os.environ.get("NAPSEER_GATEWAY_RELAY_LISTENER_MIN_LANES", "1"))))
    except ValueError:
        return 1


def gateway_listener_max_lanes():
    try:
        configured = int(os.environ.get("NAPSEER_GATEWAY_RELAY_LISTENER_MAX_LANES", "3"))
    except ValueError:
        configured = 3
    return max(gateway_listener_min_lanes(), min(5, configured))


def gateway_listener_unstable_window_seconds():
    try:
        return max(30, int(os.environ.get("NAPSEER_GATEWAY_RELAY_UNSTABLE_WINDOW_SECONDS", "180")))
    except ValueError:
        return 180


def gateway_listener_target_lanes():
    with GATEWAY_LISTENER_STABILITY_LOCK:
        unstable = time.time() < GATEWAY_LISTENER_UNSTABLE_UNTIL
    return gateway_listener_max_lanes() if unstable else gateway_listener_min_lanes()


def mark_gateway_listener_unstable(reason, lane_id=None):
    global GATEWAY_LISTENER_UNSTABLE_UNTIL
    until = time.time() + gateway_listener_unstable_window_seconds()
    with GATEWAY_LISTENER_STABILITY_LOCK:
        GATEWAY_LISTENER_UNSTABLE_UNTIL = max(GATEWAY_LISTENER_UNSTABLE_UNTIL, until)
    gateway_periodic_log(
        "relay_listener_path_marked_unstable",
        30,
        "relay_listener_path_marked_unstable",
        level="warn",
        lane_id=lane_id,
        reason=reason,
        target_lanes=gateway_listener_max_lanes(),
        unstable_until=datetime.fromtimestamp(until, timezone.utc).isoformat(),
    )


def gateway_listener_lane_ids():
    return [f"lane-{index + 1}" for index in range(gateway_listener_max_lanes())]


def ws_recv_exact(sock, length):
    data = b""
    while len(data) < length:
        chunk = sock.recv(length - len(data))
        if not chunk:
            return data
        data += chunk
    return data


def ws_send_frame(sock, opcode, payload=b""):
    data = payload if isinstance(payload, bytes) else bytes(payload)
    header = bytearray([0x80 | (opcode & 0x0F)])
    if len(data) < 126:
        header.append(0x80 | len(data))
    elif len(data) < 65536:
        header.extend([0x80 | 126, (len(data) >> 8) & 0xff, len(data) & 0xff])
    else:
        header.extend([0x80 | 127])
        header.extend(len(data).to_bytes(8, "big"))
    mask = secrets.token_bytes(4)
    sock.sendall(bytes(header) + mask + bytes(byte ^ mask[index % 4] for index, byte in enumerate(data)))


def ws_send_text(sock, text):
    ws_send_frame(sock, 0x1, text.encode("utf-8"))


def ws_read_text(sock):
    WS_CLOSE_DETAILS.pop(sock.fileno(), None)
    header = ws_recv_exact(sock, 2)
    if len(header) < 2:
        WS_CLOSE_DETAILS[sock.fileno()] = {"reason": "socket closed before websocket frame header completed"}
        return None
    first, second = header
    opcode = first & 0x0F
    length = second & 0x7F
    if length == 126:
        length_bytes = ws_recv_exact(sock, 2)
        if len(length_bytes) < 2:
            WS_CLOSE_DETAILS[sock.fileno()] = {"reason": "socket closed before websocket extended length completed"}
            return None
        length = int.from_bytes(length_bytes, "big")
    elif length == 127:
        length_bytes = ws_recv_exact(sock, 8)
        if len(length_bytes) < 8:
            WS_CLOSE_DETAILS[sock.fileno()] = {"reason": "socket closed before websocket extended length completed"}
            return None
        length = int.from_bytes(length_bytes, "big")
    mask = ws_recv_exact(sock, 4) if second & 0x80 else b""
    if second & 0x80 and len(mask) < 4:
        WS_CLOSE_DETAILS[sock.fileno()] = {"reason": "socket closed before websocket mask completed"}
        return None
    payload = ws_recv_exact(sock, length)
    if len(payload) < length:
        WS_CLOSE_DETAILS[sock.fileno()] = {"reason": "socket closed before websocket frame payload completed"}
        return None
    if mask:
        payload = bytes(byte ^ mask[index % 4] for index, byte in enumerate(payload))
    if opcode == 0x8:
        close_code = None
        close_reason = ""
        if len(payload) >= 2:
            close_code = int.from_bytes(payload[:2], "big")
            close_reason = payload[2:].decode("utf-8", errors="replace")
        elif payload:
            close_reason = payload.decode("utf-8", errors="replace")
        WS_CLOSE_DETAILS[sock.fileno()] = {"code": close_code, "reason": close_reason}
        try:
            ws_send_frame(sock, 0x8, payload)
        except OSError:
            pass
        return None
    if opcode == 0x9:
        ws_send_frame(sock, 0xA, payload)
        return ""
    if opcode != 0x1:
        return ""
    return payload.decode("utf-8", errors="replace")


AES_SBOX = (
    0x63, 0x7C, 0x77, 0x7B, 0xF2, 0x6B, 0x6F, 0xC5, 0x30, 0x01, 0x67, 0x2B, 0xFE, 0xD7, 0xAB, 0x76,
    0xCA, 0x82, 0xC9, 0x7D, 0xFA, 0x59, 0x47, 0xF0, 0xAD, 0xD4, 0xA2, 0xAF, 0x9C, 0xA4, 0x72, 0xC0,
    0xB7, 0xFD, 0x93, 0x26, 0x36, 0x3F, 0xF7, 0xCC, 0x34, 0xA5, 0xE5, 0xF1, 0x71, 0xD8, 0x31, 0x15,
    0x04, 0xC7, 0x23, 0xC3, 0x18, 0x96, 0x05, 0x9A, 0x07, 0x12, 0x80, 0xE2, 0xEB, 0x27, 0xB2, 0x75,
    0x09, 0x83, 0x2C, 0x1A, 0x1B, 0x6E, 0x5A, 0xA0, 0x52, 0x3B, 0xD6, 0xB3, 0x29, 0xE3, 0x2F, 0x84,
    0x53, 0xD1, 0x00, 0xED, 0x20, 0xFC, 0xB1, 0x5B, 0x6A, 0xCB, 0xBE, 0x39, 0x4A, 0x4C, 0x58, 0xCF,
    0xD0, 0xEF, 0xAA, 0xFB, 0x43, 0x4D, 0x33, 0x85, 0x45, 0xF9, 0x02, 0x7F, 0x50, 0x3C, 0x9F, 0xA8,
    0x51, 0xA3, 0x40, 0x8F, 0x92, 0x9D, 0x38, 0xF5, 0xBC, 0xB6, 0xDA, 0x21, 0x10, 0xFF, 0xF3, 0xD2,
    0xCD, 0x0C, 0x13, 0xEC, 0x5F, 0x97, 0x44, 0x17, 0xC4, 0xA7, 0x7E, 0x3D, 0x64, 0x5D, 0x19, 0x73,
    0x60, 0x81, 0x4F, 0xDC, 0x22, 0x2A, 0x90, 0x88, 0x46, 0xEE, 0xB8, 0x14, 0xDE, 0x5E, 0x0B, 0xDB,
    0xE0, 0x32, 0x3A, 0x0A, 0x49, 0x06, 0x24, 0x5C, 0xC2, 0xD3, 0xAC, 0x62, 0x91, 0x95, 0xE4, 0x79,
    0xE7, 0xC8, 0x37, 0x6D, 0x8D, 0xD5, 0x4E, 0xA9, 0x6C, 0x56, 0xF4, 0xEA, 0x65, 0x7A, 0xAE, 0x08,
    0xBA, 0x78, 0x25, 0x2E, 0x1C, 0xA6, 0xB4, 0xC6, 0xE8, 0xDD, 0x74, 0x1F, 0x4B, 0xBD, 0x8B, 0x8A,
    0x70, 0x3E, 0xB5, 0x66, 0x48, 0x03, 0xF6, 0x0E, 0x61, 0x35, 0x57, 0xB9, 0x86, 0xC1, 0x1D, 0x9E,
    0xE1, 0xF8, 0x98, 0x11, 0x69, 0xD9, 0x8E, 0x94, 0x9B, 0x1E, 0x87, 0xE9, 0xCE, 0x55, 0x28, 0xDF,
    0x8C, 0xA1, 0x89, 0x0D, 0xBF, 0xE6, 0x42, 0x68, 0x41, 0x99, 0x2D, 0x0F, 0xB0, 0x54, 0xBB, 0x16,
)
AES_RCON = (0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1B, 0x36)


def _aes_xtime(value):
    value <<= 1
    return ((value ^ 0x11B) if value & 0x100 else value) & 0xFF


def _aes_mix_single_column(column):
    total = column[0] ^ column[1] ^ column[2] ^ column[3]
    first = column[0]
    column[0] ^= total ^ _aes_xtime(column[0] ^ column[1])
    column[1] ^= total ^ _aes_xtime(column[1] ^ column[2])
    column[2] ^= total ^ _aes_xtime(column[2] ^ column[3])
    column[3] ^= total ^ _aes_xtime(column[3] ^ first)


def _aes_add_round_key(state, words, round_index):
    for col in range(4):
        word = words[round_index * 4 + col]
        state[col * 4 + 0] ^= (word >> 24) & 0xFF
        state[col * 4 + 1] ^= (word >> 16) & 0xFF
        state[col * 4 + 2] ^= (word >> 8) & 0xFF
        state[col * 4 + 3] ^= word & 0xFF


def _aes_sub_bytes(state):
    for index, value in enumerate(state):
        state[index] = AES_SBOX[value]


def _aes_shift_rows(state):
    state[1], state[5], state[9], state[13] = state[5], state[9], state[13], state[1]
    state[2], state[6], state[10], state[14] = state[10], state[14], state[2], state[6]
    state[3], state[7], state[11], state[15] = state[15], state[3], state[7], state[11]


def _aes_mix_columns(state):
    for col in range(4):
        start = col * 4
        column = state[start:start + 4]
        _aes_mix_single_column(column)
        state[start:start + 4] = column


def _aes_key_expand_256(key):
    if len(key) != 32:
        raise RuntimeError("AES-256 key must be 32 bytes")
    words = [int.from_bytes(key[index:index + 4], "big") for index in range(0, 32, 4)]
    for index in range(8, 60):
        temp = words[index - 1]
        if index % 8 == 0:
            temp = (
                AES_SBOX[(temp >> 16) & 0xFF] << 24
                | AES_SBOX[(temp >> 8) & 0xFF] << 16
                | AES_SBOX[temp & 0xFF] << 8
                | AES_SBOX[(temp >> 24) & 0xFF]
            ) ^ (AES_RCON[index // 8] << 24)
        elif index % 8 == 4:
            temp = (
                AES_SBOX[(temp >> 24) & 0xFF] << 24
                | AES_SBOX[(temp >> 16) & 0xFF] << 16
                | AES_SBOX[(temp >> 8) & 0xFF] << 8
                | AES_SBOX[temp & 0xFF]
            )
        words.append(words[index - 8] ^ temp)
    return words


def _aes_encrypt_block_256(key, block):
    if len(block) != 16:
        raise RuntimeError("AES block must be 16 bytes")
    words = _aes_key_expand_256(key)
    state = bytearray(block)
    _aes_add_round_key(state, words, 0)
    for round_index in range(1, 14):
        _aes_sub_bytes(state)
        _aes_shift_rows(state)
        _aes_mix_columns(state)
        _aes_add_round_key(state, words, round_index)
    _aes_sub_bytes(state)
    _aes_shift_rows(state)
    _aes_add_round_key(state, words, 14)
    return bytes(state)


def _gcm_gf_mul(left, right):
    z = 0
    v = right
    for bit in range(128):
        if (left >> (127 - bit)) & 1:
            z ^= v
        if v & 1:
            v = (v >> 1) ^ 0xE1000000000000000000000000000000
        else:
            v >>= 1
    return z


def _gcm_ghash(hash_subkey, aad, ciphertext):
    h = int.from_bytes(hash_subkey, "big")
    y = 0
    data = (
        aad
        + (b"\x00" * ((16 - len(aad) % 16) % 16))
        + ciphertext
        + (b"\x00" * ((16 - len(ciphertext) % 16) % 16))
        + (len(aad) * 8).to_bytes(8, "big")
        + (len(ciphertext) * 8).to_bytes(8, "big")
    )
    for offset in range(0, len(data), 16):
        y = _gcm_gf_mul(y ^ int.from_bytes(data[offset:offset + 16], "big"), h)
    return y.to_bytes(16, "big")


def _gcm_inc32(counter):
    prefix = counter[:12]
    value = (int.from_bytes(counter[12:], "big") + 1) & 0xFFFFFFFF
    return prefix + value.to_bytes(4, "big")


def _aes_gcm_crypt(key, nonce, aad, data):
    if len(nonce) != 12:
        raise RuntimeError("AES-GCM nonce must be 12 bytes")
    counter = nonce + b"\x00\x00\x00\x01"
    cursor = _gcm_inc32(counter)
    output = bytearray()
    for offset in range(0, len(data), 16):
        block = data[offset:offset + 16]
        stream = _aes_encrypt_block_256(key, cursor)
        output.extend(bytes(left ^ right for left, right in zip(block, stream)))
        cursor = _gcm_inc32(cursor)
    return bytes(output), counter


def aes_gcm_encrypt(key, nonce, aad, plaintext):
    ciphertext, counter = _aes_gcm_crypt(key, nonce, aad, plaintext)
    hash_subkey = _aes_encrypt_block_256(key, b"\x00" * 16)
    auth = _gcm_ghash(hash_subkey, aad, ciphertext)
    tag_mask = _aes_encrypt_block_256(key, counter)
    tag = bytes(left ^ right for left, right in zip(auth, tag_mask))
    return ciphertext + tag


def aes_gcm_decrypt(key, nonce, aad, packed):
    if len(packed) < 16:
        raise RuntimeError("AES-GCM ciphertext is missing tag")
    ciphertext, tag = packed[:-16], packed[-16:]
    hash_subkey = _aes_encrypt_block_256(key, b"\x00" * 16)
    auth = _gcm_ghash(hash_subkey, aad, ciphertext)
    counter = nonce + b"\x00\x00\x00\x01"
    expected = bytes(left ^ right for left, right in zip(auth, _aes_encrypt_block_256(key, counter)))
    if not hmac.compare_digest(tag, expected):
        raise RuntimeError("AES-GCM authentication failed")
    plaintext, _ = _aes_gcm_crypt(key, nonce, aad, ciphertext)
    return plaintext


def relay_node_crypto(operation, key, aad, nonce, ciphertext=None, payload=None):
    if operation == "decrypt":
        return aes_gcm_decrypt(key, nonce, aad, ciphertext).decode("utf-8")
    if operation == "encrypt":
        plaintext = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.b64encode(aes_gcm_encrypt(key, nonce, aad, plaintext)).decode("ascii")
    raise RuntimeError("unsupported relay crypto operation")


def relay_node_crypto_legacy(operation, key, aad, nonce, ciphertext=None, payload=None):
    script = r"""
const crypto = require('crypto');
const op = process.argv[1];
const key = Buffer.from(process.argv[2], 'base64');
const aad = Buffer.from(process.argv[3], 'base64');
const nonce = Buffer.from(process.argv[4], 'base64');
if (op === 'decrypt') {
  const packed = Buffer.from(process.argv[5], 'base64');
  const body = packed.subarray(0, packed.length - 16);
  const tag = packed.subarray(packed.length - 16);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, nonce);
  decipher.setAAD(aad);
  decipher.setAuthTag(tag);
  process.stdout.write(Buffer.concat([decipher.update(body), decipher.final()]).toString('utf8'));
} else {
  const cipher = crypto.createCipheriv('aes-256-gcm', key, nonce);
  cipher.setAAD(aad);
  const body = Buffer.concat([cipher.update(Buffer.from(process.argv[5], 'utf8')), cipher.final()]);
  process.stdout.write(Buffer.concat([body, cipher.getAuthTag()]).toString('base64'));
}
"""
    args = [
        "node",
        "-e",
        script,
        operation,
        base64.b64encode(key).decode("ascii"),
        base64.b64encode(aad).decode("ascii"),
        base64.b64encode(nonce).decode("ascii"),
        base64.b64encode(ciphertext).decode("ascii") if operation == "decrypt" else json.dumps(payload, separators=(",", ":")),
    ]
    result = subprocess.run(args, check=False, capture_output=True, text=True, timeout=20)
    if result.returncode != 0:
        raise RuntimeError((result.stderr or "relay crypto failed").strip())
    return result.stdout


def decrypt_relay_frame(key, frame_text, context_hash, expected_direction, expected_seq):
    envelope = json.loads(frame_text)
    if (
        envelope.get("context_hash") != context_hash
        or envelope.get("direction") != expected_direction
        or envelope.get("seq") != expected_seq
    ):
        raise RuntimeError("invalid relay frame context")
    plaintext = relay_node_crypto(
        "decrypt",
        key,
        relay_aad(envelope["session_id"], context_hash, expected_direction, expected_seq),
        base64.b64decode(envelope["nonce"]),
        ciphertext=base64.b64decode(envelope["ciphertext"]),
    )
    return json.loads(plaintext)


def encrypt_relay_frame(key, session_id, payload, context_hash, direction, seq):
    nonce = secrets.token_bytes(12)
    ciphertext = relay_node_crypto("encrypt", key, relay_aad(session_id, context_hash, direction, seq), nonce, payload=payload)
    return json.dumps({
        "type": "encrypted",
        "alg": "AES-GCM-256",
        "session_id": session_id,
        "context_hash": context_hash,
        "direction": direction,
        "seq": seq,
        "nonce": base64.b64encode(nonce).decode("ascii"),
        "ciphertext": ciphertext,
    }, separators=(",", ":"))


def handle_gateway_relay_session(connect_request, listener_sock=None):
    project_id = str(connect_request.get("project_id") or current_project_id())
    session_id = str(connect_request["session_id"])
    request_id = connect_request.get("request_id")
    sock = None
    stream_stop = threading.Event()
    try:
        gateway_log(
            "relay_session_starting",
            project_id=project_id,
            agent_id=AUTH.get("agent_id"),
            session_id=session_id,
            request_id=request_id,
            client_account_id=connect_request.get("client_account_id"),
        )
        secret = read_gateway_relay_secret()
        if not secret:
            gateway_log(
                "relay_session_rejected",
                level="error",
                project_id=project_id,
                agent_id=AUTH.get("agent_id"),
                session_id=session_id,
                request_id=request_id,
                reason="missing_gateway_relay_secret",
            )
            raise RuntimeError("gateway relay secret is missing; run nap gateway configure or nap gateway unlock once")
        spake2_context = connect_request.get("spake2_context") or {}
        sock = ws_connect(relay_ws_url(project_id, session_id, connect_request["relay_ticket"]))
        gateway_log("relay_session_socket_connected", project_id=project_id, session_id=session_id, request_id=request_id)
        if listener_sock is not None:
            with GATEWAY_LISTENER_SEND_LOCK:
                ws_send_text(listener_sock, json.dumps({
                    "type": "connect.accept",
                    "request_id": request_id,
                    "session_id": session_id,
                }, separators=(",", ":")))
            gateway_log("relay_session_accepted", project_id=project_id, session_id=session_id, request_id=request_id)

        while True:
            frame_text = ws_read_text(sock)
            if frame_text is None:
                raise RuntimeError("relay closed before gateway authentication")
            if not frame_text:
                continue
            try:
                frame = json.loads(frame_text)
            except Exception:
                continue
            if frame.get("source") == "gateway":
                continue
            if frame.get("type") != "spake2.message":
                continue
            browser_message = str(frame.get("message") or "")
            browser_relay_secret_fingerprint = str(frame.get("relay_secret_fingerprint") or "")
            try:
                spake2_finished = spake2_gateway_finish(secret, spake2_context, browser_message)
            except Exception:
                ws_send_text(sock, json.dumps({
                    "type": "spake2.result",
                    "session_id": session_id,
                    "source": "gateway",
                    "ok": False,
                }, separators=(",", ":")))
                gateway_log(
                    "relay_session_authentication_failed",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    reason="gateway_key_confirmation_failed",
                    relay_secret_fingerprint_match=(
                        bool(browser_relay_secret_fingerprint)
                        and hmac.compare_digest(
                            browser_relay_secret_fingerprint,
                            gateway_relay_secret_fingerprint(secret) or "",
                        )
                    ),
                )
                raise RuntimeError("gateway SPAKE2 key confirmation failed")
            ws_send_text(sock, json.dumps({
                "type": "spake2.confirm",
                "session_id": session_id,
                "source": "gateway",
                "gateway_message": spake2_finished["message"],
            }, separators=(",", ":")))
            break

        while True:
            frame_text = ws_read_text(sock)
            if frame_text is None:
                raise RuntimeError("relay closed before gateway authentication completed")
            if not frame_text:
                continue
            try:
                frame = json.loads(frame_text)
            except Exception:
                continue
            if frame.get("source") == "gateway":
                continue
            if (
                frame.get("type") == "spake2.result"
                and frame.get("ok") is True
            ):
                if hmac.compare_digest(
                    str(frame.get("client_confirmation") or ""),
                    spake2_finished["expected_client_confirmation"],
                ):
                    break
                ws_send_text(sock, json.dumps({
                    "type": "spake2.result",
                    "session_id": session_id,
                    "source": "gateway",
                    "ok": False,
                }, separators=(",", ":")))
                gateway_log(
                    "relay_session_authentication_failed",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    reason="browser_key_confirmation_failed",
                    relay_secret_fingerprint_match=(
                        bool(browser_relay_secret_fingerprint)
                        and hmac.compare_digest(
                            browser_relay_secret_fingerprint,
                            gateway_relay_secret_fingerprint(secret) or "",
                        )
                    ),
                )
                raise RuntimeError("browser SPAKE2 key confirmation failed")
            if frame.get("type") == "spake2.result" and frame.get("ok") is False:
                gateway_log(
                    "relay_session_authentication_failed",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    reason="browser_rejected_gateway",
                )
                raise RuntimeError("browser rejected gateway authentication")

        ws_send_text(sock, json.dumps({
            "type": "spake2.result",
            "session_id": session_id,
            "source": "gateway",
            "ok": True,
            "gateway_confirmation": spake2_finished["confirmation"],
        }, separators=(",", ":")))
        gateway_log("relay_session_authenticated", project_id=project_id, session_id=session_id, request_id=request_id)

        send_key = relay_key_from_secret(spake2_finished["secret"], spake2_context, "gateway_to_client")
        receive_key = relay_key_from_secret(spake2_finished["secret"], spake2_context, "client_to_gateway")
        context_hash = relay_context_hash(spake2_context)
        send_seq = {"value": 0}
        receive_seq = 0
        relay_send_lock = threading.Lock()
        relay_closed = threading.Event()
        rotation_required = gateway_requires_passphrase_rotation()
        rotation_state = gateway_rotation_session_state(
            session_id=session_id,
            project_id=project_id,
            request_id=request_id,
            connect_request=connect_request,
            requires_rotation=rotation_required,
        )
        with GATEWAY_RELAY_SESSION_ROTATION_LOCK:
            GATEWAY_RELAY_SESSION_ROTATION_STATE[str(session_id)] = rotation_state

        def send_gateway_payload(payload):
            if relay_closed.is_set():
                raise RelaySocketClosed("relay socket already closed")
            with relay_send_lock:
                seq = send_seq["value"]
                try:
                    ws_send_text(sock, encrypt_relay_frame(send_key, session_id, payload, context_hash, "gateway_to_client", seq))
                except (BrokenPipeError, ConnectionError, OSError, ssl.SSLError) as exc:
                    relay_closed.set()
                    gateway_log(
                        "relay_send_closed",
                        level="warn",
                        project_id=project_id,
                        session_id=session_id,
                        request_id=request_id,
                        error=str(exc),
                        payload_type=(payload or {}).get("type"),
                    )
                    raise RelaySocketClosed(str(exc)) from exc
                send_seq["value"] = seq + 1

        stream_state = {"stop": None, "terminal_id": None, "target": None, "backend": None, "pty_unsubscribe": None}
        try:
            PTY_INTERACTIVE_FLUSH_SECONDS = max(0.0, int(os.environ.get("NAPSEER_GATEWAY_PTY_INTERACTIVE_FLUSH_MS", "0")) / 1000)
        except Exception:
            PTY_INTERACTIVE_FLUSH_SECONDS = 0.001
        try:
            PTY_IMMEDIATE_FLUSH_BYTES = max(1, int(os.environ.get("NAPSEER_GATEWAY_PTY_IMMEDIATE_FLUSH_BYTES", "256")))
        except Exception:
            PTY_IMMEDIATE_FLUSH_BYTES = 256
        PTY_BULK_FLUSH_BYTES = 4096
        try:
            configured_snapshot_max_bytes = int(os.environ.get("NAPSEER_GATEWAY_PTY_ATTACH_SNAPSHOT_BYTES", str(16 * 1024)))
        except Exception:
            configured_snapshot_max_bytes = 16 * 1024
        PTY_ATTACH_SNAPSHOT_MAX_BYTES = max(
            4096,
            min(configured_snapshot_max_bytes, 64 * 1024),
        )

        pty_output_state = {
            "lock": threading.Lock(),
            "buffer": bytearray(),
            "seq": 0,
            "timer": None,
            "terminal_id": None,
            "latency_by_terminal": {},
        }

        def flush_pty_terminal_output():
            with pty_output_state["lock"]:
                timer = pty_output_state.get("timer")
                if timer is not None:
                    timer.cancel()
                    pty_output_state["timer"] = None
                data = bytes(pty_output_state["buffer"])
                pty_output_state["buffer"].clear()
                seq = pty_output_state["seq"]
                terminal_id = pty_output_state.get("terminal_id")
                latency = dict((pty_output_state.get("latency_by_terminal") or {}).get(str(terminal_id)) or {})
                if latency and float(latency.get("expires_at") or 0) < time.time():
                    latency = {}
            if not data or not terminal_id:
                return
            from terminal.protocol import output_frame

            try:
                send_gateway_payload({
                    **output_frame(str(terminal_id), int(seq), data),
                    "source": "gateway",
                    "mode": "stream",
                    **{key: value for key, value in latency.items() if key != "expires_at"},
                    "sent_at": iso_now(),
                })
            except RelaySocketClosed:
                pass

        def stop_terminal_stream():
            flush_pty_terminal_output()
            current = stream_state.get("stop")
            if current is not None:
                current.set()
                stream_state["stop"] = None
            current_pty = stream_state.get("pty_unsubscribe")
            if current_pty is not None:
                try:
                    current_pty()
                except Exception:
                    pass
                stream_state["pty_unsubscribe"] = None

        def start_terminal_stream(target):
            stop_terminal_stream()
            next_stop = threading.Event()
            stream_state["stop"] = next_stop

            def send_terminal_payload(payload):
                send_gateway_payload(gateway_terminal_output_payload(payload, stream_state.get("terminal_id")))

            stream_thread = threading.Thread(
                target=gateway_terminal_stream_loop,
                args=(next_stop, send_terminal_payload, project_id, session_id, request_id, target),
                name=f"napseer-terminal-stream-{session_id}",
                daemon=True,
            )
            stream_thread.start()

        def send_pty_terminal_chunk(terminal_id, seq, data):
            should_flush = False
            with pty_output_state["lock"]:
                pty_output_state["terminal_id"] = terminal_id
                pty_output_state["seq"] = seq
                pty_output_state["buffer"].extend(data)
                should_flush = (
                    len(data) <= PTY_IMMEDIATE_FLUSH_BYTES
                    or len(pty_output_state["buffer"]) >= PTY_BULK_FLUSH_BYTES
                    or data.endswith((b"\n", b"\r"))
                )
                if not should_flush and pty_output_state.get("timer") is None:
                    if PTY_INTERACTIVE_FLUSH_SECONDS <= 0:
                        should_flush = True
                    else:
                        timer = threading.Timer(PTY_INTERACTIVE_FLUSH_SECONDS, flush_pty_terminal_output)
                        timer.daemon = True
                        pty_output_state["timer"] = timer
                        timer.start()
            if should_flush:
                flush_pty_terminal_output()

        def pty_attach_snapshot_bytes(snapshot_max_bytes=None):
            try:
                requested = int(snapshot_max_bytes) if snapshot_max_bytes is not None else PTY_ATTACH_SNAPSHOT_MAX_BYTES
            except Exception:
                requested = PTY_ATTACH_SNAPSHOT_MAX_BYTES
            return max(4096, min(requested, PTY_ATTACH_SNAPSHOT_MAX_BYTES))

        def pty_compact_snapshot_data(chunks, max_bytes):
            if max_bytes <= 0:
                return b""
            selected = []
            total = 0
            for chunk in reversed(chunks):
                data = bytes(chunk.data)
                if not data:
                    continue
                selected.append(data)
                total += len(data)
                if total >= max_bytes:
                    break
            if not selected:
                return b""
            snapshot_data = b"".join(reversed(selected))
            return snapshot_data[-max_bytes:]

        def start_pty_terminal_stream(terminal_id, last_output_seq=None, snapshot=False, snapshot_max_bytes=None):
            stop_terminal_stream()
            from terminal.protocol import output_frame, replay_gap_frame

            try:
                requested_after_seq = int(last_output_seq) if last_output_seq is not None else None
            except Exception:
                requested_after_seq = None
            use_snapshot = bool(snapshot) or requested_after_seq is None or requested_after_seq <= 0
            attach = gateway_pty_manager().attach(
                terminal_id,
                last_output_seq=None if use_snapshot else requested_after_seq,
            )
            if attach.replay_gap:
                send_gateway_payload({
                    **replay_gap_frame(
                        terminal_id,
                        requested_after_seq=attach.requested_after_seq,
                        oldest_seq=attach.oldest_seq,
                        newest_seq=attach.newest_seq,
                    ),
                    "source": "gateway",
                    "sent_at": iso_now(),
                })
            if use_snapshot:
                max_snapshot_bytes = pty_attach_snapshot_bytes(snapshot_max_bytes)
                snapshot_data = pty_compact_snapshot_data(attach.chunks, max_snapshot_bytes)
                if snapshot_data and attach.newest_seq > 0:
                    send_gateway_payload({
                        **output_frame(terminal_id, attach.newest_seq, snapshot_data),
                        "source": "gateway",
                        "mode": "snapshot",
                        "snapshot": True,
                        "snapshot_bytes": len(snapshot_data),
                        "snapshot_max_bytes": max_snapshot_bytes,
                        "snapshot_truncated": len(snapshot_data) >= max_snapshot_bytes,
                        "sent_at": iso_now(),
                    })
            else:
                for chunk in attach.chunks:
                    send_gateway_payload({
                        **output_frame(terminal_id, chunk.seq, chunk.data),
                        "source": "gateway",
                        "mode": "replay",
                        "sent_at": iso_now(),
                    })
            stream_state["pty_unsubscribe"] = gateway_pty_manager().subscribe(terminal_id, send_pty_terminal_chunk)

        def pty_open_snapshot_requested(frame):
            if bool(frame.get("snapshot")):
                return True
            try:
                return int(frame.get("last_output_seq")) <= 0
            except Exception:
                return frame.get("last_output_seq") is None

        def send_terminal_sessions():
            sessions = gateway_terminal_sessions({
                "terminal_id": stream_state.get("terminal_id"),
                "remote_authenticated": True,
            })
            selected = sessions.get("selected_terminal") or {}
            stream_state["terminal_id"] = sessions.get("selected_terminal_id")
            stream_state["backend"] = selected.get("backend")
            if selected.get("target"):
                stream_state["target"] = selected.get("target")
            public_sessions = []
            for item in sessions.get("sessions") or []:
                public_sessions.append({key: value for key, value in item.items() if key != "target"})
            send_gateway_payload({
                "type": "terminal.session_list",
                "source": "gateway",
                "sessions": public_sessions,
                "selected_terminal_id": sessions.get("selected_terminal_id"),
                "sent_at": iso_now(),
            })
            return sessions

        def send_terminal_opened(selected, attached=True):
            from terminal.protocol import opened_frame

            send_gateway_payload({
                **opened_frame(
                    str(selected.get("id")),
                    rows=int(selected.get("rows") or 24),
                    cols=int(selected.get("cols") or 80),
                    output_seq=int(selected.get("output_seq") or 0),
                    attached=attached,
                ),
                "source": "gateway",
                "sent_at": iso_now(),
            })

        def send_empty_terminal_sessions(message):
            stream_state["terminal_id"] = None
            stream_state["target"] = None
            stream_state["backend"] = None
            send_gateway_payload({
                "type": "terminal.session_list",
                "source": "gateway",
                "sessions": [],
                "selected_terminal_id": None,
                "message": str(message),
                "sent_at": iso_now(),
            })

        def switch_terminal(terminal_id=None):
            backend, selected = gateway_terminal_backend_from_id(terminal_id, remote_authenticated=True)
            stream_state["terminal_id"] = selected.get("id")
            stream_state["backend"] = backend
            stream_state["target"] = selected.get("target")
            send_terminal_sessions()
            if backend == "pty":
                send_terminal_opened(selected)
                start_pty_terminal_stream(str(selected.get("id")), snapshot=True)
            else:
                start_terminal_stream(selected["target"])
            return selected

        def send_terminal_error(message):
            send_gateway_payload({
                "type": "terminal.status",
                "source": "gateway",
                "status": "error",
                "message": str(message),
                "sent_at": iso_now(),
            })

        def send_gateway_schedules():
            schedules = gateway_schedule_list({"remote_authenticated": True}).get("schedules") or []
            send_gateway_payload({
                "type": "schedule.list",
                "source": "gateway",
                "schedules": schedules,
                "sent_at": iso_now(),
            })
            return schedules

        def send_schedule_status(status, message=None):
            send_gateway_payload({
                "type": "schedule.status",
                "source": "gateway",
                "status": status,
                "message": message or "",
                "sent_at": iso_now(),
            })

        def send_schedule_error(message):
            send_gateway_payload({
                "type": "schedule.error",
                "source": "gateway",
                "message": str(message),
                "sent_at": iso_now(),
            })

        send_gateway_payload({
            "type": "terminal.status",
            "source": "gateway",
            "status": "connected",
            "sent_at": iso_now(),
        })
        if rotation_state.get("allowed_frame_mode") == "rotation_only":
            try:
                send_gateway_payload(gateway_rotation_result_payload(
                    status="retry_required",
                    code="rotation_required",
                    retry_required=True,
                ))
            except RelaySocketClosed:
                return
        else:
            try:
                switch_terminal(None)
            except RelaySocketClosed:
                gateway_log(
                    "relay_terminal_startup_closed",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                )
                return
            except Exception as startup_exc:
                gateway_log(
                    "relay_terminal_startup_error",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    error=str(startup_exc),
                )
                try:
                    send_terminal_error(startup_exc)
                    send_empty_terminal_sessions(startup_exc)
                except RelaySocketClosed:
                    return
            try:
                send_gateway_schedules()
            except RelaySocketClosed:
                return
        gateway_log("relay_session_open", project_id=project_id, session_id=session_id, request_id=request_id)
        while True:
            frame_text = ws_read_text(sock)
            if frame_text is None:
                break
            if not frame_text:
                continue
            try:
                parsed = json.loads(frame_text)
            except Exception:
                continue
            if parsed.get("type") != "encrypted":
                continue
            if parsed.get("direction") != "client_to_gateway":
                continue
            frame = decrypt_relay_frame(receive_key, frame_text, context_hash, "client_to_gateway", receive_seq)
            receive_seq += 1
            if frame.get("source") == "gateway":
                continue
            try:
                frame_type = frame.get("type")
                rotation_decision = gateway_rotation_gate_decision(frame_type, rotation_state)
                if not rotation_decision["allowed"]:
                    rotation_state["blocked_frames"] = int(rotation_state.get("blocked_frames") or 0) + 1
                    gateway_log(
                        "relay_frame_blocked_by_rotation",
                        level="warn",
                        project_id=project_id,
                        session_id=session_id,
                        request_id=request_id,
                        frame_type=frame_type,
                        frame_class=rotation_decision["frame_class"],
                    )
                    send_gateway_payload(gateway_rotation_result_payload(
                        status="retry_required",
                        code="rotation_required",
                        retry_required=True,
                    ))
                    continue
                if frame_type == "gateway.passphrase_rotation.challenge.request":
                    rotation_state["rotation_gate_state"] = "challenge_issued"
                    rotation_state["pending_challenge"] = {
                        "issued_at": iso_now(),
                        "challenge_id": uuid.uuid4().hex,
                        "consumed": False,
                    }
                    send_gateway_payload(gateway_rotation_result_payload(
                        status="retry_required",
                        code="rotation_required",
                        retry_required=True,
                    ))
                    continue
                if frame_type == "gateway.passphrase_rotation.prove":
                    pending = rotation_state.get("pending_challenge") or {}
                    if pending and not pending.get("consumed"):
                        pending["consumed"] = True
                        rotation_state["rotation_gate_state"] = "proof_consumed"
                    rotation_state["failed_rotation_attempts"] = int(rotation_state.get("failed_rotation_attempts") or 0) + 1
                    send_gateway_payload(gateway_rotation_result_payload(
                        status="retry_required",
                        code="challenge_consumed_retry_required",
                        retry_required=True,
                    ))
                    continue
                if frame_type == "terminal.input":
                    gateway_log("relay_terminal_input_received", project_id=project_id, session_id=session_id, request_id=request_id)
                    terminal_args = {
                        **gateway_terminal_route_args(frame, stream_state),
                        "input": frame.get("data") or frame.get("input") or "",
                        "enter": frame.get("enter", True),
                        "enter_delay_ms": frame.get("enter_delay_ms", 150),
                        "stream": True,
                    }
                    gateway_terminal_input(terminal_args)
                elif frame_type == "terminal.open":
                    gateway_log("relay_terminal_open_requested", project_id=project_id, session_id=session_id, request_id=request_id, terminal_id=frame.get("terminal_id"))
                    if not gateway_pty_terminal_enabled():
                        switch_terminal(frame.get("terminal_id"))
                    else:
                        requested_terminal_id = str(frame.get("terminal_id") or "").strip()
                        if requested_terminal_id:
                            backend, selected = gateway_terminal_backend_from_id(requested_terminal_id, remote_authenticated=True)
                            stream_state["terminal_id"] = selected.get("id")
                            stream_state["backend"] = backend
                            stream_state["target"] = selected.get("target")
                            send_terminal_sessions()
                            if backend == "pty":
                                send_terminal_opened(selected)
                                start_pty_terminal_stream(
                                    str(selected.get("id")),
                                    frame.get("last_output_seq"),
                                    snapshot=pty_open_snapshot_requested(frame),
                                    snapshot_max_bytes=frame.get("snapshot_max_bytes"),
                                )
                            else:
                                start_terminal_stream(selected["target"])
                        else:
                            try:
                                backend, selected = gateway_terminal_backend_from_id(None, remote_authenticated=True)
                            except Exception as attach_exc:
                                send_terminal_error(attach_exc)
                                send_empty_terminal_sessions(attach_exc)
                                continue
                            stream_state["terminal_id"] = selected.get("id")
                            stream_state["backend"] = backend
                            stream_state["target"] = selected.get("target")
                            send_terminal_sessions()
                            if backend == "pty":
                                send_terminal_opened(selected)
                                start_pty_terminal_stream(
                                    str(selected.get("id")),
                                    frame.get("last_output_seq"),
                                    snapshot=pty_open_snapshot_requested(frame),
                                    snapshot_max_bytes=frame.get("snapshot_max_bytes"),
                                )
                            else:
                                start_terminal_stream(selected["target"])
                elif frame_type == "terminal.data":
                    if not gateway_pty_terminal_enabled():
                        continue
                    from terminal.protocol import decode_bytes

                    gateway_received_at = iso_now()
                    backend, selected = gateway_terminal_backend_from_id(frame.get("terminal_id") or stream_state.get("terminal_id"), remote_authenticated=True)
                    if backend != "pty":
                        raise RuntimeError("terminal.data requires a PTY-backed terminal")
                    gateway_pty_manager().write(
                        str(selected["id"]),
                        decode_bytes(str(frame.get("data_b64") or "")),
                        input_seq=int(frame["seq"]) if frame.get("seq") is not None else None,
                    )
                    with pty_output_state["lock"]:
                        latency_by_terminal = pty_output_state.get("latency_by_terminal") or {}
                        latency_by_terminal[str(selected["id"])] = {
                            "browser_input_sent_at": frame.get("browser_input_sent_at"),
                            "gateway_received_at": gateway_received_at,
                            "pty_written_at": iso_now(),
                            "expires_at": time.time() + 2.0,
                        }
                        pty_output_state["latency_by_terminal"] = latency_by_terminal
                elif frame_type == "terminal.key":
                    gateway_log("relay_terminal_key_received", project_id=project_id, session_id=session_id, request_id=request_id)
                    terminal_args = {
                        **gateway_terminal_route_args(frame, stream_state),
                        "key": frame.get("key"),
                        "text": frame.get("text"),
                    }
                    gateway_terminal_key(terminal_args)
                elif frame_type == "terminal.capture":
                    gateway_log("relay_terminal_capture_requested", project_id=project_id, session_id=session_id, request_id=request_id)
                    terminal_args = {
                        **gateway_terminal_route_args(frame, stream_state),
                        "start": frame.get("start", "-200"),
                    }
                    result = gateway_terminal_capture(terminal_args)
                    send_gateway_payload(gateway_terminal_output_payload({
                        "type": "terminal.output",
                        "source": "gateway",
                        "mode": "snapshot",
                        "data": gateway_terminal_bound_output(result.get("output", "")),
                        "sent_at": iso_now(),
                    }, stream_state.get("terminal_id")))
                elif frame_type == "terminal.list":
                    gateway_log("relay_terminal_list_requested", project_id=project_id, session_id=session_id, request_id=request_id)
                    send_terminal_sessions()
                elif frame_type == "terminal.select":
                    gateway_log(
                        "relay_terminal_select_requested",
                        project_id=project_id,
                        session_id=session_id,
                        request_id=request_id,
                        terminal_id=frame.get("terminal_id"),
                    )
                    switch_terminal(frame.get("terminal_id"))
                elif frame_type == "terminal.create":
                    gateway_log("relay_terminal_create_requested", project_id=project_id, session_id=session_id, request_id=request_id)
                    created = gateway_terminal_create({
                        "name": frame.get("name"),
                        "remote_authenticated": True,
                    })
                    selected = created.get("selected_terminal") or {}
                    stream_state["terminal_id"] = created.get("selected_terminal_id")
                    stream_state["backend"] = selected.get("backend")
                    stream_state["target"] = selected.get("target") or stream_state.get("target")
                    send_terminal_sessions()
                    if selected.get("backend") == "pty" and stream_state.get("terminal_id"):
                        send_terminal_opened(selected, attached=False)
                        start_pty_terminal_stream(str(stream_state["terminal_id"]), snapshot=True)
                    elif stream_state.get("target"):
                        start_terminal_stream(stream_state["target"])
                elif frame_type == "terminal.close":
                    gateway_log(
                        "relay_terminal_close_requested",
                        project_id=project_id,
                        session_id=session_id,
                        request_id=request_id,
                        terminal_id=frame.get("terminal_id"),
                    )
                    closed = gateway_terminal_close({
                        "terminal_id": frame.get("terminal_id"),
                        "selected_terminal_id": stream_state.get("terminal_id"),
                        "create_replacement": frame.get("create_replacement", True),
                        "remote_authenticated": True,
                    })
                    selected = closed.get("selected_terminal") or {}
                    stream_state["terminal_id"] = closed.get("selected_terminal_id")
                    stream_state["backend"] = selected.get("backend")
                    stream_state["target"] = selected.get("target") or stream_state.get("target")
                    send_terminal_sessions()
                    if selected.get("backend") == "pty" and stream_state.get("terminal_id"):
                        start_pty_terminal_stream(str(stream_state.get("terminal_id")), snapshot=True)
                    elif stream_state.get("target"):
                        start_terminal_stream(stream_state["target"])
                elif frame_type == "terminal.resize":
                    gateway_log("relay_terminal_resize_received", project_id=project_id, session_id=session_id, request_id=request_id)
                    if gateway_pty_terminal_enabled():
                        backend, selected = gateway_terminal_backend_from_id(frame.get("terminal_id") or stream_state.get("terminal_id"), remote_authenticated=True)
                        if backend == "pty":
                            gateway_pty_manager().resize(str(selected["id"]), int(frame.get("rows") or 24), int(frame.get("cols") or 80))
                        else:
                            send_gateway_payload({
                                "type": "terminal.status",
                                "source": "gateway",
                                "status": "resize ignored",
                                "sent_at": iso_now(),
                            })
                    else:
                        send_gateway_payload({
                            "type": "terminal.status",
                            "source": "gateway",
                            "status": "resize ignored",
                            "sent_at": iso_now(),
                        })
                elif frame_type == "heartbeat":
                    send_gateway_payload({
                        "type": "heartbeat",
                        "source": "gateway",
                        "status": "ok",
                        "sent_at": iso_now(),
                    })
                elif frame_type == "schedule.list":
                    gateway_log("relay_schedule_list_requested", project_id=project_id, session_id=session_id, request_id=request_id)
                    send_gateway_schedules()
                elif frame_type == "schedule.create":
                    gateway_log("relay_schedule_create_requested", project_id=project_id, session_id=session_id, request_id=request_id)
                    gateway_schedule_create({
                        "name": frame.get("name"),
                        "terminal_id": frame.get("terminal_id"),
                        "message": frame.get("message") or frame.get("text"),
                        "cron_expr": frame.get("cron_expr"),
                        "enabled": frame.get("enabled", True),
                        "remote_authenticated": True,
                    })
                    send_schedule_status("created")
                    send_gateway_schedules()
                elif frame_type == "schedule.update":
                    gateway_log("relay_schedule_update_requested", project_id=project_id, session_id=session_id, request_id=request_id, schedule_id=frame.get("schedule_id") or frame.get("id"))
                    schedule_payload = {
                        "schedule_id": frame.get("schedule_id") or frame.get("id"),
                        "name": frame.get("name"),
                        "terminal_id": frame.get("terminal_id"),
                        "message": frame.get("message") or frame.get("text"),
                        "cron_expr": frame.get("cron_expr"),
                        "remote_authenticated": True,
                    }
                    if "enabled" in frame:
                        schedule_payload["enabled"] = frame.get("enabled")
                    gateway_schedule_update(schedule_payload)
                    send_schedule_status("updated")
                    send_gateway_schedules()
                elif frame_type == "schedule.delete":
                    gateway_log("relay_schedule_delete_requested", project_id=project_id, session_id=session_id, request_id=request_id, schedule_id=frame.get("schedule_id") or frame.get("id"))
                    gateway_schedule_delete({
                        "schedule_id": frame.get("schedule_id") or frame.get("id"),
                        "remote_authenticated": True,
                    })
                    send_schedule_status("deleted")
                    send_gateway_schedules()
                elif frame_type == "schedule.run_now":
                    gateway_log("relay_schedule_run_now_requested", project_id=project_id, session_id=session_id, request_id=request_id, schedule_id=frame.get("schedule_id") or frame.get("id"))
                    gateway_schedule_run_now({
                        "schedule_id": frame.get("schedule_id") or frame.get("id"),
                        "remote_authenticated": True,
                    })
                    send_schedule_status("ran")
                    send_gateway_schedules()
            except Exception as frame_exc:
                if isinstance(frame_exc, RelaySocketClosed):
                    gateway_log(
                        "relay_terminal_control_closed",
                        level="warn",
                        project_id=project_id,
                        session_id=session_id,
                        request_id=request_id,
                        frame_type=frame.get("type"),
                        error=str(frame_exc),
                    )
                    break
                gateway_log(
                    "relay_terminal_control_error",
                    level="warn",
                    project_id=project_id,
                    session_id=session_id,
                    request_id=request_id,
                    error=str(frame_exc),
                    frame_type=frame.get("type"),
                )
                if str(frame.get("type") or "").startswith("schedule."):
                    try:
                        send_schedule_error(frame_exc)
                    except RelaySocketClosed:
                        break
                    try:
                        send_gateway_schedules()
                    except RelaySocketClosed:
                        break
                    except Exception:
                        pass
                else:
                    try:
                        send_terminal_error(frame_exc)
                    except RelaySocketClosed:
                        break
    except Exception as exc:
        if isinstance(exc, RelaySocketClosed):
            gateway_log(
                "relay_session_closed_by_socket",
                level="warn",
                project_id=project_id,
                agent_id=AUTH.get("agent_id"),
                session_id=session_id,
                request_id=request_id,
                error=str(exc),
            )
            return
        if listener_sock is not None:
            try:
                with GATEWAY_LISTENER_SEND_LOCK:
                    ws_send_text(listener_sock, json.dumps({
                        "type": "connect.reject",
                        "request_id": request_id,
                        "session_id": session_id,
                        "error": str(exc),
                    }, separators=(",", ":")))
            except OSError:
                pass
        gateway_log(
            "relay_session_error",
            level="error",
            project_id=project_id,
            agent_id=AUTH.get("agent_id"),
            session_id=session_id,
            request_id=request_id,
            error=str(exc),
        )
        raise
    finally:
        try:
            relay_closed.set()
        except Exception:
            pass
        try:
            stop_terminal_stream()
        except Exception:
            stream_stop.set()
        GATEWAY_RELAY_THREADS.discard(session_id)
        with GATEWAY_RELAY_SESSION_ROTATION_LOCK:
            GATEWAY_RELAY_SESSION_ROTATION_STATE.pop(str(session_id), None)
        if sock:
            try:
                sock.close()
            except OSError:
                pass
        gateway_log(
            "relay_session_closed",
            project_id=project_id,
            agent_id=AUTH.get("agent_id"),
            session_id=session_id,
            request_id=request_id,
        )


def gateway_relay_loop(lane_id="lane-1"):
    global GATEWAY_LISTENER_CONNECTED, GATEWAY_LISTENER_LAST_CONNECTED_AT, GATEWAY_LISTENER_LAST_ERROR, GATEWAY_LISTENER_LAST_ERROR_AT
    closed_by_relay_streak = 0
    gateway_log(
        "relay_listener_thread_started",
        project_id=current_project_id(),
        agent_id=AUTH.get("agent_id"),
        base_url=relay_base_url(),
        lane_id=lane_id,
    )
    while True:
        closed_by_relay = False
        try:
            lane_index = int(str(lane_id).rsplit("-", 1)[-1]) if str(lane_id).rsplit("-", 1)[-1].isdigit() else 1
            if gateway_remote_should_run() and lane_index <= gateway_listener_target_lanes():
                ensure_gateway_worker_capability(refresh=True)
                project_id = current_project_id()
                agent_id = AUTH.get("agent_id")
                gateway_periodic_log(
                    "relay_listener_connecting",
                    30,
                    "relay_listener_connecting",
                    project_id=project_id,
                    agent_id=agent_id,
                    base_url=relay_base_url(),
                    lane_id=lane_id,
                    target_lanes=gateway_listener_target_lanes(),
                )
                listener = ws_connect(
                    gateway_listener_ws_url(project_id, agent_id),
                    extra_headers={
                        "Authorization": f"Bearer {TOKEN}",
                        "X-Napseer-Gateway-Lane-Id": lane_id,
                    },
                )
                connected_at = time.time()
                with GATEWAY_LISTENER_STABILITY_LOCK:
                    GATEWAY_LISTENER_ACTIVE_LANES.add(lane_id)
                    GATEWAY_LISTENER_CONNECTED = bool(GATEWAY_LISTENER_ACTIVE_LANES)
                GATEWAY_LISTENER_LAST_CONNECTED_AT = iso_now()
                GATEWAY_LISTENER_LAST_ERROR = ""
                GATEWAY_LISTENER_LAST_ERROR_AT = None
                gateway_log("relay_listener_connected", project_id=project_id, agent_id=agent_id, base_url=relay_base_url(), lane_id=lane_id, active_lanes=sorted(GATEWAY_LISTENER_ACTIVE_LANES))
                try:
                    while gateway_remote_should_run():
                        message = ws_read_text(listener)
                        if message is None:
                            close_details = WS_CLOSE_DETAILS.pop(listener.fileno(), {})
                            gateway_log(
                                "relay_listener_closed_by_relay",
                                project_id=project_id,
                                agent_id=agent_id,
                                lane_id=lane_id,
                                close_code=close_details.get("code"),
                                close_reason=close_details.get("reason"),
                            )
                            closed_by_relay = True
                            break
                        if not message:
                            continue
                        payload = json.loads(message)
                        if payload.get("type") != "connect.request":
                            gateway_log(
                                "relay_listener_message_ignored",
                                level="warn",
                                project_id=project_id,
                                agent_id=agent_id,
                                lane_id=lane_id,
                                message_type=payload.get("type"),
                            )
                            continue
                        session_id = payload.get("session_id")
                        if session_id and session_id not in GATEWAY_RELAY_THREADS:
                            gateway_log(
                                "relay_session_requested",
                                project_id=payload.get("project_id") or project_id,
                                agent_id=agent_id,
                                lane_id=lane_id,
                                session_id=session_id,
                                request_id=payload.get("request_id"),
                                client_account_id=payload.get("client_account_id"),
                            )
                            GATEWAY_RELAY_THREADS.add(session_id)
                            threading.Thread(
                                target=lambda item=payload: handle_gateway_relay_session(item, listener),
                                name=f"napseer-relay-{session_id}",
                                daemon=True,
                            ).start()
                            gateway_log(
                                "relay_session_thread_started",
                                project_id=payload.get("project_id") or project_id,
                                agent_id=agent_id,
                                lane_id=lane_id,
                                session_id=session_id,
                                request_id=payload.get("request_id"),
                            )
                        elif session_id:
                            gateway_log(
                                "relay_session_duplicate_ignored",
                                level="warn",
                                project_id=payload.get("project_id") or project_id,
                                agent_id=agent_id,
                                lane_id=lane_id,
                                session_id=session_id,
                                request_id=payload.get("request_id"),
                            )
                finally:
                    connected_duration = time.time() - connected_at if "connected_at" in locals() else 0
                    with GATEWAY_LISTENER_STABILITY_LOCK:
                        GATEWAY_LISTENER_ACTIVE_LANES.discard(lane_id)
                        GATEWAY_LISTENER_CONNECTED = bool(GATEWAY_LISTENER_ACTIVE_LANES)
                    try:
                        listener.close()
                    except OSError:
                        pass
                    gateway_log("relay_listener_disconnected", project_id=project_id, agent_id=agent_id, lane_id=lane_id, connected_duration_seconds=round(connected_duration, 3), active_lanes=sorted(GATEWAY_LISTENER_ACTIVE_LANES))
                    if connected_duration < 20:
                        mark_gateway_listener_unstable("short_lived_connection", lane_id=lane_id)
                if closed_by_relay:
                    closed_by_relay_streak += 1
                    if closed_by_relay_streak >= 2:
                        mark_gateway_listener_unstable("repeated_relay_closes", lane_id=lane_id)
                    delay = min(30.0, 2.0 + (closed_by_relay_streak * 2.0)) + random.uniform(0.0, 1.5)
                    gateway_periodic_log(
                        "relay_listener_backoff",
                        30,
                        "relay_listener_backoff",
                        level="warn",
                        project_id=project_id,
                        agent_id=agent_id,
                        lane_id=lane_id,
                        reconnect_delay_seconds=round(delay, 2),
                        closed_by_relay_streak=closed_by_relay_streak,
                    )
                    time.sleep(delay)
                    continue
                closed_by_relay_streak = 0
            else:
                closed_by_relay_streak = 0
                readiness = gateway_remote_readiness()
                blockers = gateway_remote_blockers(readiness)
                gateway_periodic_log(
                    "relay_listener_waiting",
                    60,
                    "relay_listener_waiting",
                    level="warn",
                    project_id=readiness.get("project_id"),
                    agent_id=readiness.get("agent_id"),
                    lane_id=lane_id,
                    target_lanes=gateway_listener_target_lanes(),
                    has_token=readiness.get("has_token"),
                    remote_enabled=readiness.get("remote_enabled"),
                    relay_secret_configured=readiness.get("relay_secret_configured"),
                    blockers=blockers,
                    reason=",".join(blockers) if blockers else "waiting",
                )
        except Exception as exc:
            closed_by_relay_streak = 0
            with GATEWAY_LISTENER_STABILITY_LOCK:
                GATEWAY_LISTENER_ACTIVE_LANES.discard(lane_id)
                GATEWAY_LISTENER_CONNECTED = bool(GATEWAY_LISTENER_ACTIVE_LANES)
            GATEWAY_LISTENER_LAST_ERROR = str(exc)
            GATEWAY_LISTENER_LAST_ERROR_AT = iso_now()
            mark_gateway_listener_unstable(type(exc).__name__, lane_id=lane_id)
            gateway_periodic_log(
                "relay_listener_error",
                30,
                "relay_listener_error",
                level="error",
                project_id=current_project_id(),
                agent_id=AUTH.get("agent_id"),
                base_url=relay_base_url(),
                lane_id=lane_id,
                error=str(exc),
            )
            send_telemetry_event_async(
                "gateway_listener_error",
                "gateway",
                "error",
                error_class=exc.__class__.__name__,
                error_code=telemetry_error_code(exc),
                gateway_remote_enabled=gateway_remote_should_run(),
                relay_listener_unstable=time.time() < GATEWAY_LISTENER_UNSTABLE_UNTIL,
            )
        time.sleep(2 + random.uniform(0.0, 1.0))


def start_gateway_relay_thread():
    for lane_id in gateway_listener_lane_ids():
        threading.Thread(
            target=lambda lane=lane_id: gateway_relay_loop(lane),
            name=f"napseer-gateway-relay-{lane_id}",
            daemon=True,
        ).start()


def load_auth(public_override=None, secret_override=None):
    data = public_override if public_override is not None else load_public_auth_file()
    secrets_map = secret_override or {}
    merged = {**data, **secrets_map}
    return {
        "base_url": os.environ.get("NAPSEER_BASE_URL") or merged.get("base_url") or "https://api.napseer.com",
        "token": os.environ.get("NAPSEER_TOKEN") or merged.get("token") or merged.get("access_token"),
        "token_expires_at": merged.get("token_expires_at"),
        "local_auth_secret": os.environ.get("NAPSEER_LOCAL_AUTH_SECRET") or merged.get("local_auth_secret"),
        "local_auth_purpose": os.environ.get("NAPSEER_LOCAL_AUTH_PURPOSE") or merged.get("local_auth_purpose"),
        "project_id": os.environ.get("NAPSEER_PROJECT_ID") or merged.get("project_id"),
        "project_slug": merged.get("project_slug"),
        "project_name": merged.get("project_name"),
        "project_signing_key_fingerprint": merged.get("project_signing_key_fingerprint"),
        "worker_id": merged.get("worker_id"),
        "agent_id": merged.get("agent_id"),
        "worker_name": merged.get("worker_name") or "napseer-agent",
        "device_fingerprint": merged.get("device_fingerprint") or socket.gethostname(),
        "root_path": merged.get("root_path") or str(pathlib.Path.cwd()),
        "ssh_key_path": merged.get("ssh_key_path") or str(DEFAULT_KEY_PATH),
        "ssh_private_key": merged.get("ssh_private_key"),
        "ssh_public_key": merged.get("ssh_public_key"),
        "worker_capabilities": merged.get("worker_capabilities") or {"local_mcp": True, "mcp_wrapper": SCRIPT_NAME},
        "account_mode": merged.get("account_mode"),
        "service_registration_id": merged.get("service_registration_id"),
    }


AUTH = load_auth()
BASE_URL = AUTH["base_url"].rstrip("/")
TOKEN = AUTH["token"]
LOCAL_AUTH_SECRET = AUTH.get("local_auth_secret")
LOCAL_AUTH_PURPOSE = AUTH.get("local_auth_purpose")
DEFAULT_PROJECT_ID = AUTH["project_id"]
TOKEN_EXPIRES_AT = AUTH["token_expires_at"]
PROTOCOL_VERSION = "2025-11-25"
SCHEDULE_SIGNATURE_NAMESPACE = "napseer-schedule-v1"
HTTP_TIMEOUT_SECONDS = int(os.environ.get("NAPSEER_HTTP_TIMEOUT_SECONDS", "30"))


def send(message):
    sys.stdout.write(json.dumps(message, separators=(",", ":")) + "\n")
    sys.stdout.flush()


def rpc_result(request_id, result):
    return {"jsonrpc": "2.0", "id": request_id, "result": result}


def rpc_error(request_id, code, message, details=None):
    error = {"code": code, "message": message}
    if details is not None:
        error["data"] = {"details": details}
    return {"jsonrpc": "2.0", "id": request_id, "error": error}


def tool_result(value, is_error=False):
    return {
        "content": [{"type": "text", "text": json.dumps(value, indent=2)}],
        "structuredContent": value,
        "isError": is_error,
    }


def path_parts(full_path):
    normalized = normalize_node_path(full_path)
    if normalized == "/":
        raise RuntimeError("path must point to a node")
    folder, name = normalized.rsplit("/", 1)
    return {"folder_path": folder or "/", "name": name}


def normalize_node_path(value):
    return "/" + str(value or "").strip().strip("/")


def is_agent_namespace_path(value):
    normalized = normalize_node_path(value)
    return normalized == AGENT_NAMESPACE or normalized.startswith(f"{AGENT_NAMESPACE}/")


def reject_agent_namespace_path(value, label="path"):
    if is_agent_namespace_path(value):
        raise RuntimeError(
            f"{label} is inside {AGENT_NAMESPACE}; use the explicit nap_agent_* tools with agent_slug"
        )


def filter_project_nodes(nodes):
    return [node for node in (nodes or []) if not is_agent_namespace_path(node.get("full_path") or "")]


def agent_slug_from_args(args):
    slug = str(args.get("agent_slug") or "").strip().strip("/")
    if not slug:
        raise RuntimeError("agent_slug is required")
    if "/" in slug or slug in {".", ".."} or slug.startswith("."):
        raise RuntimeError("agent_slug must be a single path segment")
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    if any(ch not in allowed for ch in slug):
        raise RuntimeError("agent_slug may contain only letters, numbers, '.', '_', and '-'")
    return slug


def agent_root_path(agent_slug):
    return f"{AGENT_NAMESPACE}/{agent_slug}"


def agent_scoped_path(args, key="path"):
    slug = agent_slug_from_args(args)
    root = agent_root_path(slug)
    raw_path = str(args.get(key) or "").strip()
    if not raw_path:
        raise RuntimeError(f"{key} is required")
    normalized = normalize_node_path(raw_path)
    if normalized == root:
        raise RuntimeError(f"{key} must point to a node inside {root}")
    if normalized.startswith(f"{root}/"):
        return normalized
    if normalized == AGENT_NAMESPACE or normalized.startswith(f"{AGENT_NAMESPACE}/"):
        raise RuntimeError(f"{key} must stay inside {root}")
    return f"{root}/{normalized.strip('/')}"


def agent_scoped_folder(args):
    slug = agent_slug_from_args(args)
    root = agent_root_path(slug)
    raw_folder = str(args.get("folder_path") or "").strip()
    if not raw_folder:
        return root
    normalized = normalize_node_path(raw_folder)
    if normalized == root or normalized.startswith(f"{root}/"):
        return normalized
    if normalized == AGENT_NAMESPACE or normalized.startswith(f"{AGENT_NAMESPACE}/"):
        raise RuntimeError(f"folder_path must stay inside {root}")
    return f"{root}/{normalized.strip('/')}"


def request_json(method, path, payload=None, token_required=True, retry_auth=True, extra_headers=None):
    if token_required and not TOKEN:
        raise RuntimeError("NAPSEER_TOKEN is required")
    body = None if payload is None else json.dumps(payload).encode("utf-8")
    headers = {"Content-Type": "application/json", "User-Agent": "napseer-mcp-python/0.1"}
    if token_required:
        headers["Authorization"] = f"Bearer {TOKEN}"
    if extra_headers:
        headers.update(extra_headers)
    request = urllib.request.Request(f"{BASE_URL}{path}", data=body, headers=headers, method=method)
    try:
        with api_urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:
            text = response.read().decode("utf-8")
            return json.loads(text) if text else {}
    except (TimeoutError, socket.timeout) as exc:
        raise RuntimeError(f"{method} {path} timed out after {HTTP_TIMEOUT_SECONDS}s") from exc
    except urllib.error.HTTPError as exc:
        body_text = exc.read().decode("utf-8")
        if exc.code == 401 and token_required and retry_auth:
            renew_auth()
            return request_json(method, path, payload, token_required=True, retry_auth=False, extra_headers=extra_headers)
        raise RuntimeError(f"{method} {path} failed: HTTP {exc.code}: {body_text}") from exc


def request_form_json(method, path, payload, token_required=False, extra_headers=None):
    if token_required and not TOKEN:
        raise RuntimeError("NAPSEER_TOKEN is required")
    body = urllib.parse.urlencode(payload).encode("utf-8")
    headers = {"Content-Type": "application/x-www-form-urlencoded", "User-Agent": "napseer-mcp-python/0.1"}
    if token_required:
        headers["Authorization"] = f"Bearer {TOKEN}"
    if extra_headers:
        headers.update(extra_headers)
    request = urllib.request.Request(f"{BASE_URL}{path}", data=body, headers=headers, method=method)
    try:
        with api_urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:
            text = response.read().decode("utf-8")
            return json.loads(text) if text else {}
    except (TimeoutError, socket.timeout) as exc:
        raise RuntimeError(f"{method} {path} timed out after {HTTP_TIMEOUT_SECONDS}s") from exc
    except urllib.error.HTTPError as exc:
        body_text = exc.read().decode("utf-8")
        raise RuntimeError(f"{method} {path} failed: HTTP {exc.code}: {body_text}") from exc


def lock_headers(lock):
    return {
        "X-Napseer-Lock-Id": lock["id"],
        "X-Napseer-Lock-Token": lock["lease_token"],
    }


def acquire_project_lock(args=None):
    args = args or {}
    project_id = resolve_project_id(args)
    payload = {
        "scope_type": args.get("scope_type", "project"),
        "scope_key": args.get("scope_key", "*"),
        "purpose": args.get("purpose", "mcp write"),
        "holder_label": args.get("holder_label") or AUTH.get("worker_name") or "local MCP",
        "ttl_seconds": int(args.get("ttl_seconds", 600)),
    }
    return request_json("POST", f"/v1/projects/{project_id}/locks", payload)


def renew_project_lock(args):
    project_id = resolve_project_id(args)
    lock_id = args.get("lock_id")
    lease_token = args.get("lease_token")
    if not lock_id or not lease_token:
        raise RuntimeError("lock_id and lease_token are required")
    return request_json(
        "POST",
        f"/v1/projects/{project_id}/locks/{lock_id}",
        {"lease_token": lease_token, "ttl_seconds": int(args.get("ttl_seconds", 600))},
        extra_headers={"X-Napseer-Lock-Token": lease_token},
    )


def release_project_lock(args):
    project_id = resolve_project_id(args)
    lock_id = args.get("lock_id")
    lease_token = args.get("lease_token")
    if not lock_id or not lease_token:
        raise RuntimeError("lock_id and lease_token are required")
    return request_json(
        "DELETE",
        f"/v1/projects/{project_id}/locks/{lock_id}",
        payload=None,
        extra_headers={"X-Napseer-Lock-Token": lease_token},
    )


def list_project_locks(args):
    project_id = resolve_project_id(args)
    return request_json("GET", f"/v1/projects/{project_id}/locks")


def with_project_lock(args, operation):
    lock = acquire_project_lock(args)
    try:
        return operation(lock_headers(lock))
    finally:
        try:
            release_project_lock({"lock_id": lock["id"], "lease_token": lock["lease_token"], "project_id": args.get("project_id")})
        except Exception:
            pass


def request_project_write(method, path, payload, project_id, purpose, scope_type="project", scope_key="*"):
    return with_project_lock(
        {"project_id": project_id, "scope_type": scope_type, "scope_key": scope_key, "purpose": purpose},
        lambda headers: request_json(method, path, payload, extra_headers=headers),
    )


def index_file_lock():
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    handle = INDEX_LOCK_PATH.open("a+b")
    chmod_best_effort(INDEX_LOCK_PATH, 0o600)
    if fcntl is not None:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
    return handle


def release_index_file_lock(handle):
    try:
        if fcntl is not None:
            fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    finally:
        handle.close()


def index_connect():
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    conn = sqlite3.connect(str(INDEX_PATH), timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout = 5000")
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS local_index_nodes (
            node_id TEXT PRIMARY KEY,
            project_id TEXT NOT NULL,
            full_path TEXT NOT NULL,
            name TEXT NOT NULL,
            folder_path TEXT,
            node_type TEXT NOT NULL,
            tags_json TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            indexed_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE VIRTUAL TABLE IF NOT EXISTS local_index_fts USING fts5(
            node_id UNINDEXED,
            project_id UNINDEXED,
            full_path,
            name,
            folder_path,
            node_type,
            tags,
            aliases,
            links,
            metadata_text,
            content_text
        )
        """
    )
    chmod_best_effort(INDEX_PATH, 0o600)
    return conn


def flatten_index_values(value):
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, (int, float, bool)):
        return [str(value)]
    if isinstance(value, list):
        items = []
        for item in value:
            items.extend(flatten_index_values(item))
        return items
    if isinstance(value, dict):
        items = []
        for key, item in value.items():
            items.append(str(key))
            items.extend(flatten_index_values(item))
        return items
    return [str(value)]


def compact_json_text(value):
    return json.dumps(value or [], ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def index_node(node):
    if not node or not node.get("id"):
        return
    lock = index_file_lock()
    try:
        with index_connect() as conn:
            tags = node.get("tags") or []
            aliases = node.get("aliases") or []
            links = node.get("links") or []
            metadata = node.get("metadata") or {}
            conn.execute(
                """
                INSERT INTO local_index_nodes (
                    node_id, project_id, full_path, name, folder_path, node_type,
                    tags_json, updated_at, indexed_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(node_id) DO UPDATE SET
                    project_id = excluded.project_id,
                    full_path = excluded.full_path,
                    name = excluded.name,
                    folder_path = excluded.folder_path,
                    node_type = excluded.node_type,
                    tags_json = excluded.tags_json,
                    updated_at = excluded.updated_at,
                    indexed_at = excluded.indexed_at
                """,
                (
                    node["id"],
                    node.get("project_id") or DEFAULT_PROJECT_ID or "",
                    node.get("full_path") or "",
                    node.get("name") or "",
                    node.get("folder_path"),
                    node.get("type") or "note",
                    compact_json_text(tags),
                    node.get("updated_at") or "",
                    iso_now(),
                ),
            )
            conn.execute("DELETE FROM local_index_fts WHERE node_id = ?", (node["id"],))
            conn.execute(
                """
                INSERT INTO local_index_fts (
                    node_id, project_id, full_path, name, folder_path, node_type,
                    tags, aliases, links, metadata_text, content_text
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    node["id"],
                    node.get("project_id") or DEFAULT_PROJECT_ID or "",
                    node.get("full_path") or "",
                    node.get("name") or "",
                    node.get("folder_path") or "",
                    node.get("type") or "note",
                    " ".join(tags),
                    " ".join(aliases),
                    " ".join(flatten_index_values(links)),
                    " ".join(flatten_index_values(metadata)),
                    node.get("content_text") or "",
                ),
            )
    finally:
        release_index_file_lock(lock)


def remove_indexed_node(node_id):
    lock = index_file_lock()
    try:
        with index_connect() as conn:
            conn.execute("DELETE FROM local_index_fts WHERE node_id = ?", (node_id,))
            conn.execute("DELETE FROM local_index_nodes WHERE node_id = ?", (node_id,))
    finally:
        release_index_file_lock(lock)


