def unique_preserve_order(values):
    seen = set()
    items = []
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        items.append(value)
    return items


def search_tokens(value):
    raw_tokens = re.findall(r"[A-Za-z0-9][A-Za-z0-9_.:/-]*", value.lower())
    tokens = []
    for token in raw_tokens:
        cleaned = token.strip("._:/-")
        if len(cleaned) < 3 or cleaned in SEARCH_STOP_WORDS:
            continue
        tokens.append(cleaned)
        if cleaned.endswith("s") and len(cleaned) > 3:
            singular = cleaned[:-1]
            if singular not in SEARCH_STOP_WORDS:
                tokens.append(singular)
    return unique_preserve_order(tokens)


def quote_fts(value):
    return f'"{str(value).replace(chr(34), chr(34) + chr(34))}"'


def fts_prefix_term(value):
    term = re.sub(r"[^a-z0-9_]", "", str(value).lower())
    if not term:
        return ""
    return f"{term}*"


def analyze_search_query(value):
    raw = str(value or "").strip()
    if not raw:
        raise RuntimeError("q is required")
    phrases = [item.strip() for item in re.findall(r'"([^"]+)"', raw) if item.strip()]
    terms = search_tokens(raw)
    simplified_terms = terms[:8]
    return {
        "raw": raw,
        "is_long_query": len(raw.split()) > 6,
        "phrases": unique_preserve_order(phrases)[:5],
        "terms": terms[:20],
        "simplified_query": " ".join(simplified_terms) if simplified_terms else raw,
    }


def fts_query(value):
    analysis = analyze_search_query(value)
    terms = analysis["terms"]
    if terms:
        return " ".join(quote_fts(term) for term in terms[:6])
    return quote_fts(analysis["raw"])


def fts_query_variants(value):
    analysis = analyze_search_query(value)
    variants = []
    for phrase in analysis["phrases"]:
        variants.append({"strategy": "quoted_phrase", "query": quote_fts(phrase)})
    terms = analysis["terms"]
    if terms:
        prefix_terms = [fts_prefix_term(term) for term in terms[:12]]
        prefix_terms = [term for term in prefix_terms if term]
        if prefix_terms:
            variants.append({"strategy": "important_terms_prefix_any", "query": " OR ".join(prefix_terms)})
        variants.append({"strategy": "important_terms_any", "query": " OR ".join(quote_fts(term) for term in terms[:12])})
        variants.append({"strategy": "important_terms_all", "query": " ".join(quote_fts(term) for term in terms[:6])})
        if len(terms) > 2:
            variants.append({"strategy": "top_terms_all", "query": " ".join(quote_fts(term) for term in terms[:3])})
    variants.append({"strategy": "raw_phrase", "query": quote_fts(analysis["raw"])})
    deduped = []
    seen = set()
    for variant in variants:
        query = variant["query"]
        if query in seen:
            continue
        seen.add(query)
        deduped.append(variant)
    return analysis, deduped


def local_index_diagnostics(project_id, conn=None):
    diagnostics = {"project_id": project_id, "exists": INDEX_PATH.exists(), "index_path": str(INDEX_PATH)}
    if not INDEX_PATH.exists():
        diagnostics.update({"count": 0, "used": False, "reindex_recommended": True})
        return diagnostics

    def read(connection):
        count = connection.execute("SELECT COUNT(*) AS count FROM local_index_nodes WHERE project_id = ?", (project_id,)).fetchone()["count"]
        latest = connection.execute("SELECT MAX(indexed_at) AS latest FROM local_index_nodes WHERE project_id = ?", (project_id,)).fetchone()["latest"]
        diagnostics.update(
            {
                "count": count,
                "latest_indexed_at": latest,
                "used": False,
                "reindex_recommended": count == 0,
            }
        )
        return diagnostics

    if conn is not None:
        return read(conn)
    lock = index_file_lock()
    try:
        with index_connect() as connection:
            return read(connection)
    finally:
        release_index_file_lock(lock)


def search_local_index(args):
    project_id = resolve_project_id(args)
    query_analysis, variants = fts_query_variants(args.get("q"))
    limit = max(1, min(int(args.get("limit", 25)), 100))
    attempts = []
    seen = set()
    items = []
    lock = index_file_lock()
    try:
        with index_connect() as conn:
            diagnostics = local_index_diagnostics(project_id, conn)
            for variant in variants:
                if len(items) >= limit:
                    break
                try:
                    rows = conn.execute(
                        """
                        SELECT n.node_id, n.project_id, n.full_path, n.name, n.folder_path, n.node_type,
                               n.tags_json, n.updated_at, n.indexed_at,
                               bm25(local_index_fts) AS rank
                        FROM local_index_fts
                        JOIN local_index_nodes n ON n.node_id = local_index_fts.node_id
                        WHERE local_index_fts MATCH ? AND n.project_id = ?
                        ORDER BY rank ASC, n.updated_at DESC
                        LIMIT ?
                        """,
                        (variant["query"], project_id, limit),
                    ).fetchall()
                except sqlite3.Error as exc:
                    attempts.append({"strategy": variant["strategy"], "matched": 0, "error": str(exc)})
                    continue
                matched = 0
                for row in rows:
                    key = row["node_id"]
                    if key in seen:
                        continue
                    seen.add(key)
                    matched += 1
                    items.append(
                        {
                            "id": row["node_id"],
                            "project_id": row["project_id"],
                            "full_path": row["full_path"],
                            "name": row["name"],
                            "folder_path": row["folder_path"],
                            "type": row["node_type"],
                            "tags": json.loads(row["tags_json"] or "[]"),
                            "updated_at": row["updated_at"],
                            "indexed_at": row["indexed_at"],
                            "rank": row["rank"],
                            "matched_strategy": variant["strategy"],
                        }
                    )
                attempts.append({"strategy": variant["strategy"], "matched": matched})
            diagnostics["used"] = True
            diagnostics["returned"] = len(items[:limit])
            return {
                "items": items[:limit],
                "query": query_analysis,
                "search_strategies": attempts,
                "index": diagnostics,
            }
    finally:
        release_index_file_lock(lock)


def reindex_project(args):
    project_id = resolve_project_id(args)
    limit = max(1, min(int(args.get("limit", 200)), 200))
    nodes = []
    cursor = None
    while True:
        query = {"limit": limit}
        if cursor:
            query["cursor"] = cursor
        page = request_json("GET", f"/v1/projects/{project_id}/nodes?{urllib.parse.urlencode(query)}")
        nodes.extend(filter_project_nodes(page.get("items", [])))
        cursor = page.get("next_cursor")
        if not cursor:
            break
    lock = index_file_lock()
    try:
        with index_connect() as conn:
            conn.execute("DELETE FROM local_index_fts WHERE project_id = ?", (project_id,))
            conn.execute("DELETE FROM local_index_nodes WHERE project_id = ?", (project_id,))
    finally:
        release_index_file_lock(lock)
    for node in nodes:
        index_node(node)
    return {"project_id": project_id, "indexed": len(nodes), "index_path": str(INDEX_PATH)}


def index_status(args):
    project_id = resolve_project_id(args)
    return local_index_diagnostics(project_id)


def clear_local_index(args):
    project_id = resolve_project_id(args)
    lock = index_file_lock()
    try:
        with index_connect() as conn:
            conn.execute("DELETE FROM local_index_fts WHERE project_id = ?", (project_id,))
            conn.execute("DELETE FROM local_index_nodes WHERE project_id = ?", (project_id,))
    finally:
        release_index_file_lock(lock)
    return {"project_id": project_id, "cleared": True}


def public_json(path):
    request = urllib.request.Request(
        f"{BASE_URL}{path}",
        headers={"Content-Type": "application/json", "User-Agent": "napseer-mcp-python/0.1"},
    )
    try:
        with api_urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:
            return json.loads(response.read().decode("utf-8"))
    except (TimeoutError, socket.timeout) as exc:
        raise RuntimeError(f"GET {path} timed out after {HTTP_TIMEOUT_SECONDS}s") from exc


def fetch_remote_script(script_name=SCRIPT_NAME):
    if SCRIPT_NAME != "napseer_mcp_server.py":
        raise RuntimeError(f"unsupported wrapper filename for self-update: {SCRIPT_NAME}")
    remote = public_json(f"/v1/scripts/{script_name}")
    content = remote.get("content")
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("remote script response did not include content")
    return remote


def sha256_bytes(content):
    return hashlib.sha256(content).hexdigest()


def is_sha256_hex(value):
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(ch in "0123456789abcdefABCDEF" for ch in value)
    )


def validate_remote_script(remote):
    content = remote.get("content")
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("remote script response did not include content")
    content_bytes = content.encode("utf-8")
    content_sha256 = sha256_bytes(content_bytes)
    declared_sha256 = remote.get("sha256")
    if not is_sha256_hex(declared_sha256):
        raise RuntimeError("remote script response did not include a valid sha256")
    declared_sha256 = declared_sha256.lower()

    errors = []
    if declared_sha256 != content_sha256:
        errors.append("content sha256 does not match declared sha256")

    declared_bytes = remote.get("bytes")
    if declared_bytes is not None:
        if isinstance(declared_bytes, bool) or not isinstance(declared_bytes, int):
            errors.append("declared byte count is not an integer")
        elif declared_bytes != len(content_bytes):
            errors.append("content byte count does not match declared byte count")

    if errors:
        raise RuntimeError(f"remote script integrity mismatch: {', '.join(errors)}")

    return {
        "content": content,
        "content_bytes": content_bytes,
        "content_bytes_len": len(content_bytes),
        "content_sha256": content_sha256,
        "declared_sha256": declared_sha256,
        "declared_bytes": declared_bytes,
    }


def update_status(remote=None):
    if remote is None:
        remote = fetch_remote_script(SCRIPT_NAME)
    integrity = validate_remote_script(remote)
    local_content = SCRIPT_PATH.read_bytes()
    local_sha256 = sha256_bytes(local_content)
    up_to_date = local_sha256 == integrity["declared_sha256"]
    return {
        "script_path": str(SCRIPT_PATH),
        "script_name": SCRIPT_NAME,
        "remote_url": f"{BASE_URL}/v1/scripts/{SCRIPT_NAME}",
        "remote_version": remote.get("version"),
        "remote_build_commit": remote.get("build_commit"),
        "remote_published_at": remote.get("published_at"),
        "remote_changelog_url": remote.get("changelog_url"),
        "up_to_date": up_to_date,
        "update_required": not up_to_date,
        "verification": "sha256",
        "remote_integrity_ok": True,
        "local_bytes": len(local_content),
        "remote_bytes": integrity["content_bytes_len"],
        "local_sha256": local_sha256,
        "remote_sha256": integrity["declared_sha256"],
        "remote_declared_sha256": integrity["declared_sha256"],
        "remote_content_sha256": integrity["content_sha256"],
        "remote_declared_bytes": integrity["declared_bytes"],
}


def update_script_dependencies():
    results = []
    for name in SCRIPT_DEPENDENCY_NAMES:
        remote = fetch_remote_script(name)
        integrity = validate_remote_script(remote)
        target = SCRIPT_PATH.with_name(name)
        local_bytes = target.read_bytes() if target.exists() else b""
        local_sha256 = sha256_bytes(local_bytes)
        updated = local_sha256 != integrity["declared_sha256"]
        if updated:
            temp_path = target.with_name(f".{target.name}.tmp")
            try:
                temp_path.unlink()
            except FileNotFoundError:
                pass
            temp_path.write_bytes(integrity["content_bytes"])
            if sha256_bytes(temp_path.read_bytes()) != integrity["declared_sha256"]:
                raise RuntimeError(f"downloaded {name} failed temp-file sha256 verification")
            temp_path.replace(target)
            try:
                target.chmod(0o755)
            except OSError:
                pass
        results.append({
            "name": name,
            "path": str(target),
            "updated": updated,
            "local_sha256": sha256_bytes(target.read_bytes()) if target.exists() else "",
            "remote_sha256": integrity["declared_sha256"],
        })
    return results


def update_self(args):
    if args.get("confirm") != "update":
        raise RuntimeError("nap_update_self requires confirm='update'")
    remote = fetch_remote_script(SCRIPT_NAME)
    status = update_status(remote)
    dependency_results = update_script_dependencies()
    if status["up_to_date"]:
        return {**status, "updated": any(item["updated"] for item in dependency_results), "dependencies": dependency_results}
    integrity = validate_remote_script(remote)
    backup_path = SCRIPT_PATH.with_suffix(SCRIPT_PATH.suffix + ".bak")
    temp_path = SCRIPT_PATH.with_name(f".{SCRIPT_PATH.name}.tmp")
    original_mode = SCRIPT_PATH.stat().st_mode
    backup_path.write_bytes(SCRIPT_PATH.read_bytes())
    try:
        try:
            temp_path.unlink()
        except FileNotFoundError:
            pass
        temp_path.write_bytes(integrity["content_bytes"])
        temp_sha256 = sha256_bytes(temp_path.read_bytes())
        if temp_sha256 != integrity["declared_sha256"]:
            raise RuntimeError("downloaded script failed temp-file sha256 verification")
        temp_path.replace(SCRIPT_PATH)
    except Exception:
        try:
            temp_path.unlink()
        except OSError:
            pass
        raise
    try:
        SCRIPT_PATH.chmod(original_mode | 0o700)
    except OSError:
        pass
    final_sha256 = sha256_bytes(SCRIPT_PATH.read_bytes())
    if final_sha256 != integrity["declared_sha256"]:
        SCRIPT_PATH.write_bytes(backup_path.read_bytes())
        raise RuntimeError("updated script failed final sha256 verification; restored backup")
    final_status = update_status(remote)
    return {
        **final_status,
        "updated": True,
        "dependencies": dependency_results,
        "backup_path": str(backup_path),
        "previous_local_sha256": status["local_sha256"],
    }


def sign_text(namespace, key_path, text):
    with tempfile.TemporaryDirectory() as tmp:
        data_path = pathlib.Path(tmp) / "data.txt"
        data_path.write_text(text, encoding="utf-8")
        subprocess.run(
            ["ssh-keygen", "-Y", "sign", "-q", "-n", namespace, "-f", str(key_path), str(data_path)],
            check=True,
            stdout=subprocess.DEVNULL,
        )
        return pathlib.Path(str(data_path) + ".sig").read_text(encoding="utf-8")


def auth_public_key():
    ensure_local_files()
    if AUTH.get("ssh_public_key"):
        return AUTH["ssh_public_key"].strip()
    key_path = pathlib.Path(AUTH["ssh_key_path"]).expanduser()
    public_key_path = pathlib.Path(str(key_path) + ".pub")
    if not public_key_path.exists():
        raise RuntimeError(f"missing public key at {public_key_path}")
    return public_key_path.read_text(encoding="utf-8").strip()


def sign_with_auth_key(namespace, text):
    if AUTH.get("ssh_private_key"):
        with tempfile.TemporaryDirectory() as tmp:
            key_path = pathlib.Path(tmp) / "id_ed25519"
            key_path.write_text(AUTH["ssh_private_key"], encoding="utf-8")
            chmod_best_effort(key_path, 0o600)
            public_key = AUTH.get("ssh_public_key")
            if public_key:
                pathlib.Path(str(key_path) + ".pub").write_text(public_key.strip() + "\n", encoding="utf-8")
            return sign_text(namespace, key_path, text)
    return sign_text(namespace, pathlib.Path(AUTH["ssh_key_path"]).expanduser(), text)


def renew_auth():
    public_key = auth_public_key()
    challenge = request_json(
        "POST",
        "/v1/enrollment/challenges",
        {
            "public_key": public_key,
            "worker_name": AUTH["worker_name"],
            "device_fingerprint": AUTH["device_fingerprint"],
            "root_path": AUTH["root_path"],
            "worker_capabilities": AUTH["worker_capabilities"],
        },
        token_required=False,
    )
    signature = sign_with_auth_key("napseer", challenge["challenge_text"])
    verified = request_json(
        "POST",
        "/v1/enrollment/verify",
        {"challenge_id": challenge["challenge_id"], "signature": signature},
        token_required=False,
    )
    save_auth(
        {
            "base_url": BASE_URL,
            "token": verified["token"]["access_token"],
            "token_expires_at": verified["token"].get("expires_at"),
            "worker_id": verified["worker"]["id"],
            "agent_id": verified["worker"]["agent_id"],
            "worker_name": verified["worker"]["name"],
            "device_fingerprint": verified["worker"]["device_fingerprint"],
            "root_path": verified["worker"]["root_path"],
        }
    )
    return {
        "status": "renewed",
        "token_expires_at": verified["token"].get("expires_at"),
        "worker_id": verified["worker"]["id"],
        "agent_id": verified["worker"]["agent_id"],
    }


def jwt_claims(token):
    try:
        parts = str(token or "").split(".")
        if len(parts) < 2:
            return {}
        payload = parts[1]
        payload += "=" * (-len(payload) % 4)
        return json.loads(base64.urlsafe_b64decode(payload.encode("ascii")).decode("utf-8"))
    except Exception:
        return {}


def token_expires_at_from_claims(claims):
    exp = claims.get("exp")
    if not exp:
        return None
    try:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(int(exp)))
    except Exception:
        return None


def oauth_code_challenge(verifier):
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return base64.urlsafe_b64encode(digest).decode("ascii").rstrip("=")


def oauth_loopback_authorize(args):
    args = args or {}
    frontend_url = str(
        args.get("frontend_url")
        or os.environ.get("NAPSEER_FRONTEND_URL")
        or os.environ.get("NAPSEER_PUBLIC_URL")
        or "https://napseer.com"
    ).rstrip("/")
    api_base_url = str(
        args.get("base_url")
        or args.get("api_base_url")
        or os.environ.get("NAPSEER_BASE_URL")
        or BASE_URL
        or "https://api.napseer.com"
    ).rstrip("/")
    state = secrets.token_urlsafe(32)
    verifier = secrets.token_urlsafe(64)
    result_queue = queue.Queue(maxsize=1)

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, fmt, *handler_args):
            return

        def do_GET(self):
            parsed = urllib.parse.urlparse(self.path)
            if parsed.path != "/oauth/callback":
                self.send_response(404)
                self.end_headers()
                return
            values = urllib.parse.parse_qs(parsed.query)
            if values.get("state", [""])[0] != state:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"Invalid OAuth state.")
                return
            code = values.get("code", [""])[0]
            if not code:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"Missing OAuth authorization code.")
                return
            result_queue.put({"code": code})
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(b"<html><body><h1>Napseer authorization complete</h1><p>You can close this tab.</p></body></html>")

    server = ReusableThreadingHTTPServer(("127.0.0.1", int(args.get("port", 0))), Handler)
    redirect_uri = f"http://127.0.0.1:{server.server_address[1]}/oauth/callback"
    authorization_payload = {
        "client_id": args.get("client_id") or "nap-cli",
        "redirect_uri": redirect_uri,
        "state": state,
        "code_challenge": oauth_code_challenge(verifier),
        "code_challenge_method": "S256",
        "scope": args["scope"],
        "flow": args["flow"],
    }
    if args.get("claim_token"):
        authorization_payload["claim_token"] = args["claim_token"]
    authorization = request_json(
        "POST",
        "/v1/oauth/native/authorizations",
        authorization_payload,
        token_required=False,
    )
    authorize_url = authorization.get("authorization_url")
    if not authorize_url:
        raise RuntimeError("OAuth authorization endpoint did not return authorization_url")

    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    print(f"Open this Napseer authorization URL if the browser does not open: {authorize_url}", file=sys.stderr)
    if args.get("open_browser", True):
        webbrowser.open(authorize_url)

    try:
        result = result_queue.get(timeout=int(args.get("timeout_seconds", 300)))
    except queue.Empty as exc:
        raise RuntimeError("timed out waiting for OAuth loopback callback") from exc
    finally:
        server.shutdown()
        server.server_close()

    token = request_form_json(
        "POST",
        "/v1/oauth/token",
        {
            "grant_type": "authorization_code",
            "client_id": authorization_payload["client_id"],
            "code": result["code"],
            "redirect_uri": redirect_uri,
            "code_verifier": verifier,
        },
        token_required=False,
    )
    token["api_base_url"] = api_base_url
    token["authorization"] = authorization
    return token


def operator_loopback_login(args=None):
    args = args or {}
    result = oauth_loopback_authorize({
        **args,
        "flow": "local_operator_access",
        "scope": "openid profile email napseer.feedback.read",
    })
    operator_auth = {
        "base_url": result["api_base_url"],
        "token": result["access_token"],
        "token_expires_at": iso_timestamp_after_seconds(int(result.get("expires_in") or 0)),
        "account_mode": "operator",
        "oauth_client_id": "nap-cli",
        "oauth_scope": result.get("scope"),
    }
    save_auth_file_credentials(operator_auth)
    return {
        "status": "authenticated",
        "auth_path": str(AUTH_PATH),
        "base_url": result["api_base_url"],
        "scope": result.get("scope"),
        "token_expires_at": operator_auth["token_expires_at"],
        "message": "OAuth2 PKCE loopback token stored in the repo-local Napseer auth state.",
    }


def save_auth_file_credentials(updates):
    global AUTH, BASE_URL, TOKEN, DEFAULT_PROJECT_ID, TOKEN_EXPIRES_AT
    current_public = load_public_auth_file()
    current_public.update({key: value for key, value in updates.items() if value is not None})
    write_public_auth(current_public)
    AUTH = load_auth()
    BASE_URL = AUTH["base_url"].rstrip("/")
    TOKEN = AUTH["token"]
    DEFAULT_PROJECT_ID = AUTH["project_id"]
    TOKEN_EXPIRES_AT = AUTH["token_expires_at"]


def save_auth(updates):
    global AUTH, BASE_URL, TOKEN, DEFAULT_PROJECT_ID, TOKEN_EXPIRES_AT, VAULT_SECRETS
    current_public = load_public_auth_file()
    cleaned = {key: value for key, value in updates.items() if value is not None}
    if vault_exists():
        public_updates = {key: value for key, value in cleaned.items() if key in AUTH_FILE_KEYS}
        vault_updates = {key: value for key, value in cleaned.items() if key in GATEWAY_VAULT_KEYS}
        current_public.update(public_updates)
        write_public_auth(current_public)
        if vault_updates:
            require_unlocked("updating gateway vault")
            VAULT_SECRETS.update(vault_updates)
            write_vault_with_key(VAULT_KEY, {"version": 1, "updated_at": iso_now(), "secrets": VAULT_SECRETS})
        AUTH = load_auth(public_override=current_public, secret_override=VAULT_SECRETS if gateway_is_unlocked() else {})
    else:
        current_public.update(cleaned)
        AUTH_PATH.parent.mkdir(exist_ok=True)
        chmod_best_effort(AUTH_PATH.parent, 0o700)
        AUTH_PATH.write_text(json.dumps(current_public, indent=2) + "\n", encoding="utf-8")
        chmod_best_effort(AUTH_PATH, 0o600)
        AUTH = load_auth()
    BASE_URL = AUTH["base_url"].rstrip("/")
    TOKEN = AUTH["token"]
    DEFAULT_PROJECT_ID = AUTH["project_id"]
    TOKEN_EXPIRES_AT = AUTH["token_expires_at"]


def ensure_local_files():
    AUTH_DIR.mkdir(exist_ok=True)
    chmod_best_effort(AUTH_DIR, 0o700)
    gitignore = AUTH_DIR / ".gitignore"
    if not gitignore.exists():
        gitignore.write_text("*\n!.gitignore\n", encoding="utf-8")
    key_path = pathlib.Path(AUTH["ssh_key_path"] or DEFAULT_KEY_PATH).expanduser()
    public_key_path = pathlib.Path(str(key_path) + ".pub")
    if not key_path.exists():
        key_path.parent.mkdir(exist_ok=True)
        chmod_best_effort(key_path.parent, 0o700)
        subprocess.run(
            ["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", str(key_path)],
            check=True,
        )
    chmod_best_effort(key_path, 0o600)
    if public_key_path.exists():
        chmod_best_effort(public_key_path, 0o644)
    return key_path


def ensure_enrolled(args=None):
    if TOKEN:
        return {"status": "already_enrolled", "token_expires_at": TOKEN_EXPIRES_AT}
    args = args or {}
    key_path = ensure_local_files()
    public_key = pathlib.Path(str(key_path) + ".pub").read_text(encoding="utf-8").strip()
    slug = str(args.get("slug") or pathlib.Path.cwd().name or "napseer-project")
    worker_name = str(args.get("worker_name") or AUTH.get("worker_name") or f"{slug}-agent")
    device_fingerprint = str(args.get("device_fingerprint") or AUTH.get("device_fingerprint") or socket.gethostname())
    root_path = str(args.get("root_path") or AUTH.get("root_path") or pathlib.Path.cwd())
    worker_capabilities = AUTH.get("worker_capabilities") or {"local_mcp": True, "mcp_wrapper": SCRIPT_NAME}
    challenge = request_json(
        "POST",
        "/v1/enrollment/challenges",
        {
            "public_key": public_key,
            "worker_name": worker_name,
            "device_fingerprint": device_fingerprint,
            "root_path": root_path,
            "worker_capabilities": worker_capabilities,
        },
        token_required=False,
    )
    signature = sign_text("napseer", key_path, challenge["challenge_text"])
    verified = request_json(
        "POST",
        "/v1/enrollment/verify",
        {"challenge_id": challenge["challenge_id"], "signature": signature},
        token_required=False,
    )
    save_auth(
        {
            "base_url": BASE_URL,
            "token": verified["token"]["access_token"],
            "token_expires_at": verified["token"].get("expires_at"),
            "worker_id": verified["worker"]["id"],
            "agent_id": verified["worker"]["agent_id"],
            "worker_name": worker_name,
            "device_fingerprint": device_fingerprint,
            "root_path": root_path,
            "ssh_key_path": str(key_path),
            "ssh_public_key": public_key,
            "worker_capabilities": worker_capabilities,
            "account_mode": AUTH.get("account_mode") or "anonymous",
        }
    )
    return {"status": "enrolled", "token_expires_at": verified["token"].get("expires_at")}


def gateway_service_preregister(args=None):
    args = args or {}
    bootstrap_token = (
        args.get("bootstrap_token")
        or os.environ.get("NAPSEER_SERVICE_BOOTSTRAP_TOKEN")
        or os.environ.get("NAPSEER_GATEWAY_BOOTSTRAP_TOKEN")
    )
    if not bootstrap_token:
        raise RuntimeError("service bootstrap token is required")
    passphrase = (
        args.get("passphrase")
        or os.environ.get("NAPSEER_GATEWAY_PASSPHRASE")
        or os.environ.get("NAPSEER_GATEWAY_PASSKEY")
    )
    if not vault_exists():
        if not passphrase:
            raise RuntimeError("gateway passphrase is required to create the gateway vault")
        gateway_setup({
            "passphrase": passphrase,
            "default_command": args.get("default_command") or os.environ.get("NAPSEER_GATEWAY_COMMAND"),
        })
    elif passphrase and not gateway_is_unlocked():
        gateway_unlock(passphrase)

    key_path = ensure_local_files()
    public_key = pathlib.Path(str(key_path) + ".pub").read_text(encoding="utf-8").strip()
    display_name = (
        args.get("display_name")
        or os.environ.get("NAPSEER_SERVICE_DISPLAY_NAME")
        or os.environ.get("NAPSEER_GATEWAY_NAME")
        or AUTH.get("worker_name")
        or f"{pathlib.Path.cwd().name}-gateway"
    )
    root_path = args.get("root_path") or os.environ.get("NAPSEER_SERVICE_ROOT_PATH") or AUTH.get("root_path") or str(pathlib.Path.cwd())
    device_fingerprint = args.get("device_fingerprint") or os.environ.get("NAPSEER_SERVICE_DEVICE_FINGERPRINT") or AUTH.get("device_fingerprint") or socket.gethostname()
    container_uuid = normalize_uuid_text(args.get("container_uuid")) or ensure_container_uuid()
    default_command = args.get("default_command") or os.environ.get("NAPSEER_GATEWAY_COMMAND") or normalize_gateway_command()
    image_ref = args.get("image_ref") or os.environ.get("NAPSEER_SERVICE_IMAGE_REF")
    result = request_json(
        "POST",
        "/v1/service-registrations",
        {
            "bootstrap_token": bootstrap_token,
            "public_key": public_key,
            "display_name": display_name,
            "device_fingerprint": device_fingerprint,
            "container_uuid": container_uuid,
            "root_path": root_path,
            "default_command": default_command,
            "image_ref": image_ref,
            "labels": {
                "source": "napseer-gateway-container",
                "hostname": socket.gethostname(),
                "container_uuid": container_uuid,
            },
            "metadata": {
                "cwd": str(pathlib.Path.cwd()),
                "base_url": BASE_URL,
                "container_uuid": container_uuid,
            },
        },
        token_required=False,
    )
    registration = result.get("registration") or result
    activation_token = result.get("activation_token")
    save_auth({
        "base_url": BASE_URL,
        "project_id": registration.get("project_id") or DEFAULT_PROJECT_ID,
        "service_registration_id": registration.get("id"),
        "service_activation_token": activation_token,
        "agent_id": registration.get("agent_id"),
        "worker_name": registration.get("display_name") or display_name,
        "device_fingerprint": registration.get("device_fingerprint") or device_fingerprint,
        "root_path": registration.get("root_path") or root_path,
        "ssh_key_path": str(key_path),
        "ssh_public_key": public_key,
        "worker_capabilities": {
            "gateway": True,
            "service_registration_id": registration.get("id"),
            "container": True,
        },
    })
    return {
        "status": "pending_review",
        "message": "Gateway service preregistered. Open the cloud UI to accept or deny it.",
        "registration": registration,
    }


def gateway_service_activate(args=None):
    args = args or {}
    registration_id = args.get("registration_id") or AUTH.get("service_registration_id") or load_public_auth_file().get("service_registration_id")
    activation_token = (
        args.get("activation_token")
        or os.environ.get("NAPSEER_SERVICE_ACTIVATION_TOKEN")
        or VAULT_SECRETS.get("service_activation_token")
        or load_public_auth_file().get("service_activation_token")
    )
    if not registration_id:
        raise RuntimeError("service registration id is required")
    if not activation_token:
        raise RuntimeError("service activation token is required")
    payload = {"activation_token": activation_token}
    if args.get("token_expires_in_hours"):
        payload["token_expires_in_hours"] = int(args["token_expires_in_hours"])
    activation = request_json(
        "POST",
        f"/v1/service-registrations/{registration_id}/activate",
        payload,
        token_required=False,
    )
    token = activation.get("token") or activation
    worker = activation.get("worker") or {}
    save_auth({
        "base_url": BASE_URL,
        "token": token.get("access_token"),
        "token_expires_at": token.get("expires_at"),
        "project_id": worker.get("project_id") or DEFAULT_PROJECT_ID,
        "worker_id": worker.get("id") or AUTH.get("worker_id"),
        "agent_id": worker.get("agent_id") or AUTH.get("agent_id"),
        "worker_name": worker.get("name") or AUTH.get("worker_name"),
        "device_fingerprint": worker.get("device_fingerprint") or AUTH.get("device_fingerprint"),
        "root_path": worker.get("root_path") or AUTH.get("root_path"),
    })
    return {
        "status": "activated",
        "message": "Gateway service accepted and worker token stored locally.",
        "token_expires_at": token.get("expires_at"),
        "registration_id": registration_id,
        "agent_id": worker.get("agent_id") or AUTH.get("agent_id"),
        "project_id": worker.get("project_id") or DEFAULT_PROJECT_ID,
    }


def gateway_service_unlock_from_env():
    if not vault_exists() or gateway_is_unlocked():
        return False
    passphrase = os.environ.get("NAPSEER_GATEWAY_PASSPHRASE") or os.environ.get("NAPSEER_GATEWAY_PASSKEY")
    if not passphrase:
        return False
    gateway_unlock(passphrase)
    return True


def gateway_bootstrap_token_invalid_result():
    return {
        "status": "bootstrap_token_invalid",
        "message": "Gateway bootstrap token is invalid or expired. Create a new gateway bootstrap token and replace compose.yaml.",
    }


def gateway_service_run(args=None):
    args = args or {}
    ensure_container_uuid()
    bootstrap_token = (
        args.get("bootstrap_token")
        or os.environ.get("NAPSEER_SERVICE_BOOTSTRAP_TOKEN")
        or os.environ.get("NAPSEER_GATEWAY_BOOTSTRAP_TOKEN")
    )
    gateway_service_unlock_from_env()
    if bootstrap_token and not TOKEN:
        try:
            gateway_service_preregister(args)
        except RuntimeError as exc:
            if "service bootstrap token is invalid or expired" not in str(exc):
                raise
            result = gateway_bootstrap_token_invalid_result()
            gateway_log("service_bootstrap_token_invalid", level="error", error=str(exc))
            print(json.dumps(result, indent=2))
            return result
    deadline = time.time() + int(args.get("timeout_seconds") or os.environ.get("NAPSEER_SERVICE_ACTIVATION_TIMEOUT_SECONDS", "900"))
    activated = False
    while not TOKEN and time.time() < deadline:
        try:
            gateway_service_unlock_from_env()
            gateway_service_activate(args)
            activated = True
            break
        except RuntimeError as exc:
            if "401" not in str(exc) and "not accepted" not in str(exc) and "already activated" not in str(exc):
                raise
            gateway_log("service_activation_waiting", registration_id=AUTH.get("service_registration_id"), error=str(exc))
            time.sleep(5)
    if not TOKEN and not activated:
        raise RuntimeError("gateway service was not accepted before activation timeout")
    if not gateway_is_unlocked():
        gateway_service_unlock_from_env()
    result = start_local_ui({"open_browser": False, "port": int(args.get("port") or os.environ.get("NAPSEER_GATEWAY_PORT", "0"))})
    print(json.dumps(result, indent=2))
    try:
        threading.Event().wait()
    except KeyboardInterrupt:
        return result


def chmod_best_effort(path, mode):
    try:
        path.chmod(mode)
    except OSError:
        pass


def resolve_project_id(args):
    project_id = DEFAULT_PROJECT_ID
    if not project_id:
        raise RuntimeError("No project configured. Run nap project create or call nap_project_create first.")
    return project_id


def current_project_id():
    return DEFAULT_PROJECT_ID or ""


def create_project_with_state(args):
    ensure_enrolled(args)
    payload = {
        "slug": args["slug"],
        "name": args["name"],
        "description": args.get("description", ""),
    }
    status = "created"
    try:
        project = request_json("POST", "/v1/projects", payload)
    except RuntimeError as exc:
        if "HTTP 409" not in str(exc):
            raise
        project = find_project_by_slug(args["slug"])
        if not project:
            raise
        status = "existing"
    save_auth(
        {
            "base_url": BASE_URL,
            "token": TOKEN,
            "project_id": project["id"],
            "project_slug": project["slug"],
            "project_name": project["name"],
        }
    )
    try:
        register_project_signing_key({"label": "local-project-key"})
    except Exception:
        pass
    message = (
        f"Project '{project['slug']}' created and configured for this directory."
        if status == "created"
        else f"Project '{project['slug']}' already exists; configured this directory to use it."
    )
    return project, status, message


def create_project_from_args(args):
    project, _, _ = create_project_with_state(args)
    return project


def find_project_by_slug(slug):
    target = str(slug or "").strip().lower()
    projects = request_json("GET", "/v1/projects").get("items", [])
    for project in projects:
        if str(project.get("slug") or "").lower() == target:
            return project
    return None


def bootstrap_project(args):
    encryption = str(args.get("encryption") or "plaintext").strip().lower()
    if encryption not in {"plaintext", "encrypted"}:
        raise RuntimeError("encryption must be plaintext or encrypted")
    if encryption == "encrypted" and not str(args.get("passphrase") or "").strip():
        raise RuntimeError("project passphrase is required when encryption is enabled")
    project, project_status, message = create_project_with_state(args)
    encryption_state = "plaintext"
    if encryption == "encrypted":
        status = request_project_write(
            "POST",
            f"/v1/projects/{project['id']}/encryption/enable",
            {"state": "encrypted"},
            project["id"],
            "enable project encryption",
        )
        encryption_state = status.get("state") or "encrypted"
    return {
        "status": project_status,
        "message": message,
        "project": project,
        "project_id": project["id"],
        "encryption_state": encryption_state,
        "project_unlocked": True,
    }


def project_encryption_status(args=None):
    args = args or {}
    project_id = resolve_project_id(args)
    status = request_json("GET", f"/v1/projects/{project_id}/encryption/status")
    return {
        **status,
        "status": "ok",
        "message": f"Project encryption is {status.get('state') or 'unknown'}.",
    }


def project_encryption_transition(args=None):
    args = args or {}
    requested = str(args.get("state") or args.get("mode") or "").strip().lower()
    aliases = {
        "on": "encrypted",
        "enable": "encrypted",
        "enabled": "encrypted",
        "encrypt": "encrypted",
        "encrypted": "encrypted",
        "off": "plaintext",
        "disable": "plaintext",
        "disabled": "plaintext",
        "decrypt": "plaintext",
        "decrypted": "plaintext",
        "plain": "plaintext",
        "plaintext": "plaintext",
    }
    desired = aliases.get(requested)
    if desired is None:
        raise RuntimeError("project encryption mode must be plaintext or encrypted")
    project_id = resolve_project_id(args)
    operation = "enable" if desired == "encrypted" else "disable"
    payload = {"state": desired}
    result = request_project_write(
        "POST",
        f"/v1/projects/{project_id}/encryption/{operation}",
        payload,
        project_id,
        f"set project encryption {desired}",
        scope_type="encryption",
    )
    save_auth({"project_encryption_state": result.get("state") or desired})
    return {
        **result,
        "status": "updated",
        "message": f"Project encryption is now {result.get('state') or desired}.",
        "requested_state": desired,
    }


def default_project_slug():
    base = pathlib.Path.cwd().name.lower()
    slug = []
    previous_dash = False
    for char in base:
        if char.isalnum():
            slug.append(char)
            previous_dash = False
        elif not previous_dash:
            slug.append("-")
            previous_dash = True
    normalized = "".join(slug).strip("-")
    return normalized or "local-project"


def default_project_name(slug):
    return " ".join(part.capitalize() for part in slug.split("-") if part) or "Local project"


def cli_option(args, *names, default=None):
    for name in names:
        if name in args:
            index = args.index(name)
            if index + 1 >= len(args):
                raise RuntimeError(f"{name} requires a value")
            return args[index + 1]
    return default


def cli_flag(args, *names):
    return any(name in args for name in names)


def cli_positionals(args):
    values = []
    skip_next = False
    options_with_values = {
        "--slug",
        "--name",
        "--description",
        "--encryption",
        "--passphrase",
        "--bootstrap-token",
        "--command",
        "--default-command",
        "--display-name",
        "--device-fingerprint",
        "--container-uuid",
        "--image",
        "--image-ref",
        "--root-path",
        "--name",
        "--target",
        "--session",
        "--window",
        "--pane",
    }
    for index, value in enumerate(args):
        if skip_next:
            skip_next = False
            continue
        if value in options_with_values:
            skip_next = True
            continue
        if value.startswith("-"):
            continue
        values.append(value)
    return values


def looks_like_service_bootstrap_token(value):
    return isinstance(value, str) and value.strip().startswith("npb_")


def cli_project_create(args):
    positionals = cli_positionals(args)
    slug = cli_option(args, "--slug", default=positionals[0] if positionals else default_project_slug())
    name = cli_option(args, "--name", default=default_project_name(slug))
    encryption = cli_option(args, "--encryption", default="encrypted" if cli_flag(args, "--encrypted") else "plaintext")
    payload = {
        "slug": slug,
        "name": name,
        "description": cli_option(args, "--description", default=""),
        "encryption": encryption,
    }
    passphrase = cli_option(args, "--passphrase", default=os.environ.get("NAPSEER_PROJECT_PASSPHRASE"))
    if passphrase:
        payload["passphrase"] = passphrase
    return bootstrap_project(payload)


def parse_tmux_target(value):
    value = str(value or "").strip()
    if not value:
        return {}
    session = value
    window = ""
    pane = ""
    if ":" in session:
        session, rest = session.split(":", 1)
        if "." in rest:
            window, pane = rest.split(".", 1)
        else:
            window = rest
    return {"session": session, "window": window, "pane": pane}


def current_tmux_target():
    if not os.environ.get("TMUX"):
        return {}
    try:
        result = subprocess.run(
            ["tmux", "display-message", "-p", "#{session_name}:#{window_index}.#{pane_index}"],
            check=True,
            capture_output=True,
            text=True,
            timeout=5,
        )
        return parse_tmux_target(result.stdout.strip())
    except Exception:
        return {}


def cli_gateway_configure(args):
    positionals = cli_positionals(args)
    passphrase = (
        cli_option(args, "--passphrase", default=None)
        or os.environ.get("NAPSEER_GATEWAY_PASSPHRASE")
        or os.environ.get("NAPSEER_GATEWAY_PASSKEY")
    )
    bootstrap_token = (
        cli_option(args, "--bootstrap-token", default=None)
        or next((value for value in positionals if looks_like_service_bootstrap_token(value)), None)
        or os.environ.get("NAPSEER_SERVICE_BOOTSTRAP_TOKEN")
        or os.environ.get("NAPSEER_GATEWAY_BOOTSTRAP_TOKEN")
    )
    default_command = cli_option(args, "--command", default=cli_option(args, "--default-command", default=None))
    if bootstrap_token:
        if passphrase and vault_exists() and not gateway_is_unlocked():
            gateway_unlock(passphrase)
        if TOKEN:
            if default_command:
                gateway_tmux_configure({"default_command": default_command})
            return {**gateway_status(), "status": "configured", "message": "Gateway service token is already configured."}
        try:
            return gateway_service_preregister({
                "bootstrap_token": bootstrap_token,
                "passphrase": passphrase,
                "display_name": cli_option(args, "--name", "--display-name", default=None),
                "default_command": default_command,
                "root_path": cli_option(args, "--root-path", default=None),
                "device_fingerprint": cli_option(args, "--device-fingerprint", default=None),
                "container_uuid": cli_option(args, "--container-uuid", default=None),
                "image_ref": cli_option(args, "--image", "--image-ref", default=None),
            })
        except RuntimeError as exc:
            if "service bootstrap token is invalid or expired" not in str(exc):
                raise
            gateway_log("service_bootstrap_token_invalid", level="error", error=str(exc))
            return gateway_bootstrap_token_invalid_result()

    if not vault_exists():
        gateway_setup({"passphrase": passphrase})
    if not gateway_is_unlocked():
        gateway_unlock(passphrase or getpass.getpass("Gateway passphrase: "))

    target = parse_tmux_target(cli_option(args, "--target", default=""))
    command = default_command or ""
    if not command and sys.stdin.isatty():
        value = input(f"Default terminal command [{normalize_gateway_command()}]: ").strip()
        command = value or normalize_gateway_command()
    if not command:
        command = normalize_gateway_command()
    payload = {
        "session": cli_option(args, "--session", default=target.get("session", "")),
        "window": cli_option(args, "--window", default=target.get("window", "")),
        "pane": cli_option(args, "--pane", default=target.get("pane", "")),
        "default_command": command,
    }
    if "--target" not in args and "--session" not in args:
        payload["session"] = ""
    elif not payload["session"]:
        payload.update(current_tmux_target())
    if "--target" in args or "--session" in args:
        if not payload.get("session"):
            payload["session"] = input("tmux session: ").strip()
        if not payload.get("window"):
            value = input("tmux window, optional: ").strip()
            if value:
                payload["window"] = value
        if not payload.get("pane"):
            value = input("tmux pane, optional: ").strip()
            if value:
                payload["pane"] = value
    return gateway_tmux_configure(payload)


def mcp_gateway_configure(args):
    args = args or {}
    passphrase = (
        args.get("passphrase")
        or os.environ.get("NAPSEER_GATEWAY_PASSPHRASE")
        or os.environ.get("NAPSEER_GATEWAY_PASSKEY")
    )
    bootstrap_token = (
        args.get("bootstrap_token")
        or os.environ.get("NAPSEER_SERVICE_BOOTSTRAP_TOKEN")
        or os.environ.get("NAPSEER_GATEWAY_BOOTSTRAP_TOKEN")
    )
    default_command = args.get("default_command") or args.get("command")
    if bootstrap_token:
        if passphrase and vault_exists() and not gateway_is_unlocked():
            gateway_unlock(passphrase)
        if TOKEN:
            if default_command:
                gateway_tmux_configure({"default_command": default_command})
            return {**gateway_status(), "status": "configured", "message": "Gateway service token is already configured."}
        try:
            return gateway_service_preregister(
                {
                    "bootstrap_token": bootstrap_token,
                    "passphrase": passphrase,
                    "display_name": args.get("display_name"),
                    "default_command": default_command,
                    "root_path": args.get("root_path"),
                    "device_fingerprint": args.get("device_fingerprint"),
                    "container_uuid": args.get("container_uuid"),
                    "image_ref": args.get("image_ref"),
                }
            )
        except RuntimeError as exc:
            if "service bootstrap token is invalid or expired" not in str(exc):
                raise
            gateway_log("service_bootstrap_token_invalid", level="error", error=str(exc))
            return gateway_bootstrap_token_invalid_result()

    if not vault_exists():
        if not passphrase:
            raise RuntimeError("gateway passphrase is required to create the gateway vault")
        gateway_setup({"passphrase": passphrase, "default_command": default_command})
    elif passphrase and not gateway_is_unlocked():
        gateway_unlock(passphrase)

    target = parse_tmux_target(args.get("target", ""))
    payload = {
        "session": args.get("session", target.get("session", "")),
        "window": args.get("window", target.get("window", "")),
        "pane": args.get("pane", target.get("pane", "")),
        "default_command": default_command or normalize_gateway_command(),
    }
    if not args.get("target") and not args.get("session"):
        payload["session"] = ""
    return gateway_tmux_configure(payload)


def cli_gateway_require_unlocked(args, operation="gateway operation"):
    if not vault_exists():
        raise RuntimeError("gateway vault is not configured; run nap gateway configure first")
    if not gateway_is_unlocked():
        gateway_unlock(cli_option(args, "--passphrase", default=None) or getpass.getpass("Gateway passphrase: "))
    require_unlocked(operation)


def cli_project_claim(args):
    result = claim_account({
        "open_browser": not cli_flag(args, "--no-browser"),
        "timeout_seconds": int(cli_option(args, "--timeout", "--timeout-seconds", default="300")),
        "return_url": cli_option(args, "--return-url", default=None),
    })
    if result.get("status") == "already_claimed":
        return result
    claim_result = result.get("result") if isinstance(result.get("result"), dict) else None
    if claim_result and claim_result.get("status") == "claimed":
        status = "claimed"
        message = "Project/account claim completed and local auth was updated."
    else:
        status = "claim_pending"
        message = "Claim link created. Complete it in the browser to attach this project/account."
    return {**result, "status": status, "message": message}


def cli_configure_status():
    project_configured = bool(DEFAULT_PROJECT_ID)
    encryption = {"state": "plaintext", "updated_at": ""}
    if project_configured:
        try:
            encryption = project_encryption_status({})
        except Exception:
            encryption = {"state": AUTH.get("project_encryption_state") or "unknown", "updated_at": ""}
    return {
        "status": "configured" if project_configured else "not_configured",
        "message": "Project is configured for this directory." if project_configured else "No project is configured for this directory.",
        "cwd": str(pathlib.Path.cwd()),
        **state_dir_status_payload(),
        "auth_path": str(AUTH_PATH),
        "auth_configured": bool(TOKEN),
        "account_mode": AUTH.get("account_mode"),
        "project_configured": project_configured,
        "project_id": DEFAULT_PROJECT_ID or "",
        "project_slug": load_public_auth_file().get("project_slug", ""),
        "encryption_state": encryption.get("state") or "unknown",
        "encryption_updated_at": encryption.get("updated_at") or "",
        "token_expires_at": TOKEN_EXPIRES_AT,
        "next": {
            "gateway_start": "nap gateway start",
            "gateway_configure": "nap gateway configure",
            "gateway_logs": "nap gateway logs",
            "create_project": "nap project create",
            "project_encryption": "nap project encryption status",
            "update": "nap update",
        },
    }


def iso_now():
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def iso_after_days(days):
    return (datetime.now(timezone.utc) + timedelta(days=days)).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def iso_timestamp_after_seconds(seconds):
    return (datetime.now(timezone.utc) + timedelta(seconds=seconds)).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def get_project_signing_key(project_id):
    key = request_json("GET", f"/v1/projects/{project_id}/signing-key")
    save_auth({"project_signing_key_fingerprint": key.get("fingerprint")})
    return key


def register_project_signing_key(args):
    project_id = resolve_project_id(args)
    key = request_project_write(
        "PUT",
        f"/v1/projects/{project_id}/signing-key",
        {"public_key": auth_public_key(), "label": args.get("label", "local-project-key")},
        project_id,
        "register project signing key",
    )
    save_auth({"project_signing_key_fingerprint": key.get("fingerprint")})
    return key


def canonical_schedule_payload(args):
    project_id = resolve_project_id(args)
    fingerprint = AUTH.get("project_signing_key_fingerprint")
    if not fingerprint:
        try:
            fingerprint = get_project_signing_key(project_id).get("fingerprint")
        except Exception:
            fingerprint = register_project_signing_key({}).get("fingerprint")
    payload = {
        "schema": "napseer.schedule.v1",
        "project_id": project_id,
        "schedule_id": args.get("schedule_id") or str(uuid.uuid4()),
        "version": int(args.get("version", 1)),
        "action": args.get("action", "upsert"),
        "name": args["name"],
        "cron_expr": args["cron_expr"],
        "timezone": args.get("timezone", "UTC"),
        "target_worker_id": args.get("target_worker_id"),
        "target_agent_id": args.get("target_agent_id") or AUTH.get("agent_id"),
        "instruction_text": args["instruction_text"],
        "enabled": bool(args.get("enabled", True)),
        "created_at": args.get("created_at") or iso_now(),
        "expires_at": args.get("expires_at") or iso_after_days(int(args.get("expires_in_days", 30))),
        "key_fingerprint": fingerprint,
        "payload": args.get("payload") or {},
    }
    return json.dumps(payload, separators=(",", ":"), sort_keys=True)


def create_signed_schedule(args):
    project_id = resolve_project_id(args)
    signed_payload = canonical_schedule_payload(args)
    signature = sign_with_auth_key(SCHEDULE_SIGNATURE_NAMESPACE, signed_payload)
    return request_project_write(
        "POST",
        f"/v1/projects/{project_id}/schedules",
        {"signed_payload": signed_payload, "signature": signature},
        project_id,
        "create signed schedule",
    )


def get_node_by_path(args, allow_agent=False):
    project_id = resolve_project_id(args)
    path = args["path"]
    if not allow_agent:
        reject_agent_namespace_path(path)
    return request_json(
        "GET",
        f"/v1/projects/{project_id}/nodes/by-path?{urllib.parse.urlencode({'path': path})}",
    )


def try_get_node_by_path(path, allow_agent=False):
    try:
        return get_node_by_path({"path": path}, allow_agent=allow_agent)
    except RuntimeError as exc:
        if "HTTP 404" in str(exc):
            return None
        raise


def node_payload_from_args(args, existing=None):
    parts = path_parts(args["path"])
    payload = {}
    if not existing or "path" in args:
        payload["folder_path"] = parts["folder_path"]
        payload["name"] = parts["name"]
    for source, target in [
        ("type", "type"),
        ("content_text", "content_text"),
        ("tags", "tags"),
        ("aliases", "aliases"),
        ("links", "links"),
        ("metadata", "metadata"),
    ]:
        if source in args:
            payload[target] = args[source]
    if "type" not in payload and not existing:
        payload["type"] = "note"
    if "content_text" not in payload and not existing:
        payload["content_text"] = ""
    if "tags" not in payload and not existing:
        payload["tags"] = []
    if "aliases" not in payload and not existing:
        payload["aliases"] = []
    if "links" not in payload and not existing:
        payload["links"] = []
    if "metadata" not in payload and not existing:
        payload["metadata"] = {}
    return payload


def upsert_node(args):
    reject_agent_namespace_path(args["path"])
    project_id = resolve_project_id(args)
    existing = try_get_node_by_path(args["path"])
    if existing:
        updated = request_project_write(
            "PATCH",
            f"/v1/projects/{project_id}/nodes/{existing['id']}",
            node_payload_from_args(args, existing=existing),
            project_id,
            f"update node {existing['full_path']}",
            "path",
            existing["full_path"],
        )
        index_node(updated)
        return {"created": False, "node": updated}
    write_path = normalize_node_path(args["path"])
    created = request_project_write(
        "POST",
        f"/v1/projects/{project_id}/nodes",
        node_payload_from_args(args),
        project_id,
        f"create node {args['path']}",
        "path",
        write_path,
    )
    index_node(created)
    return {"created": True, "node": created}


def update_node_by_path(args):
    reject_agent_namespace_path(args["path"])
    project_id = resolve_project_id(args)
    existing = get_node_by_path({"path": args["path"]})
    updated = request_project_write(
        "PATCH",
        f"/v1/projects/{project_id}/nodes/{existing['id']}",
        node_payload_from_args(args, existing=existing),
        project_id,
        f"update node {existing['full_path']}",
        "path",
        existing["full_path"],
    )
    index_node(updated)
    return {"updated": True, "node": updated}


def archive_node_by_path(args):
    reject_agent_namespace_path(args["path"])
    project_id = resolve_project_id(args)
    existing = get_node_by_path({"path": args["path"]})
    if args.get("dry_run"):
        return {"ok": True, "changed": False, "dry_run": True, "archived": False, "paths": [existing["full_path"]]}
    request_project_write(
        "DELETE",
        f"/v1/projects/{project_id}/nodes/{existing['id']}",
        None,
        project_id,
        f"archive node {existing['full_path']}",
        "path",
        existing["full_path"],
    )
    remove_indexed_node(existing["id"])
    return {"ok": True, "changed": True, "dry_run": False, "archived": True, "paths": [existing["full_path"]], "id": existing["id"]}


def delete_archived_node(args):
    node_id = str(args.get("id") or "").strip()
    path = str(args.get("path") or "").strip()
    project_id = resolve_project_id(args)
    if not node_id:
        if not path:
            raise RuntimeError("id or path is required")
        matches = list_project_nodes({"archived_only": True, "limit": 200}).get("items", [])
        match = next((node for node in matches if node.get("full_path") == path), None)
        if not match:
            raise RuntimeError(f"archived node not found: {path}")
        node_id = match["id"]
        path = match.get("full_path") or path
    request_project_write(
        "DELETE",
        f"/v1/projects/{project_id}/nodes/{node_id}?hard=true",
        None,
        project_id,
        f"permanently delete archived node {path or node_id}",
    )
    remove_indexed_node(node_id)
    return {"ok": True, "changed": True, "deleted": True, "id": node_id, "path": path or None}


def link_nodes(args):
    reject_agent_namespace_path(args["source_path"], "source_path")
    reject_agent_namespace_path(args["target_path"], "target_path")
    project_id = resolve_project_id(args)
    source = get_node_by_path({"path": args["source_path"]})
    target = get_node_by_path({"path": args["target_path"]})
    relation = args.get("relation", "references")
    links = source.get("links") or []
    if not isinstance(links, list):
        links = []

    link = {"path": target["full_path"], "relation": relation}
    created = not any(
        item.get("path") == link["path"] and item.get("relation", "references") == relation
        for item in links
        if isinstance(item, dict)
    )
    if created:
        links.append(link)
        updated = request_project_write(
            "PATCH",
            f"/v1/projects/{project_id}/nodes/{source['id']}",
            {"links": links},
            project_id,
            f"link node {source['full_path']}",
            "path",
            source["full_path"],
        )
        index_node(updated)
    else:
        updated = source

    return {
        "created": created,
        "relation": relation,
        "source": {"id": source["id"], "full_path": source["full_path"]},
        "target": {"id": target["id"], "full_path": target["full_path"]},
        "updated_node": updated,
    }


def get_backlinks_by_path(args):
    reject_agent_namespace_path(args["path"])
    project_id = resolve_project_id(args)
    target = get_node_by_path({"path": args["path"]})
    backlinks = request_json("GET", f"/v1/projects/{project_id}/nodes/{target['id']}/backlinks")
    return {"target": {"id": target["id"], "full_path": target["full_path"]}, **backlinks}


def list_project_nodes(args):
    project_id = resolve_project_id(args)
    allowed = {"tag", "folder_path", "q", "limit", "cursor", "updated_before", "updated_after", "type", "include_archived", "archived_only"}
    base_query = {key: value for key, value in args.items() if key in allowed and value not in (None, "")}
    raw_q = str(base_query.get("q") or "").strip()
    if raw_q and not base_query.get("cursor"):
        query_analysis = analyze_search_query(raw_q)
        limit = max(1, min(int(base_query.get("limit", 50)), 200))
        collected = []
        diagnostics = {"server_queries": []}
        for server_query in server_search_queries(query_analysis):
            if len(unique_nodes(collected)) >= limit:
                break
            query = dict(base_query)
            query["q"] = server_query
            query["limit"] = max(1, limit - len(unique_nodes(collected)))
            suffix = f"?{urllib.parse.urlencode(query)}"
            page = request_json("GET", f"/v1/projects/{project_id}/nodes{suffix}")
            items = filter_project_nodes(page.get("items", []))
            diagnostics["server_queries"].append({"q": server_query, "matched": len(items)})
            for node in items:
                node = dict(node)
                node["matched_query"] = server_query
                collected.append(node)
        return {
            "items": unique_nodes(collected)[:limit],
            "query_analysis": query_analysis,
            "diagnostics": diagnostics,
        }

    query = urllib.parse.urlencode(base_query)
    suffix = f"?{query}" if query else ""
    result = request_json("GET", f"/v1/projects/{project_id}/nodes{suffix}")
    result["items"] = filter_project_nodes(result.get("items", []))
    return result


