def tool_side_effect(name):
    if name in READ_ONLY_TOOLS:
        return "none"
    if name in LOCAL_FILE_TOOLS:
        return "local-file"
    if name in PROCESS_CONTROL_TOOLS:
        return "process-control"
    if name in TERMINAL_CONTROL_TOOLS:
        return "terminal-control"
    return "remote-write"


def tool_auth_mode(name):
    category = tool_category(name)
    if name in {"nap_apropos", "nap_man", "nap_contract", "nap_update_status"}:
        return "public"
    if category == "gateway":
        return "gateway-vault" if name in SECRET_ACCEPTING_TOOLS or name.startswith("nap_gateway_") else "local-only"
    if name in {"nap_grep_local", "nap_index_status", "nap_index_clear", "nap_reindex_project", "nap_ui_open", "nap_update_self"}:
        return "local-only"
    if category in {"explore", "update", "coordination", "agent", "project", "schedules", "maintenance"}:
        return "project-auth"
    return "local-auth"


def tool_contract_metadata(name):
    side_effect = tool_side_effect(name)
    dry_run_supported = name in {"nap_rm", "nap_mv", "nap_mv_folder", "nap_bulk"}
    return {
        "contract_version": CONTRACT_VERSION,
        "category": tool_category(name),
        "auth_mode": tool_auth_mode(name),
        "side_effect": side_effect,
        "lock_policy": "auto-project" if name in AUTO_LOCK_TOOLS else "none",
        "secret_policy": "accepts-local-secret" if name in SECRET_ACCEPTING_TOOLS else "accepts-no-secrets",
        "returns_secrets": False,
        "idempotency": "safe" if side_effect == "none" else "not-idempotent",
        "dangerous": side_effect in {"process-control", "terminal-control"} or name in SECRET_ACCEPTING_TOOLS,
        "dry_run_supported": dry_run_supported,
        "replaces": NEW_TOOL_REPLACES.get(name),
        "requires_local": tool_auth_mode(name) != "public",
    }


def tool_card(tool, include_schema=False):
    name = tool["name"]
    card = {
        "name": name,
        "category": tool_category(name),
        "description": tool.get("description", ""),
        "metadata": tool_contract_metadata(name),
    }
    if include_schema:
        card["inputSchema"] = tool.get("inputSchema", {})
    return card


def contract_profile(args=None):
    args = args or {}
    include_tools = bool(args.get("include_tools", True))
    include_schemas = bool(args.get("include_schemas", False))
    tool_items = tools()
    profile = {
        "contract_version": CONTRACT_VERSION,
        "wrapper": {
            "name": SCRIPT_NAME,
            "path": str(SCRIPT_PATH),
            "dependencies": list(SCRIPT_DEPENDENCY_NAMES),
        },
        "project_id": DEFAULT_PROJECT_ID,
        "auth": {
            "base_url": BASE_URL,
            "has_token": bool(TOKEN),
            "token_expires_at": TOKEN_EXPIRES_AT,
            "default_auth_mode": "project-auth" if TOKEN else "local-only",
        },
        "tool_count": len(tool_items),
        "categories": list(TOOL_CATEGORIES.keys()),
        "metadata_fields": [
            "contract_version",
            "category",
            "auth_mode",
            "side_effect",
            "lock_policy",
            "secret_policy",
            "returns_secrets",
            "idempotency",
            "dangerous",
            "dry_run_supported",
            "replaces",
            "requires_local",
        ],
        "public_vs_local_boundary": {
            "public_mcp": "Discovery only. Do not send bearer tokens, private keys, gateway passphrases, project-private content, terminal plaintext, or derived keys.",
            "local_mcp": "Authenticated wrapper that keeps tokens, project id, vault material, and local index state on this machine.",
            "relay": "Relay authorizes communication between pairs and authenticates requests; peer secrets and terminal plaintext stay outside relay/backend.",
        },
        "limits": {
            "explore_tools_default_limit": 50,
            "explore_tools_max_limit": 200,
            "include_schemas_default": False,
            "content_is_bounded_by_tool": True,
        },
    }
    if include_tools:
        profile["tools"] = [tool_card(tool, include_schemas) for tool in tool_items]
    return profile


def tools():
    items = []
    for tool in raw_tools():
        item = dict(tool)
        category = tool_category(item["name"])
        if not item.get("description", "").startswith("["):
            item["description"] = f"[{category}] {item.get('description', '')}"
        item["napseer"] = tool_contract_metadata(item["name"])
        items.append(item)
    return items


def explore_tools(args):
    category = str(args.get("category") or "").strip().lower()
    query = str(args.get("q") or "").strip().lower()
    include_schemas = bool(args.get("include_schemas", False))
    limit = max(1, min(int(args.get("limit", 50)), 200))
    grouped = {key: [] for key in TOOL_CATEGORIES}
    grouped["other"] = []
    tool_by_name = {tool["name"]: tool for tool in tools()}
    ordered_names = []
    for names in TOOL_CATEGORIES.values():
        ordered_names.extend(names)
    ordered_names.extend(name for name in tool_by_name if name not in ordered_names)
    for name in ordered_names:
        tool = tool_by_name.get(name)
        if not tool:
            continue
        tool_category_name = tool_category(name)
        if category and category != tool_category_name:
            continue
        haystack = f"{name} {tool.get('description', '')}".lower()
        if query and query not in haystack:
            continue
        card = tool_card(tool, include_schemas)
        grouped.setdefault(tool_category_name, []).append(card)
    grouped = {key: value[:limit] for key, value in grouped.items() if value}
    return {
        "contract_version": CONTRACT_VERSION,
        "categories": list(TOOL_CATEGORIES.keys()),
        "tools_are_flat_in_mcp": True,
        "include_schemas": include_schemas,
        "metadata_fields": contract_profile({"include_tools": False})["metadata_fields"],
        "groups": grouped,
    }


def man_tool(args):
    name = str(args.get("tool") or args.get("name") or "").strip()
    if name in OLD_TOOL_RENAMES:
        replacement = OLD_TOOL_RENAMES[name]
        return {
            "ok": False,
            "tool": name,
            "renamed_to": replacement,
            "message": f"{name} was renamed to {replacement}; call {replacement} instead",
        }
    for tool in tools():
        if tool["name"] == name:
            return tool_card(tool, include_schema=True)
    raise RuntimeError(f"unknown tool: {name}")


