def lint_memory(args):
    limit = max(1, min(int(args.get("limit", 200)), 500))
    result = list_project_nodes({"limit": limit, "include_content": False})
    warnings = []
    for node in result.get("items", []):
        for link in node.get("links") or []:
            if not isinstance(link, dict) or not link.get("path"):
                continue
            try:
                get_node_by_path({"path": link["path"]}, allow_agent=is_agent_namespace_path(link["path"]))
            except Exception as exc:
                warnings.append({
                    "type": "broken_link",
                    "source": node.get("full_path"),
                    "target": link.get("path"),
                    "error": str(exc),
                })
    return {"ok": not warnings, "checked": len(result.get("items", [])), "warnings": warnings, "next_cursor": result.get("next_cursor")}


